WordHunterWoW_QuestEN[9023] = { title = "The Perfect Poison", description = "My brother and I run the poison operations out of the manor Ravenholdt.\n\nLord Ravenholdt tasked me to track down a new and extremely effective poison compound that can be crafted from the venom sacs of the inhabitants of Zul'Gurub and the Ruins of Ahn'Qiraj.\n\nThere are two particularly venomous beasts residing in those blasted ruins that possess what it is that we might be looking for, {class}. Bring me a venom sac from the beasts Kurinnaxx and Venoxis and we would be eternally grateful.", objectives = "Dirk Thunderwood at Cenarion Hold wants you to bring him Venoxis's Venom Sac and Kurinnaxx's Venom Sac.", progress = "This ain't no smash and grab job, {name}. You're gonna need to bring friends.", completion = "Ravenholdt thanks you, hero! Take your pick!" }
WordHunterWoW_QuestEN[9024] = { title = "Aristan's Hunch", description = "I've got it! Have you smelled the new fragrance on the wind? The new colognes and perfumes that have come into fashion? Our guards wouldn't neglect their duties so easily.\n\nThat is, unless their thinking has been clouded by some foul alchemy.\n\nThere is only one way to be sure - bring a bottle of cologne and perfume to Morgan Pestle, and tell him my suspicions. I will reimburse you for their purchase when you return.", objectives = "Bring 1 Cologne Bottle and 1 Perfume Bottle to Morgan Pestle in the Trade District of Stormwind.", progress = "Something I can help you with?", completion = "I understand Aristan's concerns, but I really think he's overreacting. Let young men and women do what they will. I think Aristan has forgotten what it means to be young and in love.\n\nBut it would be better not to tell him that. We'll humor him." }
WordHunterWoW_QuestEN[9025] = { title = "Morgan's Discovery", description = "Well, I'll be. It looks like Aristan might be on to something after all. I found traces of substances used in love potions and insidious mind-altering draughts.\n\nIt isn't unheard of for perfumes to have some of them, but a few of the ingredients I detected... Smells funny.", objectives = "Return to Aristan Mottar outside the bank in Stormwind's Trade District.", completion = "While I thought this would be the case, finding out that my suspicions were correct is still unsettling. We must carefully consider our next move.\n\nHere, to repay you for the purchase of the cologne and perfume." }
WordHunterWoW_QuestEN[9026] = { title = "Tracing the Source", description = "We've got to find the source. I've seen a lot more people than usual - guards included - going in and out of The Gilded Rose. Talk to Allison. If she's selling them, she can tell you where they came from.", objectives = "Speak with Innkeeper Allison at The Gilded Rose in Stormwind's Trade District.", completion = "Oh yes, I just got the perfume and cologne in stock recently. It's been selling so well, I don't know how long I can keep it on the shelves.\n\nIf you ask me, it's kind of boring. Everyone smelling the same? It smells great, but still." }
WordHunterWoW_QuestEN[9027] = { title = "Tracing the Source", description = "Something funny about the cologne? It's possible. I've never seen so many people after one product like this.\n\nLook, if there's something wrong with it, I want to know, too. I bought my supply from a merchant named Evert Sorisam. He's new in town.\n\nHe mentioned he had some goods he was going to deliver to The Finest Thread.", objectives = "Speak with Evert Sorisam at The Finest Thread along Stormwind's Canals.", completion = "Yes, of course. Those fragrances are the hottest items this season. You must be the fifth or sixth person this hour to inquire about them.\n\nI'm afraid my supplies are all sold out. If you'd like some, you should speak with Allison, the innkeeper of The Gilded Rose.\n\nYou shouldn't waste any time, though. I think you'll find the cologne will be irresistible." }
WordHunterWoW_QuestEN[9028] = { title = "The Source Revealed", description = "What? Treason? No, no. I assure you, my intentions are completely harmless.\n\nIs it so wrong to help those who wish to ease the painful ritual of courtship? Come, that is no crime.\n\nAnd to prove that I mean no harm, I will even tell you my source.\n\nThey were shipped to me by a Staffron Lerent, an apothecary of some sort. I never spoke with him.\n\nOur goblin middle man said that he worked in the foothills over Hillsbrad past that mysterious Ravenholdt Manor. I wish you luck in finding him.", objectives = "Find Apothecary Staffron Lerent in the Hillsbrad Foothills behind Ravenholdt Manor.", completion = "Yes, I made those fragrances. Wonderful smell, isn't it? Irresistible.\n\nOnce the warriors of Alliance and Horde alike are smitten with these feelings of love, they will be powerless to stop the rise of the Shadow Council.\n\nThey will be weakened, unprepared. As they worry for their loved ones, they will lose their edge.\n\nThe solution was so simple. Why did it take me so long to come upon it? The weakness of all is through the heart. And there is nothing you can do to stop the inevitable." }
WordHunterWoW_QuestEN[9029] = { title = "A Bubbling Cauldron", description = "", objectives = "A pleasant smell wafts up from the cauldron.", completion = "A pleasant smell wafts up from the cauldron." }
WordHunterWoW_QuestEN[9032] = { title = "Bodley's Unfortunate Fate", description = "The medallion contained Valthalak's soul?  It's no surprise it was guarded by such a powerful curse.\n\nLocating Bodley presents a bit of a problem.  Last time I heard of him, he was preparing to venture back into Blackrock Spire.  He was never heard of again.\n\nSeek him out in Blackrock Mountain, though I'm afraid to say he's probably dead by now.  I suggest taking the goblin's device with you, friend.", objectives = "Travel to Blackrock Mountain and use the Extra-Dimensional Ghost Revealer to find Bodley near Blackrock Spire.", completion = "I am so glad that you can see me. Finally someone to talk to!\n\nWill you help us, {name}? Help to undo the wrong that we perpetrated and put things to right? If its true that you already have the Top Piece of Lord Valthalaks Amulet, then I think I can point you in the right direction to acquire the other two parts, reunite them and put an end to all of this.\n\nOh, by the way, hello, my name is Bodley. Nice to meet you!" }
WordHunterWoW_QuestEN[9033] = { title = "Echoes of War", description = "Five years since the last war...\n\nTens of thousands of lives were lost and for what? The threat was never fully extinguished.\n\nAnd so the Lich King stirs once more... His yes-man, Kel'Thuzad, amassing for another attack upon our lands.\n\nWe will not allow it! Prove your dedication. Prove that you are willing to risk life and limb to stop this madness and the combined might of the Dawn and the Crusade will be at your beck and call.\n\nEnter Naxxramas and destroy the Scourge within...", objectives = "Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands wants you to slay 5 Living Monstrosities, 5 Stoneskin Gargoyles, 8 Deathknight Captains and 3 Venom Stalkers.", completion = "A job well done! You will be rewarded via the services of the men and women at Light's Hope." }
WordHunterWoW_QuestEN[9034] = { title = "Dreadnaught Breastplate", description = "During your battles with the Scourge in Naxxramas, should you come across desecrated battlements and wartorn plate scraps, return them to me and I shall craft for you a piece of armor worn by heroes.", objectives = "Korfax at Light's Hope Chapel in the Eastern Plaguelands will make a Dreadnaught Breastplate if you bring him the following items: 1 Desecrated Breastplate, 25 Wartorn Plate Scraps, 4 Arcanite Bars and 2 Nexus Crystals.", progress = "Naxxramas holds ancient evils, {name}.", completion = "Let them know fear once more, {class}. Let them feel no mercy." }
WordHunterWoW_QuestEN[9036] = { title = "Dreadnaught Legplates", description = "During your battles with the Scourge in Naxxramas, should you come across desecrated battlements and wartorn plate scraps, return them to me and I shall craft for you a piece of armor worn by heroes.", objectives = "Korfax at Light's Hope Chapel in the Eastern Plaguelands will make Dreadnaught Legplates if you bring him the following items: 1 Desecrated Legplates, 20 Wartorn Plate Scraps, 4 Arcanite Bars and 3 Cured Rugged Hides.", progress = "Remember those that fell before you, {name}.", completion = "Crush them beneath your feet." }
WordHunterWoW_QuestEN[9037] = { title = "Dreadnaught Helmet", description = "During your battles with the Scourge in Naxxramas, should you come across desecrated battlements and wartorn plate scraps, return them to me and I shall craft for you a piece of armor worn by heroes.", objectives = "Korfax at Light's Hope Chapel in the Eastern Plaguelands will make a Dreadnaught Helmet if you bring him the following items: 1 Desecrated Helmet, 15 Wartorn Plate Scraps, 5 Arcanite Bars and 1 Nexus Crystal.", progress = "The head is the most sensitive part of most bodies.", completion = "Remember, you're not really dead if your brain is still in your head. Keep this thing on at all times..." }
WordHunterWoW_QuestEN[9038] = { title = "Dreadnaught Pauldrons", description = "During your battles with the Scourge in Naxxramas, should you come across desecrated battlements and wartorn plate scraps, return them to me and I shall craft for you a piece of armor worn by heroes.", objectives = "Korfax at Light's Hope Chapel in the Eastern Plaguelands will make Dreadnaught Pauldrons if you bring him the following items: 1 Desecrated Pauldrons, 12 Wartorn Plate Scraps, 2 Arcanite Bars and 3 Cured Rugged Hides.", progress = "The secret is in the banding.", completion = "I've always thought that the pauldrons are the most pronounced pieces of a suit of armor. I'm sure you agree." }
WordHunterWoW_QuestEN[9039] = { title = "Dreadnaught Sabatons", description = "During your battles with the Scourge in Naxxramas, should you come across desecrated battlements and wartorn plate scraps, return them to me and I shall craft for you a piece of armor worn by heroes.", objectives = "Korfax at Light's Hope Chapel in the Eastern Plaguelands will make Dreadnaught Sabatons if you bring him the following items: 1 Desecrated Sabatons, 12 Wartorn Plate Scraps, 2 Arcanite Bars and 3 Cured Rugged Hides.", progress = "Never underestimate a good pair of boots. Especially when they're made by Korfax!", completion = "In the last war, I watched Mograine crack open the fetid skulls of the living dead with these very boots." }
WordHunterWoW_QuestEN[9040] = { title = "Dreadnaught Gauntlets", description = "During your battles with the Scourge in Naxxramas, should you come across desecrated battlements and wartorn plate scraps, return them to me and I shall craft for you a piece of armor worn by heroes.", objectives = "Korfax at Light's Hope Chapel in the Eastern Plaguelands will make Dreadnaught Gauntlets if you bring him the following items: 1 Desecrated Gauntlets, 8 Wartorn Plate Scraps, 1 Arcanite Bar and 5 Cured Rugged Hides.", progress = "These gauntlets are made to grip a fine weapon.", completion = "May your grip tighten around the neck of Kel'Thuzad.\n\n<Korfax makes a wrenching motion with his hands.>" }
WordHunterWoW_QuestEN[9041] = { title = "Dreadnaught Waistguard", description = "During your battles with the Scourge in Naxxramas, should you come across desecrated battlements and wartorn plate scraps, return them to me and I shall craft for you a piece of armor worn by heroes.", objectives = "Korfax at Light's Hope Chapel in the Eastern Plaguelands will make a Dreadnaught Waistguard if you bring him the following items: 1 Desecrated Waistguard, 8 Wartorn Plate Scraps, 1 Arcanite Bar and 5 Cured Rugged Hides.", progress = "The belt is both a fashion statement and a powerful piece of protective gear.", completion = "Use it as a noose for your enemies. Also, wear it out to your local goblin disco. You will be the talk of the town!" }
WordHunterWoW_QuestEN[9042] = { title = "Dreadnaught Bracers", description = "During your battles with the Scourge in Naxxramas, should you come across desecrated battlements and wartorn plate scraps, return them to me and I shall craft for you a piece of armor worn by heroes.", objectives = "Korfax at Light's Hope Chapel in the Eastern Plaguelands will make Dreadnaught Bracers if you bring him the following items: 1 Desecrated Bracers, 6 Wartorn Plate Scraps, 1 Arcanite Bar and 1 Nexus Crystal.", progress = "The wrist is the second most vulnerable spot on a body... Or is it the fourth?", completion = "Remember, the wrist is the fifth most vulnerable spot on a body! Protect your wrists and they'll definitely protect your elbows - maybe." }
WordHunterWoW_QuestEN[9043] = { title = "Redemption Tunic", description = "You will find the remnants of our fallen heroes on the corpses of the Lords of Naxxramas. Bring those desecrated keepsakes to me along with wartorn plate scraps and crafting materials capable of revitalizing the cursed armor and I shall craft a fine piece of armor for you.", objectives = "Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands will make a Redemption Tunic if you bring him the following: 1 Desecrated Tunic, 25 Wartorn Plate Scraps, 4 Arcanite Bars and 3 Cured Rugged Hides.", progress = "My orders come from on high, {name}.", completion = "Wear it in good health, {class}." }
WordHunterWoW_QuestEN[9044] = { title = "Redemption Legguards", description = "You will find the remnants of our fallen heroes on the corpses of the Lords of Naxxramas. Bring those desecrated keepsakes to me along with wartorn plate scraps and crafting materials capable of revitalizing the cursed armor and I shall craft a fine piece of armor for you.", objectives = "Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands will make a pair of Redemption Legguards if you bring him the following: 1 Desecrated Legguards, 20 Wartorn Plate Scraps, 4 Arcanite Bars and 2 Nexus Crystals.", progress = "You will not find a better suited pair of legguards for a holy warrior.", completion = "The balance between melee and magic is kept tightly in check with these legguards." }
WordHunterWoW_QuestEN[9045] = { title = "Redemption Headpiece", description = "You will find the remnants of our fallen heroes on the corpses of the Lords of Naxxramas. Bring those desecrated keepsakes to me along with wartorn plate scraps and crafting materials capable of revitalizing the cursed armor and I shall craft a fine piece of armor for you.", objectives = "Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands will make a Redemption Headpiece if you bring him the following: 1 Desecrated Headpiece, 15 Wartorn Plate Scraps, 5 Arcanite Bars and 2 Cured Rugged Hides.", progress = "<Eligor looks up at you and then returns to his conversation.>", completion = "<Eligor points to his head.>\n\nKeep it covered, {class}." }
WordHunterWoW_QuestEN[9046] = { title = "Redemption Spaulders", description = "You will find the remnants of our fallen heroes on the corpses of the Lords of Naxxramas. Bring those desecrated keepsakes to me along with wartorn plate scraps and crafting materials capable of revitalizing the cursed armor and I shall craft a fine piece of armor for you.", objectives = "Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands will make a pair of Redemption Spaulders if you bring him the following: 1 Desecrated Spaulders, 12 Wartorn Plate Scraps, 2 Arcanite Bars and 2 Nexus Crystals.", progress = "Can you not see that we are in the middle of something, {name}?", completion = "Any {class} will tell you that the brunt of their power comes from the shoulders. The bigger the better..." }
WordHunterWoW_QuestEN[9047] = { title = "Redemption Boots", description = "You will find the remnants of our fallen heroes on the corpses of the Lords of Naxxramas. Bring those desecrated keepsakes to me along with wartorn plate scraps and crafting materials capable of revitalizing the cursed armor and I shall craft a fine piece of armor for you.", objectives = "Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands will make Redemption Boots if you bring him the following: 1 Desecrated Boots, 12 Wartorn Plate Scraps, 2 Arcanite Bars and 3 Cured Rugged Hides.", progress = "You must provide me with what I have asked if I am to begin crafting.", completion = "These boots will protect your feet against the attacks of very short Scourge." }
WordHunterWoW_QuestEN[9048] = { title = "Redemption Handguards", description = "You will find the remnants of our fallen heroes on the corpses of the Lords of Naxxramas. Bring those desecrated keepsakes to me along with wartorn plate scraps and crafting materials capable of revitalizing the cursed armor and I shall craft a fine piece of armor for you.", objectives = "Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands will make Redemption Handguards if you bring him the following: 1 Desecrated Handguards, 8 Wartorn Plate Scraps, 1 Arcanite Bar and 5 Cured Rugged Hides.", progress = "You must provide me with what I have asked if I am to begin crafting.", completion = "Let the Light channel through these handguards and strike down your foes!" }
WordHunterWoW_QuestEN[9049] = { title = "Redemption Girdle", description = "You will find the remnants of our fallen heroes on the corpses of the Lords of Naxxramas. Bring those desecrated keepsakes to me along with wartorn plate scraps and crafting materials capable of revitalizing the cursed armor and I shall craft a fine piece of armor for you.", objectives = "Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands will make a Redemption Girdle if you bring him the following: 1 Desecrated Girdle, 8 Wartorn Plate Scraps, 1 Arcanite Bar and 3 Nexus Crystals.", progress = "You must provide me with what I have asked if I am to begin crafting.", completion = "This girdle will serve two functions: 1) It will protect and guide you against the Scourge and 2) Make you look 20 pounds lighter." }
WordHunterWoW_QuestEN[9050] = { title = "Redemption Wristguards", description = "You will find the remnants of our fallen heroes on the corpses of the Lords of Naxxramas. Bring those desecrated keepsakes to me along with wartorn plate scraps and crafting materials capable of revitalizing the cursed armor and I shall craft a fine piece of armor for you.", objectives = "Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands will make Redemption Wristguards if you bring him the following: 1 Desecrated Wristguards, 6 Wartorn Plate Scraps, 1 Arcanite Bar and 2 Cured Rugged Hides.", progress = "You must provide me with what I have asked if I am to begin crafting.", completion = "These are exceptionally cost effective to construct, but be warned, they may take on rust if you splash around in them too much." }
WordHunterWoW_QuestEN[9051] = { title = "Toxic Test", description = "The toxin you helped me create is for a special purpose.  The great devilsaurs of the crater make it dangerous to hunt and difficult for me to survive.  Even if I possessed the necessary strength, killing a devilsaur simply allows another to move into its territory.\n\nTake this poisoned barb and stab it deep into a living devilsaur.  The toxin should pacify the creature, though I do not know how quickly...", objectives = "Stab a Devilsaur with the Devilsaur Barb. Return to Torwa Pathfinder in Un'Goro Crater when you have completed this task.", progress = "Were you able to pacify the great beast?", completion = "Thank you, {name}.  You are brave and wise.\n\nTell me, how did the devilsaur react to the toxin?" }
WordHunterWoW_QuestEN[9052] = { title = "Bloodpetal Poison", description = "I would ask you to help me create a toxin of sorts, to pacify a great creature living here in the crater.  It is not deadly, and only the keen eyes of a {class} can hope to collect the ingredients.\n\nYou can find the bloodcap mushrooms growing within the bloodpetal sprouts all across the crater.  Gorishi stings are from the giant flying wasps inside and around the Slithering Scar, located in the southern part of the crater.", objectives = "Collect 8 Bloodcap and 8 Gorishi Stings, and return to Torwa Pathfinder in Un'Goro Crater.", progress = "Have you met with success?", completion = "The ingredients at last!\n\nWith the Un'Goro soil I have collected, the toxin is easily concocted..." }
WordHunterWoW_QuestEN[9053] = { title = "A Better Ingredient", description = "It is as I feared -- the toxin is simply too weak for such a powerful creature.\n\nIf we are to create a toxin of high enough potency, you must venture to the bottom of the Temple of Atal'Hakkar, unlock the secrets of the altar and recover a putrid vine from the guardian there.  The temple is dangerous, and it would behoove you to bring friends.\n\nReturn to me when this is done.", objectives = "Retrieve a Putrid Vine from the guardian at the bottom of the Sunken Temple and return to Torwa Pathfinder.", progress = "Have you recovered the vine?", completion = "At last, the toxin can be created in full.  I dare not require you to inflict it upon the creature again, as I have asked too much already.\n\nYou have my thanks and respect.  May you be well in your travels, {name}." }
WordHunterWoW_QuestEN[9054] = { title = "Cryptstalker Tunic", description = "I have discovered a use for the carapace of the crypt fiend. I am able to fashion an extremely light and very deadly set of armor by combining the fragments with some of the desecrated magical armors lost in Naxxramas.\n\nBring me the items I require and I shall fashion for you a suit of armor the likes of which has never before been seen in our world!", objectives = "Huntsman Leopold at Light's Hope Chapel in the Eastern Plaguelands will make a Cryptstalker Tunic if you bring him the following: 1 Desecrated Tunic, 25 Wartorn Chain Scraps, 4 Arcanite Bars and 3 Cured Rugged Hides.", progress = "Do you have the items I asked for, {class}?", completion = "They will fear you, {name}." }
WordHunterWoW_QuestEN[9055] = { title = "Cryptstalker Legguards", description = "I have discovered a use for the carapace of the crypt fiend. I am able to fashion an extremely light and very deadly set of armor by combining the fragments with some of the desecrated magical armors lost in Naxxramas.\n\nBring me the items I require and I shall fashion for you a suit of armor the likes of which has never before been seen in our world!", objectives = "Huntsman Leopold at Light's Hope Chapel in the Eastern Plaguelands will make Cryptstalker Legguards if you bring him the following: 1 Desecrated Legguards, 20 Wartorn Chain Scraps, 3 Arcanite Bars and 5 Cured Rugged Hides.", progress = "Do you have the items I asked for, {class}?", completion = "As you don more of this armor, you will notice that your persona is changing. You will gain a preternatural ability for killing. Perhaps, even, a lust for blood.\n\nLet it be said that I will not be held responsible for what chaos you may invoke..." }
WordHunterWoW_QuestEN[9056] = { title = "Cryptstalker Headpiece", description = "I have discovered a use for the carapace of the crypt fiend. I am able to fashion an extremely light and very deadly set of armor by combining the fragments with some of the desecrated magical armors lost in Naxxramas.\n\nBring me the items I require and I shall fashion for you a suit of armor the likes of which has never before been seen in our world!", objectives = "Huntsman Leopold at Light's Hope Chapel in the Eastern Plaguelands will make a Cryptstalker Headpiece if you bring him the following: 1 Desecrated Headpiece, 15 Wartorn Chain Scraps, 4 Arcanite Bars and 2 Nexus Crystals.", progress = "Do you have the items I asked for, {class}?", completion = "You are turning into a fearsome creature, {name}." }
WordHunterWoW_QuestEN[9057] = { title = "Cryptstalker Spaulders", description = "I have discovered a use for the carapace of the crypt fiend. I am able to fashion an extremely light and very deadly set of armor by combining the fragments with some of the desecrated magical armors lost in Naxxramas.\n\nBring me the items I require and I shall fashion for you a suit of armor the likes of which has never before been seen in our world!", objectives = "Huntsman Leopold at Light's Hope Chapel in the Eastern Plaguelands will make Cryptstalker Spaulders if you bring him the following: 1 Desecrated Spaulders, 12 Wartorn Chain Scraps, 2 Arcanite Bars and 3 Cured Rugged Hides.", progress = "Do you have the items I asked for, {class}?", completion = "I have taken special care in making these shoulders as large and pronounced as possible. Take my word for it; you're going to love them..." }
WordHunterWoW_QuestEN[9058] = { title = "Cryptstalker Boots", description = "I have discovered a use for the carapace of the crypt fiend. I am able to fashion an extremely light and very deadly set of armor by combining the fragments with some of the desecrated magical armors lost in Naxxramas.\n\nBring me the items I require and I shall fashion for you a suit of armor the likes of which has never before been seen in our world!", objectives = "Huntsman Leopold at Light's Hope Chapel in the Eastern Plaguelands will make Cryptstalker Boots if you bring him the following: 1 Desecrated Boots, 12 Wartorn Chain Scraps, 1 Arcanite Bar and 3 Nexus Crystals.", progress = "Do you have the items I asked for, {class}?", completion = "The boots are ready, {name}! Wear them well." }
WordHunterWoW_QuestEN[9059] = { title = "Cryptstalker Handguards", description = "I have discovered a use for the carapace of the crypt fiend. I am able to fashion an extremely light and very deadly set of armor by combining the fragments with some of the desecrated magical armors lost in Naxxramas.\n\nBring me the items I require and I shall fashion for you a suit of armor the likes of which has never before been seen in our world!", objectives = "Huntsman Leopold at Light's Hope Chapel in the Eastern Plaguelands will make Cryptstalker Handguards if you bring him the following: 1 Desecrated Handguards, 8 Wartorn Chain Scraps, 1 Arcanite Bar and 5 Cured Rugged Hides.", progress = "Do you have the items I asked for, {class}?", completion = "Let the rage of the crypt fiend guide your hand, {name}." }
WordHunterWoW_QuestEN[9060] = { title = "Cryptstalker Girdle", description = "I have discovered a use for the carapace of the crypt fiend. I am able to fashion an extremely light and very deadly set of armor by combining the fragments with some of the desecrated magical armors lost in Naxxramas.\n\nBring me the items I require and I shall fashion for you a suit of armor the likes of which has never before been seen in our world!", objectives = "Huntsman Leopold at Light's Hope Chapel in the Eastern Plaguelands will make a Cryptstalker Girdle if you bring him the following: 1 Desecrated Girdle, 8 Wartorn Chain Scraps, 1 Arcanite Bar and 3 Nexus Crystals.", progress = "Do you have the items I asked for, {class}?", completion = "A girdle fit for royalty! It's ready for you, {name}." }
WordHunterWoW_QuestEN[9061] = { title = "Cryptstalker Wristguards", description = "I have discovered a use for the carapace of the crypt fiend. I am able to fashion an extremely light and very deadly set of armor by combining the fragments with some of the desecrated magical armors lost in Naxxramas.\n\nBring me the items I require and I shall fashion for you a suit of armor the likes of which has never before been seen in our world!", objectives = "Huntsman Leopold at Light's Hope Chapel in the Eastern Plaguelands will make Cryptstalker Wristguards if you bring him the following: 1 Desecrated Wristguards, 6 Wartorn Chain Scraps, 1 Arcanite Bar and 2 Cured Rugged Hides.", progress = "Do you have the items I asked for, {class}?", completion = "The wristguards are ready. Enjoy!" }
WordHunterWoW_QuestEN[9063] = { title = "Torwa Pathfinder", description = "A hunter by the name of Torwa Pathfinder has requested the help of a druid.  He said only we would possess the necessary skills and respect for nature to help him.\n\nThere is a road that connects the Un'Goro Crater and the desert of Tanaris.  As that road enters the crater, you will find Torwa close by.", objectives = "Speak with Torwa Pathfinder in Un'Goro Crater.", completion = "You have traveled far to meet with me, {class}, and not a moment too soon." }
WordHunterWoW_QuestEN[9065] = { title = "The \"Chow\" Quest (123)aa", description = "", objectives = "" }
WordHunterWoW_QuestEN[9068] = { title = "Earthshatter Tunic", description = "Would you honor me by returning the armor of those that fell in the defense of these lands?\n\nThe armor has been desecrated and is undoubtedly being used for evil; however, with wartorn armor scraps, the desecrated armor can be renewed and worn for battle once more.\n\nBring me the remnants of the fallen along with purification materials and Earthshatter shall be yours to don.\n\nSearch Naxxramas.", objectives = "Rimblat Earthshatter at Light's Hope Chapel in the Eastern Plaguelands will make an Earthshatter Tunic if you bring him the following: 1 Desecrated Tunic, 25 Wartorn Chain Scraps, 4 Arcanite Bars and 3 Cured Rugged Hides.", progress = "<Rimblat snorts at you.>", completion = "Easily the most powerful and awe-inspiring piece of Earthshatter. My ancestors smile down upon you for this achievement, {name}." }
WordHunterWoW_QuestEN[9069] = { title = "Earthshatter Legguards", description = "Would you honor me by returning the armor of those that fell in the defense of these lands?\n\nThe armor has been desecrated and is undoubtedly being used for evil; however, with wartorn armor scraps, the desecrated armor can be renewed and worn for battle once more.\n\nBring me the remnants of the fallen along with purification materials and Earthshatter shall be yours to don.\n\nSearch Naxxramas.", objectives = "Rimblat Earthshatter at Light's Hope Chapel in the Eastern Plaguelands will make Earthshatter Legguards if you bring him the following: 1 Desecrated Legguards, 20 Wartorn Chain Scraps, 3 Arcanite Bars and 5 Cured Rugged Hides.", progress = "If nothing else, the land must be saved.", completion = "I hope that you do not share the same fate as those that came before you, {name}." }
WordHunterWoW_QuestEN[9070] = { title = "Earthshatter Headpiece", description = "Would you honor me by returning the armor of those that fell in the defense of these lands?\n\nThe armor has been desecrated and is undoubtedly being used for evil; however, with wartorn armor scraps, the desecrated armor can be renewed and worn for battle once more.\n\nBring me the remnants of the fallen along with purification materials and Earthshatter shall be yours to don.\n\nSearch Naxxramas.", objectives = "Rimblat Earthshatter at Light's Hope Chapel in the Eastern Plaguelands will make an Earthshatter Headpiece if you bring him the following: 1 Desecrated Headpiece, 15 Wartorn Chain Scraps, 4 Arcanite Bars and 2 Nexus Crystals.", progress = "Have you brought me that which I require?", completion = "I present you with the centerpiece of Earthshatter vestments: The Earthshatter helmet..." }
WordHunterWoW_QuestEN[9071] = { title = "Earthshatter Spaulders", description = "Would you honor me by returning the armor of those that fell in the defense of these lands?\n\nThe armor has been desecrated and is undoubtedly being used for evil; however, with wartorn armor scraps, the desecrated armor can be renewed and worn for battle once more.\n\nBring me the remnants of the fallen along with purification materials and Earthshatter shall be yours to don.\n\nSearch Naxxramas.", objectives = "Rimblat Earthshatter at Light's Hope Chapel in the Eastern Plaguelands will make Earthshatter Spaulders if you bring him the following: 1 Desecrated Spaulders, 12 Wartorn Chain Scraps, 2 Arcanite Bars and 2 Mooncloth.", progress = "Have you brought me that which I require?", completion = "From the shoulders comes balance." }
WordHunterWoW_QuestEN[9072] = { title = "Earthshatter Boots", description = "Would you honor me by returning the armor of those that fell in the defense of these lands?\n\nThe armor has been desecrated and is undoubtedly being used for evil; however, with wartorn armor scraps, the desecrated armor can be renewed and worn for battle once more.\n\nBring me the remnants of the fallen along with purification materials and Earthshatter shall be yours to don.\n\nSearch Naxxramas.", objectives = "Rimblat Earthshatter at Light's Hope Chapel in the Eastern Plaguelands will make Earthshatter Boots if you bring him the following: 1 Desecrated Boots, 12 Wartorn Chain Scraps, 1 Arcanite Bar and 3 Nexus Crystals.", progress = "Have you brought me that which I require?", completion = "These boots are infused with the power of my ancestors! Tread wisely..." }
WordHunterWoW_QuestEN[9073] = { title = "Earthshatter Handguards", description = "Would you honor me by returning the armor of those that fell in the defense of these lands?\n\nThe armor has been desecrated and is undoubtedly being used for evil; however, with wartorn armor scraps, the desecrated armor can be renewed and worn for battle once more.\n\nBring me the remnants of the fallen along with purification materials and Earthshatter shall be yours to don.\n\nSearch Naxxramas.", objectives = "Rimblat Earthshatter at Light's Hope Chapel in the Eastern Plaguelands will make Earthshatter Handguards if you bring him the following: 1 Desecrated Handguards, 8 Wartorn Chain Scraps, 1 Arcanite Bar and 5 Cured Rugged Hides.", progress = "Have you brought me that which I require?", completion = "These handguards channel the power of the elements!" }
WordHunterWoW_QuestEN[9074] = { title = "Earthshatter Girdle", description = "Would you honor me by returning the armor of those that fell in the defense of these lands?\n\nThe armor has been desecrated and is undoubtedly being used for evil; however, with wartorn armor scraps, the desecrated armor can be renewed and worn for battle once more.\n\nBring me the remnants of the fallen along with purification materials and Earthshatter shall be yours to don.\n\nSearch Naxxramas.", objectives = "Rimblat Earthshatter at Light's Hope Chapel in the Eastern Plaguelands will make an Earthshatter Girdle if you bring him the following: 1 Desecrated Girdle, 8 Wartorn Chain Scraps, 1 Arcanite Bar and 3 Nexus Crystals.", progress = "Have you brought me that which I require?", completion = "The girdle is ready, {name}." }
WordHunterWoW_QuestEN[9075] = { title = "Earthshatter Wristguards", description = "Would you honor me by returning the armor of those that fell in the defense of these lands?\n\nThe armor has been desecrated and is undoubtedly being used for evil; however, with wartorn armor scraps, the desecrated armor can be renewed and worn for battle once more.\n\nBring me the remnants of the fallen along with purification materials and Earthshatter shall be yours to don.\n\nSearch Naxxramas.", objectives = "Rimblat Earthshatter at Light's Hope Chapel in the Eastern Plaguelands will make Earthshatter Wristguards if you bring him the following: 1 Desecrated Wristguards, 6 Wartorn Chain Scraps, 1 Arcanite Bar and 2 Cured Rugged Hides.", progress = "Have you brought me that which I require?", completion = "The wristguards are ready, {name}." }
WordHunterWoW_QuestEN[9077] = { title = "Bonescythe Breastplate", description = "If you want Bonescythe made, you're going to have to supply the materials.\n\nEnter Naxxramas, the big floating city of death in the sky up there, and find desecrated armor and wartorn armor scraps. Bring those back along with the materials to put everything together and you'll have your Bonescythe. Oh, and you'll need to pay me for my troubles... I'll supply the bones.", objectives = "Rohan the Assassin at Light's Hope Chapel in the Eastern Plaguelands will make a Bonescythe Breastplate if you bring him the following: 1 Desecrated Breastplate, 25 Wartorn Leather Scraps, 2 Arcanite Bars and 6 Cured Rugged Hides.", progress = "<Rohan shows you his moves.>\n\nWhat is it, {name}? I've got to hit this mark perfectly for the competition later.", completion = "There you go, {race}. As promised, the Bonescythe breastplate. I hope the fashion authorities aren't around. You'd be thrown in the slammer for wearing that out!" }
WordHunterWoW_QuestEN[9078] = { title = "Bonescythe Legplates", description = "If you want Bonescythe made, you're going to have to supply the materials.\n\nEnter Naxxramas, the big floating city of death in the sky up there, and find desecrated armor and wartorn armor scraps. Bring those back along with the materials to put everything together and you'll have your Bonescythe. Oh, and you'll need to pay me for my troubles... I'll supply the bones.", objectives = "Rohan the Assassin at Light's Hope Chapel in the Eastern Plaguelands will make Bonescythe Legplates if you bring him the following: 1 Desecrated Legplates, 20 Wartorn Leather Scraps, 1 Arcanite Bar, 8 Cured Rugged Hides and 100 gold pieces.", progress = "<Rohan laughs.>\n\nI just realized the irony in all of this.", completion = "Be careful walking around in those things. You might cut yourself." }
WordHunterWoW_QuestEN[9079] = { title = "Bonescythe Helmet", description = "If you want Bonescythe made, you're going to have to supply the materials.\n\nEnter Naxxramas, the big floating city of death in the sky up there, and find desecrated armor and wartorn armor scraps. Bring those back along with the materials to put everything together and you'll have your Bonescythe. Oh, and you'll need to pay me for my troubles... I'll supply the bones.", objectives = "Rohan the Assassin at Light's Hope Chapel in the Eastern Plaguelands will make a Bonescythe Helmet if you bring him the following: 1 Desecrated Helmet, 15 Wartorn Leather Scraps, 8 Cured Rugged Hides, 1 Nexus Crystal and 75 gold pieces.", progress = "You're giving me money.\n\n<Rohan laughs.>\n\nThat still cracks me up.", completion = "What separates my Bonescythe helmet model from Don Julio's is style, {name}. Style..." }
WordHunterWoW_QuestEN[9080] = { title = "Bonescythe Pauldrons", description = "If you want Bonescythe made, you're going to have to supply the materials.\n\nEnter Naxxramas, the big floating city of death in the sky up there, and find desecrated armor and wartorn armor scraps. Bring those back along with the materials to put everything together and you'll have your Bonescythe. Oh, and you'll need to pay me for my troubles... I'll supply the bones.", objectives = "Rohan the Assassin at Light's Hope Chapel in the Eastern Plaguelands will make Bonescythe Pauldrons if you bring him the following: 1 Desecrated Pauldrons, 12 Wartorn Leather Scraps, 5 Cured Rugged Hides, 1 Nexus Crystal and 50 gold pieces.", progress = "<Rohan eyes you suspiciously.>\n\nBeen to Tyr's Hand lately?", completion = "<Rohan wipes the sweat from his brow.>\n\nThese shoulders took some work! Don't go out and get yourself killed like a scrub, {name}." }
WordHunterWoW_QuestEN[9081] = { title = "Bonescythe Sabatons", description = "If you want Bonescythe made, you're going to have to supply the materials.\n\nEnter Naxxramas, the big floating city of death in the sky up there, and find desecrated armor and wartorn armor scraps. Bring those back along with the materials to put everything together and you'll have your Bonescythe. Oh, and you'll need to pay me for my troubles... I'll supply the bones.", objectives = "Rohan the Assassin at Light's Hope Chapel in the Eastern Plaguelands will make Bonescythe Sabatons if you bring him the following: 1 Desecrated Sabatons, 12 Wartorn Leather Scraps, 3 Cured Rugged Hides, 2 Nexus Crystals and 25 gold pieces.", progress = "Just bring me the materials and stop wasting my time, {class}.", completion = "They go on your feet. Say, you haven't been nosing around in Tyr's Hand again, have you?" }
WordHunterWoW_QuestEN[9082] = { title = "Bonescythe Gauntlets", description = "If you want Bonescythe made, you're going to have to supply the materials.\n\nEnter Naxxramas, the big floating city of death in the sky up there, and find desecrated armor and wartorn armor scraps. Bring those back along with the materials to put everything together and you'll have your Bonescythe. Oh, and you'll need to pay me for my troubles... I'll supply the bones.", objectives = "Rohan the Assassin at Light's Hope Chapel in the Eastern Plaguelands will make Bonescythe Gauntlets if you bring him the following: 1 Desecrated Gauntlets, 8 Wartorn Leather Scraps, 1 Arcanite Bar and 5 Cured Rugged Hides.", progress = "How do you expect me to get anything done without the items I requested?", completion = "These gauntlets could probably substitute as weapons if absolutely necessary. Wear them with pride!" }
WordHunterWoW_QuestEN[9083] = { title = "Bonescythe Waistguard", description = "If you want Bonescythe made, you're going to have to supply the materials.\n\nEnter Naxxramas, the big floating city of death in the sky up there, and find desecrated armor and wartorn armor scraps. Bring those back along with the materials to put everything together and you'll have your Bonescythe. Oh, and you'll need to pay me for my troubles... I'll supply the bones.", objectives = "Rohan the Assassin at Light's Hope Chapel in the Eastern Plaguelands will make a Bonescythe Waistguard if you bring him the following: 1 Desecrated Waistguard, 8 Wartorn Leather Scraps, 5 Cured Rugged Hides, 1 Nexus Crystal and 15 gold pieces.", progress = "How do you expect me to get anything done without the items I requested?", completion = "The belt is ready, {name}. Have you ever seen such a high-quality item sold for so little?" }
WordHunterWoW_QuestEN[9084] = { title = "Bonescythe Bracers", description = "If you want Bonescythe made, you're going to have to supply the materials.\n\nEnter Naxxramas, the big floating city of death in the sky up there, and find desecrated armor and wartorn armor scraps. Bring those back along with the materials to put everything together and you'll have your Bonescythe. Oh, and you'll need to pay me for my troubles... I'll supply the bones.", objectives = "Rohan the Assassin at Light's Hope Chapel in the Eastern Plaguelands will make Bonescythe Bracers if you bring him the following: 1 Desecrated Bracers, 6 Wartorn Leather Scraps, 1 Arcanite Bar, 2 Cured Rugged Hides and 10 gold pieces.", progress = "How do you expect me to get anything done without the items I requested?", completion = "The bracers are ready, {name}." }
WordHunterWoW_QuestEN[9085] = { title = "Shadows of Doom", description = "After you bring down the defenses of the Scourge summoning circles that have appeared in the zones under attack, you will be able to confront the acolytes who protect them.\n\nIn truth, these are not men. They are shadows, some of the Lich King's most frightening creatures. They can be revealed using the necrotic runes they carry, and then destroyed with magic or strength of arms.", objectives = "Go to a summoning circle and kill a Shadow of Doom, then return to Commander Thomas Helleran at Light's Hope Chapel in Eastern Plaguelands.", progress = "Have you had any luck, {name}?", completion = "Excellent work, {name}. With the shadows destroyed, it can only be a matter of time before the Lich King decides to recall his necropolises and leave us in peace." }
WordHunterWoW_QuestEN[9086] = { title = "Dreamwalker Tunic", description = "Many heroes fell in the last war and many continue to perish at the hands of the Scourge to this day. From the corpses of the fallen, the armor is stripped and taken back to Naxxramas to be used for unknown purposes.\n\nRecover the desecrated armor and wartorn armor scraps and supply to me the other material components I require and I will craft Dreamwalker armor.", objectives = "Rayne at Light's Hope Chapel in the Eastern Plaguelands will make a Dreamwalker Tunic if you bring her the following: 1 Desecrated Tunic, 25 Wartorn Leather Scraps, 6 Cured Rugged Hides and 2 Nexus Crystals.", progress = "The material cost is high, but soon forgotten.", completion = "Your Dreamwalker tunic is ready, {name}." }
WordHunterWoW_QuestEN[9087] = { title = "Dreamwalker Legguards", description = "Many heroes fell in the last war and many continue to perish at the hands of the Scourge to this day. From the corpses of the fallen, the armor is stripped and taken back to Naxxramas to be used for unknown purposes.\n\nRecover the desecrated armor and wartorn armor scraps and supply to me the other material components I require and I will craft Dreamwalker armor.", objectives = "Rayne at Light's Hope Chapel in the Eastern Plaguelands will make Dreamwalker Legguards if you bring her the following: 1 Desecrated Legguards, 20 Wartorn Leather Scraps, 8 Cured Rugged Hides and 1 Nexus Crystal.", progress = "The material cost is high, but soon forgotten.", completion = "As promised, Dreamwalker legguards.\n\n<Rayne hands you the armor.>" }
WordHunterWoW_QuestEN[9088] = { title = "Dreamwalker Headpiece", description = "Many heroes fell in the last war and many continue to perish at the hands of the Scourge to this day. From the corpses of the fallen, the armor is stripped and taken back to Naxxramas to be used for unknown purposes.\n\nRecover the desecrated armor and wartorn armor scraps and supply to me the other material components I require and I will craft Dreamwalker armor.", objectives = "Rayne at Light's Hope Chapel in the Eastern Plaguelands will make a Dreamwalker Headpiece if you bring her the following: 1 Desecrated Headpiece, 15 Wartorn Leather Scraps, 6 Cured Rugged Hides and 2 Nexus Crystals.", progress = "The material cost is high, but soon forgotten.", completion = "Your Dreamwalker headpiece is ready, {name}." }
