WordHunterWoW_QuestEN[9103] = { title = "Plagueheart Robe", description = "I make no pretenses, maggot. The darkness Plagueheart items hold could very well destroy the both of us. That is why the price is so high. If I'm going to die, it's going to be as a rich man.\n\nAnd I don't give an ounce of gnoll spit how you die, only that you do as I ask. Bring me what I require and we will both benefit - or die; but I've already explained this...", objectives = "Mataus the Wrathcaster at Light's Hope Chapel in the Eastern Plaguelands will make a Plagueheart Robe if you bring him the following: 1 Desecrated Robe, 25 Wartorn Cloth Scraps, 4 Mooncloth and 2 Nexus Crystals.", progress = "The prodigal rodent returns! Have you what I require?", completion = "Do you see? Do you now understand the power? Purification... What fools...\n\n<Mataus shakes his head disapprovingly.>\n\nNow take it and get out of my sight." }
