WordHunterWoW_QuestEN[9120] = { title = "The Fall of Kel'Thuzad", description = "The phylactery is all that remains of the master of Naxxramas. Your better judgment dictates that you destroy the phylactery, preventing the lich from ever reforming. Thankfully, you seldom listen to that internal voice of reason.\n\nSomeone at Light's Hope will pay you hugely for this artifact. Who cares if Kel'Thuzad regenerates to full power?", objectives = "Take the Phylactery of Kel'Thuzad to Light's Hope Chapel in the Eastern Plaguelands.", progress = "BLESSED LIGHT! What foulness do you hold, boy?", completion = "In all my days of living I would have never expected to see this...\n\n<Father Montoy appears to be salivating.>\n\nOh yes, you will be rewarded dear boy. You will be greatly rewarded. Give it here. Now!" }
WordHunterWoW_QuestEN[9121] = { title = "The Dread Citadel - Naxxramas", description = "In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now.\n\nWe have devised a way to gain entry via arcane cloaking - an old cantrip of the Kirin Tor with a few modifications of my own. Since your dedication to the cause of the Dawn is somewhat lacking, {name}, the price will be high. You may decline and choose to return when you are revered or exalted for a discount.", objectives = "Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands wants 5 Arcane Crystals, 2 Nexus Crystals, 1 Righteous Orb and 60 gold pieces. You must also be Honored with the Argent Dawn.", progress = "None have entered Naxxramas and lived to tell the tale.", completion = "You will feel a slight tingle, {name}. That sensation means it's working. Once complete, you will be able to enter Naxxramas by stepping upon the rune portal in Plaguewood." }
WordHunterWoW_QuestEN[9122] = { title = "The Dread Citadel - Naxxramas", description = "In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now.\n\nWe have devised a way to gain entry via a permanent arcane cloaking of sorts - an old cantrip of the Kirin Tor with a few modifications of my own. With that said, the cloaking is costly. Since your dedication to the cause of the Dawn is admirable, we are willing to incur some of those costs.", objectives = "Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands wants 2 Arcane Crystals, 1 Nexus Crystal and 30 gold pieces. You must also be Revered with the Argent Dawn.", progress = "None have entered Naxxramas and lived to tell the tale.", completion = "You will feel a slight tingle, {name}. That sensation means it's working. Once complete, you will be able to enter Naxxramas by stepping upon the rune portal in Plaguewood." }
WordHunterWoW_QuestEN[9123] = { title = "The Dread Citadel - Naxxramas", description = "In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now.\n\nWe have devised a way to gain entry via a permanent arcane cloaking of sorts - an old cantrip of the Kirin Tor with a few modifications of my own. With that said, the cloaking is costly; however, your dedication to the cause of the Dawn is unwavering! We will waive all cost associations.", objectives = "Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will grant you Arcane Cloaking at no cost. You must be Exalted with the Argent Dawn.", completion = "You will feel a slight tingle, {name}. That sensation means it's working. Once complete, you will be able to enter Naxxramas by stepping upon the rune portal in Plaguewood." }
WordHunterWoW_QuestEN[9124] = { title = "Cryptstalker Armor Doesn't Make Itself...", description = "How would you like to earn yourself one of these shiny coins?\n\n<Leopold holds up an insignia of the Crusade.>\n\nI've got a little problem that you might be able to help me with, {name}. You see, I make Cryptstalker armor for those daft enough to venture into Naxxramas. While they supply me with the core material requirements for the armor, I always run out of the crypt fiend parts. Bring me back a bundle of parts and I'll pay you with an insignia - usable at the quartermaster.", objectives = "Huntsman Leopold at Light's Hope Chapel in the Eastern Plaguelands wants 30 Crypt Fiend Parts.", progress = "How goes the hunt?", completion = "Ah, that'll do nicely, {name}. Remember, I'm always accepting more parts. For every bundle you bring me, I'll reward you with an insignia." }
WordHunterWoW_QuestEN[9125] = { title = "Crypt Fiend Parts", description = "", objectives = "You did an exemplary job on the first bundle, {name}. If you have more, I will take them now. For every bundle that you turn in, I will reward you with another insignia.", progress = "You did an exemplary job on the first bundle, {name}. If you have more, I will take them now. For every bundle that you turn in, I will reward you with another insignia.", completion = "Most excellent, {name}! These will definitely come to good use." }
WordHunterWoW_QuestEN[9126] = { title = "Bonescythe Digs", description = "Don Julio's Bonescythe armor pattern requires bone fragments - a lot of bone fragments. While those crazy enough to venture into Naxxramas provide me with enough of the core materials to make the armor, I'm always looking for more Scourge bone fragments.\n\nSo what do you think? Interested in getting your hands dirty and destroying some Scourge at the same time? It's a win-win situation.", objectives = "Rohan the Assassin at Light's Hope Chapel in the Eastern Plaguelands wants 30 Bone Fragments.", progress = "I can direct you to skeleton infested locales, {class}.", completion = "You work fast, {name}. Fast like a fox... Say, have I ever told you about the time I was in a barber shop quartet?\n\nRemind me to tell you that story one of these days." }
WordHunterWoW_QuestEN[9127] = { title = "Bone Fragments", description = "", objectives = "A man in my line of work can never have too many bone fragments, {name}. Whenever you have a surplus of fragments, bring them to me and I'll reward you with another insignia.", progress = "A man in my line of work can never have too many bone fragments, {name}. Whenever you have a surplus of fragments, bring them to me and I'll reward you with another insignia.", completion = "My dream of becoming a full-time dancer at the Gadgetzan disco is soon to become a reality! Keep up the good work, {name}." }
WordHunterWoW_QuestEN[9128] = { title = "The Elemental Equation", description = "Greetings, adventurer! Are you interested in some work? I pay those under my employ with insignias. These insignias can be used at the Quartermaster to purchase items of power.\n\nAll I need you to do is bring me as many core of elements as you can carry. The more the better!\n\nYou'll find them on elementals of varying shapes and sizes that exist across our world.", objectives = "Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands wants 30 Core of Elements.", progress = "I can only steer you in the right direction, {name}.", completion = "A job well done, {name}! As promised, the insignia is yours. Just remember, there's more where that came from..." }
WordHunterWoW_QuestEN[9129] = { title = "Core of Elements", description = "", objectives = "Truth be told, I use the cores to create Frostfire armor. It is the armor used by the mages battling in Naxxramas. Without you and others like you, we would most definitely be losing this war.\n\nWith that said, bring me more cores and I shall grant you more insignias.", progress = "Truth be told, I use the cores to create Frostfire armor. It is the armor used by the mages battling in Naxxramas. Without you and others like you, we would most definitely be losing this war.\n\nWith that said, bring me more cores and I shall grant you more insignias.", completion = "You perform a great service for us, {name}. Well done!" }
WordHunterWoW_QuestEN[9131] = { title = "Binding the Dreadnaught", description = "Have you ever seen Dreadnaught armor, {class}? No, of course you haven't. You're still a <boy/girl> - a tyke. Let me tell you, it is glorious.\n\nYou're probably asking yourself what any of this has to do with you, right? I'll tell you what, scrub; I need Dark Iron scraps and I'm willing to pay to get my hands on as many as possible.\n\nI need the scraps to put together sets of Dreadnaught for our champions. Bring me scraps and get paid.", objectives = "Korfax at Light's Hope Chapel in the Eastern Plaguelands wants 30 Dark Iron Scraps.", progress = "<Korfax growls at you.>\n\nWhat do you want? Directions? I can provide those...", completion = "This will do, for now. If you get more, you know where to find me." }
WordHunterWoW_QuestEN[9132] = { title = "Dark Iron Scraps", description = "", objectives = "For every armful of the scraps, I'll give you an insignia - the more the better. Now get out of my sight before I split you in two!", progress = "For every armful of the scraps, I'll give you an insignia - the more the better. Now get out of my sight before I split you in two!", completion = "That's all you brought me? Maybe you didn't hear me the first time. I need MORE!" }
WordHunterWoW_QuestEN[9136] = { title = "Savage Flora", description = "I make a special type of armor for the brave heroes that enter Naxxramas known as Dreamwalker. They are able to provide me with most of the materials I require but I am always looking for those able to retrieve savage fronds from the flora of our world.\n\nYou may think of this job as beneath you, but without the fronds, the armor could not be made.\n\nI am also in a unique position to pay you with an insignia of your choice as both the Dawn and the Crusade supply me with funds.", objectives = "Rayne at Light's Hope Chapel in the Eastern Plaguelands wants 30 Savage Fronds.", progress = "I have intimate knowledge of the flora in our world. Do you require direction?", completion = "I am much obliged, {name}.\n\n\n\nPlease remember that I am always accepting fronds." }
WordHunterWoW_QuestEN[9137] = { title = "Savage Fronds", description = "", objectives = "For every bundle of fronds that you deliver to me, I will pay you with your choice of an insignia of the Dawn or the Crusade.\n\nInsignias may be turned in to the Quartermaster for various rewards.", progress = "For every bundle of fronds that you deliver to me, I will pay you with your choice of an insignia of the Dawn or the Crusade.\n\nInsignias may be turned in to the Quartermaster for various rewards.", completion = "Thank you, {name}. Your work is vital to the success of our campaign against the Scourge." }
WordHunterWoW_QuestEN[9141] = { title = "They Call Me \"The Rooster\"", description = "You want a writ? What? Do you expect me to hand you a highly sought after work order just for showing up? I think not, scrub. Crafters from around the world bid for jobs here at the front lines.\n\nIf you want a work order, you'll have to show me that you're willing to bleed for the cause. Bring me a valor token and we'll talk.\n\nAnd there's only one way to get your grubby little scrub mitts on those - get to killin'.", objectives = "Dispatch Commander Metz at Light's Hope Chapel in the Eastern Plaguelands wants an Argent Dawn Valor Token.", progress = "<Commander Metz chews on his cigar.>\n\nWhat is it? I'm a busy man.", completion = "Alright, here's how it works: For every valor token that you turn in, I'll give you another writ. You complete the order on that writ and deliver the order to Packmaster Stonebruiser. Got it? Good. Now get out of here." }
WordHunterWoW_QuestEN[9142] = { title = "Craftsman's Writ", description = "", objectives = "You know the drill, kid. One valor token gets you a craftsman's writ.", progress = "You know the drill, kid. One valor token gets you a craftsman's writ.", completion = "You earned this, scrub. Now, don't cry about your orders. Fill 'em or destroy 'em." }
WordHunterWoW_QuestEN[9153] = { title = "Under the Shadow", description = "The floating necropolises of the Scourge plague the lands of Horde and Alliance alike. Tanaris, the Blasted Lands, Winterspring and the Burning Steppes are blanketed in the shadows of the flying fortresses.\n\nOnly through our combined efforts will they be turned away.\n\nThe necropolises are supported by magical circles at various points in the invaded areas. We have determined that destroying the mindless hordes that surround these circles will destroy their defenses.", objectives = "Check your map to find an area under Scourge attack. Go there and damage a necropolis by defeating the Scourge around them. Return 10 of their Necrotic Runes to Commander Thomas Helleran at Light's Hope Chapel in the Eastern Plaguelands.", progress = "It will take time to prevail against this threat. How have you fared, {name}?", completion = "You've done well, {name}. Through these incremental defeats, we shall prevail against this renewed Scourge threat.\n\nRest and recover, but then you must head out to the front again, lest we lose the ground we have gained today.\n\nTo aid you in your further battles, we will make some of our special items available to you in trade for more necrotic runes." }
WordHunterWoW_QuestEN[9154] = { title = "Light's Hope Chapel", description = "The Scourge have returned in greater numbers than we have seen before. The Argent Dawn is recruiting all willing and capable men and women to defend our lands.\n\nIf we share common cause, take this document to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.", objectives = "Deliver the Call to Arms Announcement to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.", progress = "You've come to join our order, have you not?", completion = "The Argent Dawn placed the call for aid, and you, among others, have answered. There is no time for us to provide you with training. Our faith is placed in your abilities, and that you will join us in throwing back this Scourge threat." }
WordHunterWoW_QuestEN[9165] = { title = "Writ of Safe Passage", description = "Without the help of adventurers, my caravan would have never made it! Scourge were coming out of the woodwork to try and stop us from getting here.\n\n<Guard Didier wipes his brow.>\n\nNow we need to wait here for Field Marshal Chambers to arrive. He'll sign your writ of safe passage to take back to Dispatch Commander Metz at Light's Hope Chapel.\n\nAnd {name}, watch what you say around Chambers. He's the 'bite off your head and spit down your wind pipe' type of guy - except that he'll actually do it...", objectives = "Deliver the signed Writ of Safe Passage to Dispatch Commander Metz at Light's Hope Chapel in the Eastern Plaguelands.", completion = "<Dispatch Commander Metz takes the writ and signs it.>\n\nExcellent work, {name}. Outstanding even! Take this as a token of our appreciation. No pun intended, scrub." }
WordHunterWoW_QuestEN[9178] = { title = "Craftsman's Writ - Dense Weightstone", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order BS-091:\n\n120 Dense Weightstones.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 120 Dense Weightstones and the Craftsman's Writ - Dense Weightstone - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "Yep, these will come in handy for the infantry's bashin' weapons." }
WordHunterWoW_QuestEN[9179] = { title = "Craftsman's Writ - Imperial Plate Chest", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order BS-428:\n\n3 Imperial Plate Chests.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 3 Imperial Plate Chests and the Craftsman's Writ - Imperial Plate Chest - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "More armor for the troops! Fantastic, {name}!" }
WordHunterWoW_QuestEN[9181] = { title = "Craftsman's Writ - Volcanic Hammer", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order BS-697:\n\n3 Volcanic Hammers.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 3 Volcanic Hammers and the Craftsman's Writ - Volcanic Hammer - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "These should go well with the dense weightstones we're stockpiling." }
WordHunterWoW_QuestEN[9182] = { title = "Craftsman's Writ - Huge Thorium Battleaxe", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order BS-6020:\n\n3 Huge Thorium Battleaxes.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 3 Huge Thorium Battleaxes and the Craftsman's Writ - Huge Thorium Battleaxe - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "These aren't as huge as I expected. Regardless, a deal is a deal." }
WordHunterWoW_QuestEN[9183] = { title = "Craftsman's Writ - Radiant Circlet", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order BS-80:\n\n3 Radiant Circlets.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 3 Radiant Circlets and the Craftsman's Writ - Radiant Circlet - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "I still can't believe Metz expects our troops to wear this low-quality garbage to protect against the freezing attacks of the Scourge." }
WordHunterWoW_QuestEN[9184] = { title = "Craftsman's Writ - Wicked Leather Headband", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order LW-971:\n\n10 Wicked Leather Headbands.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 10 Wicked Leather Headbands and the Craftsman's Writ - Wicked Leather Headband - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "These are... wicked." }
WordHunterWoW_QuestEN[9185] = { title = "Craftsman's Writ - Rugged Armor Kit", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order LW-448:\n\n25 Rugged Armor Kits.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 25 Rugged Armor Kits and the Craftsman's Writ - Rugged Armor Kit - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "The rugged armor kits have many uses, {name}. They aren't JUST for slapping on certain armor pieces for added protection. Like this one here, I'm going to use it as teapot cozy." }
WordHunterWoW_QuestEN[9186] = { title = "Craftsman's Writ - Wicked Leather Belt", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order LW-736:\n\n9 Wicked Leather Belts.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 9 Wicked Leather Belts and the Craftsman's Writ - Wicked Leather Belt - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "These belts are actually more wicked than the headbands - if you can believe such a thing to be possible." }
WordHunterWoW_QuestEN[9187] = { title = "Craftsman's Writ - Runic Leather Pants", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order LW-8485:\n\n4 Runic Leather Pants.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 4 Runic Leather Pants and the Craftsman's Writ - Runic Leather Pants - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "The druids will definitely appreciate the craftsmanship that went into the making of these pants. Many thanks, {class}." }
WordHunterWoW_QuestEN[9188] = { title = "Craftsman's Writ - Brightcloth Pants", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order TR-95:\n\n6 Brightcloth Pants.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 6 Brightcloth Pants and the Craftsman's Writ - Brightcloth Pants - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "I can almost see my reflection in these things! That's crazy." }
WordHunterWoW_QuestEN[9190] = { title = "Craftsman's Writ - Runecloth Boots", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order TR-635:\n\n8 Runecloth Boots.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 8 Runecloth Boots and the Craftsman's Writ - Runecloth Boots - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "By Bronzebeard's beard! You actually brought me runecloth boots... I guess I lost that bet." }
WordHunterWoW_QuestEN[9191] = { title = "Craftsman's Writ - Runecloth Bag", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order TR-9999:\n\n8 Runecloth Bags.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 8 Runecloth Bags and the Craftsman's Writ - Runecloth Bag - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "Blessed bootstraps! Are those what I think they are? The troops have been complaining non-stop about the lack of storage space for all that is required while in the field. One of them even drew me a diagram - such a pansy...\n\nThese will definitely help alleviate some of the whining." }
WordHunterWoW_QuestEN[9194] = { title = "Craftsman's Writ - Runecloth Robe", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order TR-7229:\n\n8 Runecloth Robes.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 8 Runecloth Robes and the Craftsman's Writ - Runecloth Robe - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "You shouldn't have! No really, you shouldn't have. I don't know what Metz is thinking, but nobody is going to be wearing these robes into Naxxramas.\n\n<Packmaster Stonebruiser sighs.>\n\nBah, another pile of junk I'll have to get transferred to the front lines and another berating I'll have to take from Chambers." }
WordHunterWoW_QuestEN[9195] = { title = "Craftsman's Writ - Goblin Sapper Charge", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order EN-11:\n\n20 Goblin Sapper Charges.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 20 Goblin Sapper Charges and the Craftsman's Writ - Goblin Sapper Charge - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "Now you're talking my language, {class}. Things that go BOOM!" }
WordHunterWoW_QuestEN[9196] = { title = "Craftsman's Writ - Thorium Grenade", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order EN-7:\n\n20 Thorium Grenades.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 20 Thorium Grenades and the Craftsman's Writ - Thorium Grenade - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "These must have cost a pretty copper piece to make. Am I right or am I right, {name}?" }
WordHunterWoW_QuestEN[9197] = { title = "Craftsman's Writ - Gnomish Battle Chicken", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order EN-0:\n\n4 Gnomish Battle Chickens.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 4 Gnomish Battle Chickens and the Craftsman's Writ - Gnomish Battle Chicken - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "Why are you smiling? What's so funny? Listen, sonny, a gnomish battle chicken is a very important unit and not to be taken lightly - EVER. We send these in to areas that might be heavily plagued or infested and they clean up any plagued insects or carrion maggots that might still be fluttering about. Everybody knows that robots are immune to the plague.\n\nI bet you don't feel so smart now, do you? Big dummy..." }
WordHunterWoW_QuestEN[9198] = { title = "Craftsman's Writ - Thorium Tube", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order EN-558:\n\n14 Thorium Tubes.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 14 Thorium Tubes and the Craftsman's Writ - Thorium Tube - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "Thorium tubes? Gee, thanks.\n\n<Packmaster Stonebruiser throws the stack of Thorium tubes into a large pile of assorted junk.>" }
WordHunterWoW_QuestEN[9200] = { title = "Craftsman's Writ - Major Mana Potion", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order AL-473:\n\n10 Major Mana Potions.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 10 Major Mana Potions and the Craftsman's Writ - Major Mana Potion - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "The utility of these should go without saying." }
WordHunterWoW_QuestEN[9201] = { title = "Craftsman's Writ - Greater Arcane Protection Potion", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order AL-1420:\n\n15 Greater Arcane Protection Potions.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 15 Greater Arcane Protection Potions and the Craftsman's Writ - Greater Arcane Protection Potion - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "<Packmaster Stonebruiser pops open one of the greater arcane protection potions and take a swig.>\n\nWOOT! These pack a kick, baby! A kick I say!" }
WordHunterWoW_QuestEN[9202] = { title = "Craftsman's Writ - Major Healing Potion", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order AL-169110:\n\n20 Major Healing Potions.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 20 Major Healing Potions and the Craftsman's Writ - Major Healing Potion - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "Do you know what the troops on the front lines call these? Priests in a bottle...\n\n<Packmaster Stonebruiser sings.>\n\n\"I'm your priest in a bott-le baby... you gotta drink me the right way...\"\n\nWhat's the matter sonny? It's a very popular song around these parts." }
WordHunterWoW_QuestEN[9203] = { title = "Craftsman's Writ - Flask of Petrification", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order AL-90:\n\n1 Flask of Petrification.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 1 Flask of Petrification and the Craftsman's Writ - Flask of Petrification - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "No comment.\n\n<Packmaster Stonebruiser glares at you.>\n\nI said no comment! Now get out of my sight!" }
WordHunterWoW_QuestEN[9204] = { title = "Craftsman's Writ - Stonescale Eel", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order FS-5:\n\n40 Stonescale Eel.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 40 Stonescale Eel and the Craftsman's Writ - Stonescale Eel - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "You could have used this for something else, but you didn't, did you? No use crying about it now, {name}." }
WordHunterWoW_QuestEN[9205] = { title = "Craftsman's Writ - Plated Armorfish", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order FS-12:\n\n30 Plated Armorfish.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 30 Plated Armorfish and the Craftsman's Writ - Plated Armorfish - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "You really don't know what these are for?\n\n<Packmaster Stonebruiser laughs.>\n\nLike I'm going to tell you!" }
WordHunterWoW_QuestEN[9206] = { title = "Craftsman's Writ - Lightning Eel", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order FS-9:\n\n30 Lightning Eel.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 30 Lightning Eel and the Craftsman's Writ - Lightning Eel - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, {class}?", completion = "These make the best eel rolls in the world. That's right - IN THE WORLD." }
WordHunterWoW_QuestEN[9208] = { title = "The Savage Guard - Arcanum of Protection", description = "Zanza can create many ancient troll enchantments with proper components! Have you heard of the Savage Guard? No, of course you haven't. Your mind is addled with the inferior elven magic.\n\nBring me an arcanum of elven creation so that I may destroy the aberration. Do this and the Savage Guard will be yours.", objectives = "Zanza the Restless in Zul'Gurub wants an Arcanum of Protection.", progress = "Do you have the arcanum?", completion = "The worthless magic in these enchantments fuels my anger. My anger gives me strength.\n\nBring me more and you shall receive another Savage Guard." }
WordHunterWoW_QuestEN[9209] = { title = "The Savage Guard - Arcanum of Rapidity", description = "Zanza can create many ancient troll enchantments with proper components! Have you heard of the Savage Guard? No, of course you haven't. Your mind is addled with the inferior elven magic.\n\nBring me an arcanum of elven creation so that I may destroy the aberration. Do this and the Savage Guard will be yours.", objectives = "Zanza the Restless in Zul'Gurub wants an Arcanum of Rapidity.", progress = "Do you have the arcanum?", completion = "The worthless magic in these enchantments fuels my anger. My anger gives me strength.\n\nBring me more and you shall receive another Savage Guard." }
WordHunterWoW_QuestEN[9210] = { title = "The Savage Guard - Arcanum of Focus", description = "Zanza can create many ancient troll enchantments with proper components! Have you heard of the Savage Guard? No, of course you haven't. Your mind is addled with the inferior elven magic.\n\nBring me an arcanum of elven creation so that I may destroy the aberration. Do this and the Savage Guard will be yours.", objectives = "Zanza the Restless in Zul'Gurub wants an Arcanum of Focus.", progress = "Do you have the arcanum?", completion = "The worthless magic in these enchantments fuels my anger. My anger gives me strength.\n\nBring me more and you shall receive another Savage Guard." }
WordHunterWoW_QuestEN[9211] = { title = "The Ice Guard", description = "Ah, the Ice Guard. It is a thin sheen of protective magic that covers certain pieces of equipment. Those that do battle with creatures of frost and ice will gain increased protection from their attacks by using the Ice Guard.\n\nAs with all things the Wrathcaster creates, there is a price - a price that I will not lower, regardless of how much you whimper. Interested?", objectives = "Mataus the Wrathcaster at Light's Hope Chapel in the Eastern Plaguelands wants 10 Insignia of the Crusade and 30 gold.", progress = "If it were not for these Argent Dawn guards, you would be a stain upon this floor.", completion = "<Mataus pockets the gold.>\n\nEnjoy the repair costs, {race}. Naxxramas is 'unkind' to the uninitiated." }
WordHunterWoW_QuestEN[9213] = { title = "The Shadow Guard", description = "A creation of genius! Much like the Ice Guard, the Shadow Guard employs a thin sheen of protective magic that covers certain pieces of equipment. And like the Ice Guard, the Shadow Guard is going to cost you a good amount of money.\n\n<Mataus holds his hand out and rubs his fingers together.>\n\nInterested?", objectives = "Mataus the Wrathcaster at Light's Hope Chapel in the Eastern Plaguelands wants 10 Insignia of the Crusade and 30 gold.", progress = "<Mataus yawns.>\n\nBe gone, insect, lest you have something for me.", completion = "<Mataus stuffs the gold into his robe.>\n\nWhat are you still standing around for, {race}? Our business is done." }
WordHunterWoW_QuestEN[9221] = { title = "Superior Armaments of Battle - Friend of the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?\n\nI must warn you; purchases made at a friendly reputation with the Dawn come with a hefty surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.", objectives = "For 30 Insignias of the Dawn and 30 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", completion = "Good day, {name}. It was a pleasure doing business with you." }
WordHunterWoW_QuestEN[9222] = { title = "Epic Armaments of Battle - Friend of the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?\n\nI must warn you; purchases made at a friendly reputation with the Dawn come with an extremely hefty surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.", objectives = "For 110 Insignias of the Dawn and 110 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", completion = "Good day, {name}. It was a pleasure doing business with you." }
WordHunterWoW_QuestEN[9223] = { title = "Superior Armaments of Battle - Honored Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?\n\nI must warn you; purchases made at honored reputation with the Dawn come with a fairly prohibitive surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.", objectives = "For 20 Insignias of the Dawn and 20 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", progress = "Choose carefully. There are no refunds.", completion = "Good day, {name}. It was a pleasure doing business with you." }
WordHunterWoW_QuestEN[9224] = { title = "Epic Armaments of Battle - Honored Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?\n\nI must warn you; purchases made at honored reputation with the Dawn come with an extremely hefty surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.", objectives = "For 75 Insignias of the Dawn and 75 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", completion = "Good day, {name}. It was a pleasure doing business with you." }
WordHunterWoW_QuestEN[9225] = { title = "Epic Armaments of Battle - Revered Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?\n\nI must warn you; epic purchases made at revered reputation with the Dawn are still quite expensive. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.", objectives = "For 45 Insignias of the Dawn and 45 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", progress = "Choose carefully. There are no refunds.", completion = "Good day, {name}. It was a pleasure doing business with you." }
WordHunterWoW_QuestEN[9226] = { title = "Superior Armaments of Battle - Revered Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?\n\nItems offered to those revered amongst the Dawn are priced quite reasonably. I encourage you to make a purchase!", objectives = "For 7 Insignias of the Dawn and 7 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", progress = "Choose carefully. There are no refunds.", completion = "Good day, {name}. It was a pleasure doing business with you." }
WordHunterWoW_QuestEN[9227] = { title = "Superior Armaments of Battle - Exalted Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?\n\nItems offered to those exalted amongst the Dawn are discounted. I encourage you to make a purchase!", objectives = "For 6 Insignias of the Dawn and 6 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", progress = "Choose carefully. There are no refunds.", completion = "Good day, {name}. It was a pleasure doing business with you." }
WordHunterWoW_QuestEN[9228] = { title = "Epic Armaments of Battle - Exalted Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?\n\nThose exalted amongst the Dawn receive our greatest discounts! I encourage you to make a purchase.", objectives = "For 27 Insignias of the Dawn and 27 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", progress = "Choose carefully. There are no refunds.", completion = "Good day, {name}. It was a pleasure doing business with you." }
WordHunterWoW_QuestEN[9229] = { title = "The Fate of Ramaladni", description = "Ramaladni was a warrior of the Brotherhood - a pupil of Highlord Mograine before the Dawn even existed! When news of Mograine's death reached him, hatred and anger took over.\n\nUnderstand this, {name}, when rage and retribution take the reins, a man ceases to be a man. The man personifies the emotions that control him instead. And so it would be that Ramaladni, the spirit of retribution, would enter Naxxramas to exact vengeance... and never return.\n\nEnter Naxxramas and find what became of Ramaladni.", objectives = "Enter Naxxramas and uncover the Fate of Ramaladni.", progress = "Any news of Ramaladni?", completion = "It is his ring! But it is destroyed. No other evidence of Ramaladni was found?\n\n<Korfax grimaces.>\n\nThis does not bode well for Ramaladni. The ring, however... it might be salvageable." }
WordHunterWoW_QuestEN[9230] = { title = "Ramaladni's Icy Grasp", description = "Fixing this band may prove to be quite challenging, {name}. You see, it was made from the very runes that form inside Scourge structures - like Naxxramas. Additional materials are also required but your main concern should be getting those frozen runes. Bring me what I need and I will restore the ring to its former glory.", objectives = "Korfax at Light's Hope Chapel in the Eastern Plaguelands wants you to bring him 1 Frozen Rune, 1 Blue Sapphire and 1 Arcanite Bar.", progress = "Frozen runes could probably be found inside Naxxramas.", completion = "Ramaladni himself couldn't have done better! Here is the ring, as promised." }
WordHunterWoW_QuestEN[9232] = { title = "The Only Song I Know...", description = "You fancy yourself a hero of the Dawn, eh? I've seen our greatest soldiers get rolled over by Kel'Thuzad's plebes! How well could someone so clueless possibly fare in Naxxramas?\n\n<Wilhelm sighs.>\n\nBah, what choice do I got? You're the best I can do; I may as well help you.\n\nOmarion left me with one recipe. It's the only song I know... I can make a few variations of these pants; you just gotta supply the materials.", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants you to bring him 2 Frozen Runes, 2 Essence of Water, 2 Blue Sapphires and 30 gold pieces.", progress = "You haven't run into Omarion, have you?", completion = "<Wilhelm wipes the sweat from his brow.>\n\nThat's some hard work! Enjoy the pants, {class}. At least you'll die in a clean pair now." }
WordHunterWoW_QuestEN[9233] = { title = "Omarion's Handbook", description = "Wilhelm,\n\nIf you are reading this, I have perished - finally. I want you to know that my dying thoughts revolved around you and your ineptitude when it comes to tradeskills. Unfortunately, the bearer of this handbook is in even worse shape than you in regards to crafting.\n\nAbout the book: These are the rest of my recipes. Make the bearer of this book whatever they request. I'm sure you will charge a hefty fee for your services because you are, after all, a bastard.\n\nIn Disdain,\n\nOmarion", objectives = "Take Omarion's Handbook to Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Is that what I think it is?\n\n<Wilhelm appears to be drooling.>", completion = "He musta really been off his rocker when he wrote this! Omarion and I - we were thick as thieves!\n\nAnyhow, this certainly opens up some new possibilities, {name}. I am now able to craft more items - for a small fee and material charges, of course." }
WordHunterWoW_QuestEN[9234] = { title = "Icebane Gauntlets", description = "Thanks to you and Omarion, may he rest in peace, I am now able to create Icebane gauntlets. All you need to do is bring me the materials and pay a small crafting fee.", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 5 Frozen Runes, 12 Thorium Bars, 2 Arcanite Bars, 2 Essences of Water and 200 gold.", progress = "Have you brought the materials?", completion = "Here is your order, {name}. Delivered as promised!" }
WordHunterWoW_QuestEN[9235] = { title = "Icebane Bracers", description = "Thanks to you and Omarion (May he rest in peace), I am now able to create Icebane bracers. All you need to do is bring me the materials and pay a small crafting fee.", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 4 Frozen Runes, 12 Thorium Bars, 2 Arcanite Bars, 2 Essence of Water and 200 gold.", progress = "Have you brought the materials?", completion = "Here is your order, {name}. Delivered as promised!" }
WordHunterWoW_QuestEN[9236] = { title = "Icebane Breastplate", description = "Thanks to you and Omarion (May he rest in peace), I am now able to create an Icebane breastplate. All you need to do is bring me the materials and pay a small crafting fee.", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 8 Frozen Runes, 16 Thorium Bars, 2 Arcanite Bars, 4 Essence of Water and 300 gold. You will also need to be of Exalted reputation with the Argent Dawn.", progress = "Have you brought the materials?", completion = "Here is your order, {name}. Delivered as promised!" }
WordHunterWoW_QuestEN[9237] = { title = "Glacial Cloak", description = "Thanks to you and Omarion, may he rest in peace, I am now able to create a Glacial cloak. All you need to do is bring me the materials and pay a small crafting fee.", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 5 Frozen Runes, 4 Bolts of Runecloth, 2 Essences of Water, 4 Ironweb Spider Silks and 200 gold. You must also be of Exalted reputation with the Argent Dawn.", progress = "Have you brought the materials?", completion = "Here is your order, {name}. Delivered as promised!" }
WordHunterWoW_QuestEN[9238] = { title = "Glacial Wrists", description = "Thanks to you and Omarion, may he rest in peace, I am now able to create Glacial wrists. All you need to do is bring me the materials and pay a small crafting fee.", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 4 Frozen Runes, 2 Bolts of Runecloth, 2 Essences of Water, 2 Ironweb Spider Silks and 200 gold.", completion = "Now that's one face I was not expecting to see so soon.\n\nThis is quite the good news. {name}, in more ways than you can imagine." }
WordHunterWoW_QuestEN[9239] = { title = "Glacial Gloves", description = "Thanks to you and Omarion, may he rest in peace, I am now able to create Glacial gloves. All you need to do is bring me the materials and pay a small crafting fee.", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 5 Frozen Runes, 4 Bolts of Runecloth, 4 Essences of Water, 2 Ironweb Spider Silks and 200 gold.", completion = "Here is your order, {name}. Delivered as promised!" }
WordHunterWoW_QuestEN[9240] = { title = "Glacial Vest", description = "Thanks to you and Omarion, may he rest in peace, I am now able to create a Glacial vest. All you need to do is bring me the materials and pay a small crafting fee.", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 8 Frozen Runes, 8 Bolts of Runecloth, 6 Essences of Water, 4 Ironweb Spider Silks and 300 gold. You must also be of Exalted reputation with the Argent Dawn.", completion = "Here is your order, {name}. Delivered as promised!" }
WordHunterWoW_QuestEN[9241] = { title = "Polar Bracers", description = "Thanks to you and Omarion (May he rest in peace), I am now able to create Polar bracers. All you need to do is bring me the materials and pay a small crafting fee.", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 4 Frozen Runes, 12 Enchanted Leather, 3 Essence of Water, 3 Cured Rugged Hides and 200 gold.", progress = "Have you brought the materials?", completion = "Here is your order, {name}. Delivered as promised!" }
WordHunterWoW_QuestEN[9242] = { title = "Polar Gloves", description = "Thanks to you and Omarion (May he rest in peace), I am now able to create Polar gloves. All you need to do is bring me the materials and pay a small crafting fee.", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 5 Frozen Runes, 12 Enchanted Leather, 3 Essence of Water, 3 Cured Rugged Hides and 200 gold.", progress = "Have you brought the materials?", completion = "Here is your order, {name}. Delivered as promised!" }
WordHunterWoW_QuestEN[9243] = { title = "Polar Tunic", description = "Thanks to you and Omarion, may he rest in peace, I am now able to create a Polar tunic. All you need to do is bring me the materials and pay a small crafting fee.", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 8 Frozen Runes, 16 Enchanted Leathers, 5 Essences of Water, 5 Cured Rugged Hides and 300 gold. You must also be of Exalted reputation with the Argent Dawn.", completion = "Here is your order, {name}. Delivered as promised!" }
WordHunterWoW_QuestEN[9244] = { title = "Icy Scale Bracers", description = "Thanks to you and Omarion, may he rest in peace, I am now able to create Icy Scale bracers. All you need to do is bring me the materials and pay a small crafting fee.", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 4 Frozen Runes, 16 Heavy Scorpid Scales, 5 Essences of Water, 3 Cured Rugged Hides and 200 gold.", completion = "Here is your order, {name}. Delivered as promised!" }
WordHunterWoW_QuestEN[9245] = { title = "Icy Scale Gauntlets", description = "Thanks to you and Omarion (May he rest in peace), I am now able to create Icy Scale gauntlets. All you need to do is bring me the materials and pay a small crafting fee.", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 5 Frozen Runes, 16 Heavy Scorpid Scale, 5 Essence of Water, 3 Cured Rugged Hides and 200 gold.", completion = "Here is your order, {name}. Delivered as promised!" }
WordHunterWoW_QuestEN[9246] = { title = "Icy Scale Breastplate", description = "Thanks to you and Omarion (May he rest in peace), I am now able to create an Icy Scale breastplate. All you need to do is bring me the materials and pay a small crafting fee.", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 8 Frozen Runes, 24 Heavy Scorpid Scale, 7 Essence of Water, 5 Cured Rugged Hides and 300 gold. You must also be of Exalted reputation with the Argent Dawn.", completion = "Here is your order, {name}. Delivered as promised!" }
WordHunterWoW_QuestEN[9247] = { title = "The Keeper's Call", description = "{name},\n\nIn times past you have served the interests of the Argent Dawn, always to the best of your abilities. Now, once again, we sound the clarion call in our time of greatest need.\n\n{name}, please report to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands if you are willing to aid us once more.", objectives = "Take the Letter from the Keeper of the Rolls to him at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Ah, {name}, it is good to see you.", completion = "Simply by answering the call, we are in your debt, {name}. The Argent Dawn is certain that through your shining example, others that are here to aid us will gain great insight into how best to throw back this Scourge Invasion!" }
WordHunterWoW_QuestEN[9248] = { title = "A Humble Offering", description = "Ishnu-alah, {race}. Show me proof of the demise of a Lord of the Abyssal Council and I shall reward you with an item that should aid you in your battles against the Qiraji.", objectives = "Aurel Goldleaf at Cenarion Hold in Silithus wants you to bring her 1 Abyssal Scepter. You must also be Honored with the Cenarion Circle.", progress = "Fandu-dath-belore? Oh, pardon me, {name}. I did not recognize you. Have you the scepter?", completion = "Ande'thoras-ethil. It means; 'May your troubles be diminished,' in my native tongue.\n\nWear the band proudly and in good health, {name}." }
WordHunterWoW_QuestEN[9249] = { title = "40 Tickets - Schematic: Steam Tonk Controller", description = "", objectives = "" }
WordHunterWoW_QuestEN[9250] = { title = "Frame of Atiesh", description = "With the frame formed, Atiesh is nearly whole. Only the head and base of the staff are now missing. There is also a minor issue regarding the staff being a conduit for Sargeras's evil.\n\nFind someone that can assist you in locating the remaining pieces and exorcising the evil from the staff.", objectives = "Find someone that will help you in recovering the last two pieces of the staff and ridding it of evil.", progress = "It was her time, mortal.", completion = "The archmages have died.\n\nDo not mourn their passing, {name}. All such things are fated. Just as you holding the staff of the Guardian was fated..." }
WordHunterWoW_QuestEN[9251] = { title = "Atiesh, the Befouled Greatstaff", description = "You question why you are still alive. After all, you have in your possession an item of great evil. The answer is not clear, {name}. I only do as I must.\n\nKel'Thuzad sits atop his throne in Naxxramas, plotting... He seeks that which you hold and holds that which you seek.\n\nAs for the base of the staff; the dwarf, Brann Bronzebeard, held it when he entered Ahn'Qiraj. He has left Ahn'Qiraj but the base of Atiesh remains.\n\nShould you succeed in recovering the pieces, return them to me.", objectives = "Anachronos at the Caverns of Time in Tanaris wants the Staff Head of Atiesh and the Base of Atiesh.", progress = "In its current form, the staff is far too dangerous to be in the hands of a mortal.", completion = "There is a being within... a being not of this world." }
WordHunterWoW_QuestEN[9257] = { title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", objectives = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.", completion = "The magnitude of this accomplishment must not be understated, {name}. You have done what most would have thought to be impossible. Alas, it was fated. The staff has made its choice..." }
WordHunterWoW_QuestEN[9259] = { title = "Traitor to the Bloodsail", description = "", objectives = "That mangy dog, Revilgaz, has offered to pardon any former Bloodsails willing to turn on their cap'n!  That bilge sucker asked me to go an' off me ole' mates and to bring back their bandannas as proof.\n\nI don't have it in me heart to do that, nor will I ask ye to.  Bring me some silk cloth and red dye and I'll make suitable replicas.  I'll tell the Baron you went turncoat, but be warned... the Bloodsails are not gonna like it!", progress = "That mangy dog, Revilgaz, has offered to pardon any former Bloodsails willing to turn on their cap'n!  That bilge sucker asked me to go an' off me ole' mates and to bring back their bandannas as proof.\n\nI don't have it in me heart to do that, nor will I ask ye to.  Bring me some silk cloth and red dye and I'll make suitable replicas.  I'll tell the Baron you went turncoat, but be warned... the Bloodsails are not gonna like it!", completion = "Let us observe a minute of silence for our fallen mates, {name}.\n\n\n\nBeing a traitor is one thing, murdering yer own buckos... that'd be just downright despicable, aye!" }
WordHunterWoW_QuestEN[9260] = { title = "Investigate the Scourge of Stormwind", description = "The Scourge is camped upon our very doorstep; we cannot remain idle! Surely you will step up to defend Stormwind from these accursed invaders? \n\nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "Collect three Dim Necrotic Stones from the Scourge outside Stormwind and investigate the glowing runic circles near their encampment.", progress = "Have you investigated the invasion yet? There's no time for dawdling!", completion = "Hmm. From what you've told me, the voices within the circles... they must be used for communication of some kind. I shudder to think what unnatural minds are contacted through such magic. Regardless, you seem to have emerged whole and sane.  The Argent Dawn appreciates your service." }
WordHunterWoW_QuestEN[9261] = { title = "Investigate the Scourge of Ironforge", description = "The Scourge is camped upon our very doorstep; we cannot remain idle! Surely you will step up to defend Ironforge from these accursed invaders? \n\nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "Collect three Dim Necrotic Stones from the Scourge outside Ironforge and investigate the glowing runic circles near their encampment.", progress = "Have you investigated the invasion yet? There's no time for dawdling!", completion = "Hmm. From what you've told me, the voices within the circles... they must be used for communication of some kind. I shudder to think what unnatural minds are contacted through such magic. Regardless, you seem to have emerged whole and sane.  The Argent Dawn appreciates your service." }
