WordHunterWoW_QuestEN[9265] = { title = "Investigate the Scourge of the Undercity", description = "The Scourge is camped upon our very doorstep; we cannot remain idle! Surely you will step up to defend the Undercity from these accursed invaders? \n\nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "Collect three Dim Necrotic Stones from the Scourge outside the Undercity and investigate the glowing runic circles near their encampment.", progress = "Have you investigated the invasion yet? There's no time for dawdling!", completion = "Hmm. From what you've told me, the voices within the circles... they must be used for communication of some kind. I shudder to think what unnatural minds are contacted through such magic. Regardless, you seem to have emerged whole and sane.  The Argent Dawn appreciates your service." }
WordHunterWoW_QuestEN[9266] = { title = "Making Amends", description = "", objectives = "You must've done something really bad to us or our friends, {name}.  At any rate, I'm here to offer you a way to get our good graces back.\n\nAs you know, Winterspring is quite cold.  With so many of us goblins coming from other cities, we could use a hand keeping warm.  Bring me some runecloth and coal and I'll put in the good word for ya.  Be warned though, our enemies are not going to take kindly to your helping us.", progress = "You must've done something really bad to us or our friends, {name}.  At any rate, I'm here to offer you a way to get our good graces back.\n\nAs you know, Winterspring is quite cold.  With so many of us goblins coming from other cities, we could use a hand keeping warm.  Bring me some runecloth and coal and I'll put in the good word for ya.  Be warned though, our enemies are not going to take kindly to your helping us.", completion = "Thank you, {name}.  You're on a quick path to redeeming yourself with our fair town." }
WordHunterWoW_QuestEN[9267] = { title = "Mending Old Wounds", description = "", objectives = "You'd better think twice before setting foot in Ratchet, {name}!  Word's been getting around of your dirty deeds.\n\nYou're in luck though, a ship just arrived with many wounded from an encounter with the Bloodsail Buccaneers.  This is your chance to prove you're not a complete scoundrel.  Lend us a hand by bringing linen cloth for bandages and empty vials for potions.", progress = "You'd better think twice before setting foot in Ratchet, {name}!  Word's been getting around of your dirty deeds.\n\nYou're in luck though, a ship just arrived with many wounded from an encounter with the Bloodsail Buccaneers.  This is your chance to prove you're not a complete scoundrel.  Lend us a hand by bringing linen cloth for bandages and empty vials for potions.", completion = "I'm happy you're seeing the error of your ways, {name}.  Keep the supplies coming; we're not going to forget about you so easily, mister!" }
WordHunterWoW_QuestEN[9268] = { title = "War at Sea", description = "", objectives = "You seek to befriend the goblins of Tanaris once again, {name}?  We're in need of materials for sails and guns to fight off our old enemies, the Bloodsail Buccaneers.  Bring me mageweave and strong flux and we'll be on our way to pardoning your trespasses.", progress = "You seek to befriend the goblins of Tanaris once again, {name}?  We're in need of materials for sails and guns to fight off our old enemies, the Bloodsail Buccaneers.  Bring me mageweave and strong flux and we'll be on our way to pardoning your trespasses.", completion = "Keep it coming, {name}.  Us goblins don't forget that easily!" }
WordHunterWoW_QuestEN[9269] = { title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", objectives = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.", completion = "The magnitude of this accomplishment must not be understated, {name}. You have done what most would have thought to be impossible. Alas, it was fated. The staff has made its choice..." }
WordHunterWoW_QuestEN[9270] = { title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", objectives = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.", progress = "I must not interfere, {race}.", completion = "The magnitude of this accomplishment must not be understated, {name}. You have done what most would have thought to be impossible. Alas, it was fated. The staff has made its choice..." }
WordHunterWoW_QuestEN[9271] = { title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", objectives = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.", completion = "The magnitude of this accomplishment must not be understated, {name}. You have done what most would have thought to be impossible. Alas, it was fated. The staff has made its choice..." }
WordHunterWoW_QuestEN[9272] = { title = "Dressing the Part", description = "", objectives = "Yarrr... if ye be keen on enjoying the company of us experienced sea dogs, you'd best belay dressing like a blaggard!  Here, put on something proper 'fore I keelhaul yer hide.\n\nThese'll fit ye better than they ever fit that old dog, Red-Eyed Ben.  Lost him in a devil of a storm at sea.\n\nWear 'em with pride, mate!", completion = "Yarrr... if ye be keen on enjoying the company of us experienced sea dogs, you'd best belay dressing like a blaggard! Here, put on something proper 'fore I keelhaul yer hide.\n\nThese'll fit ye better than they ever fit that old dog, Red-Eyed Ben. Lost him in a devil of a storm at sea.\n\nWear 'em with pride, mate!" }
WordHunterWoW_QuestEN[9273] = { title = "Redeem iCoke Prize Voucher", description = "", objectives = "" }
WordHunterWoW_QuestEN[9292] = { title = "Cracked Necrotic Crystal", description = "On the corpse of the fallen abomination, you discover a cracked crystal, slowly pulsing with necrotic energy.", objectives = "Bring the Cracked Necrotic Crystal to Lieutenant Orrin outside the gates of Stormwind.", progress = "Is there something you need?", completion = "Hm, you took this from the corpse of one of the invading abominations?\n\nWe have received word about the necropolis base camps that are being summoned by the Scourge. I suspect they wanted to create one inside Stormwind. It is good that they were unsuccessful." }
WordHunterWoW_QuestEN[9295] = { title = "Letter from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", objectives = "Take the Torn Letter to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Yes? What do you have there?", completion = "How tragic. These words, clearly meant for someone the soldier loved, never made it to their destination. The events detailed happened years ago; I'm not sure if the intended recipient still lives.\n\nThere is hope yet, however. With the names and information he gives, I might be able to locate the family! It will take some research, but the librarian in Stormwind owes me a favor...\n\nThank you for bringing this to me. With your help, we may be able to grant someone peace of mind at last." }
WordHunterWoW_QuestEN[9296] = { title = "reuse", description = "This stone radiates a dark energy. You should deliver it to SOMEONE.", objectives = "Deliver the Dim Necrotic Stone to SOMEONE." }
WordHunterWoW_QuestEN[9297] = { title = "reuse", description = "This stone radiates a dark energy. You should deliver it to SOMEONE.", objectives = "Deliver the Dim Necrotic Stone to SOMEONE." }
WordHunterWoW_QuestEN[9298] = { title = "reuse", description = "This stone radiates a dark energy. You should deliver it to SOMEONE.", objectives = "Deliver the Dim Necrotic Stone to SOMEONE." }
