WordHunterWoW_QuestEN[9304] = { title = "Document from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", objectives = "Take the Smudged Document to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Yes? What do you have there?", completion = "How tragic. These words, clearly meant for someone the soldier loved, never made it to their destination. The events detailed happened years ago; I'm not sure if the intended recipient still lives.\n\nThere is hope yet, however. With the names and information he gives, I might be able to locate the family! It will take some research, but the librarian in Stormwind owes me a favor...\n\nThank you for bringing this to me. With your help, we may be able to grant someone peace of mind at last." }
WordHunterWoW_QuestEN[9310] = { title = "Faint Necrotic Crystal", description = "On the corpse of the fallen wight, you find a crystal that is faintly radiating necrotic energy.", objectives = "Bring the Faint Necrotic Crystal to Lieutenant Rukag in the courtyard of the Undercity.", progress = "Can I help you with something?", completion = "You say this was taken from a wight attacking the city?\n\nWe have received word about the necropolis base camps that are being summoned by the Scourge. I suspect they were trying to create one in the Undercity. We will have to be vigilant in the future." }
WordHunterWoW_QuestEN[9317] = { title = "Consecrated Sharpening Stones", description = "", objectives = "If you bring me eight necrotic runes from the Scourge invaders, I can give you a consecrated sharpening stone. It should be of great help in your battle against the minions of the Lich King.", progress = "If you bring me eight necrotic runes from the Scourge invaders, I can give you a consecrated sharpening stone. It should be of great help in your battle against the minions of the Lich King.", completion = "Thank you, {name}. Here are your consecrated sharpening stones. Use them prudently." }
WordHunterWoW_QuestEN[9318] = { title = "Blessed Wizard Oil", description = "", objectives = "In exchange for the necrotic runes of the Scourge invaders, the Argent Dawn will give you one vial of blessed wizard oil.", progress = "In exchange for the necrotic runes of the Scourge invaders, the Argent Dawn will give you one vial of blessed wizard oil.", completion = "I hope that you will find these items useful in future battles." }
WordHunterWoW_QuestEN[9319] = { title = "A Light in Dark Places", description = "We are not the only ones who celebrate this holiday, {name}. All creatures, all cultures, are touched by the flame. Even in the darkest places, the fires are being lit.\n\nIf you wish to see them for yourself, travel into the depths. Seek out the bonfires burning within Stratholme, Scholomance, among the ogres of Dire Maul, and the halls of Blackrock Spire itself; I will await your return.", objectives = "Find and touch the bonfires located within Blackrock Spire, Dire Maul, Scholomance, and Stratholme, then return to the Festival Flamekeeper.", completion = "Your essence sings with the energy of the flames you found, {name}. The fire you encountered is potent, and with the right knowledge, its power can be harnessed...\n\n\n\nAh! Here we are. May this light your path, no matter where you tread." }
WordHunterWoW_QuestEN[9320] = { title = "Major Mana Potion", description = "", objectives = "In addition to our other supplies, we also have a number of major mana potions you may find useful. I will give you one in exchange for fifteen necrotic runes.", progress = "In addition to our other supplies, we also have a number of major mana potions you may find useful. I will give you one in exchange for fifteen necrotic runes.", completion = "Here you are, {name}. Be careful out there. Our numbers are not so large we can afford many battlefield casualties." }
WordHunterWoW_QuestEN[9321] = { title = "Major Healing Potion", description = "", objectives = "In addition to our other supplies, we also have a number of major healing potions you may find useful. I will give you one in exchange for fifteen necrotic runes.", progress = "In addition to our other supplies, we also have a number of major healing potions you may find useful. I will give you one in exchange for fifteen necrotic runes.", completion = "Here you are, {name}. Be careful out there. Our numbers are not so large we can afford many battlefield casualties." }
WordHunterWoW_QuestEN[9322] = { title = "Wild Fires in Kalimdor", description = "The Midsummer Fire Festival is celebrated everywhere in Azeroth, and the diverse land of Kalimdor is no exception. You look fit to travel -- perhaps a journey is in order.\n\nMidsummer cannot be truly appreciated unless you've seen the blistering blue fires abroad. The celebrants have lit fires in chilly western Winterspring, northeastern Azshara, near Valor's Rest in the wastes of Silithus, and by the entrance to lush Un'Goro. Return once your journey is complete.", objectives = "Visit the Midsummer camps located in Azshara, Silithus, Un'Goro Crater, and Winterspring, then return to the Festival Flamekeeper.", completion = "Your spirit glows with the warmth of the Kalimdor fires, friend. Is the heat not invigorating?\n\n Once the power fades from you, perhaps these will help rekindle the feeling." }
WordHunterWoW_QuestEN[9323] = { title = "Wild Fires in the Eastern Kingdoms", description = "Our celebration of the flame is spread throughout the land, {class}. Not a single place remains untouched by the heat of this holiday, and the strongest fires burn a brilliant blue. Seek them out.\n\nYou'll find one just north of Blackrock Spire. The others are located deep within the Eastern Plaguelands near a decrepit town, along the road to the cliffs within the mountainous Hinterlands, and on the way to the Dark Portal within the Blasted Lands.\n\n Return once your journey is done.", objectives = "Visit the Fire Festival camps located in Blasted Lands, Eastern Plaguelands, the Hinterlands and Searing Gorge, then speak with the Festival Flamekeeper.", completion = "Ah, here you are. A little wearier, a bit dustier, but enlightened! The heat touches us all during this season and unites us; your very being glows with the power of the fires you touched.\n\nAh, but these days enlightenment is taken as a rather poor reward for being sent on a task, I suppose. Take these, then, and enjoy the celebration." }
WordHunterWoW_QuestEN[9324] = { title = "Stealing Orgrimmar's Flame", description = "This flame, stolen from the heart of Orgrimmar itself, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", objectives = "Return the Flame of Orgrimmar to the Festival Loremaster.", progress = "You're practically glowing, {race}. What do you have there?", completion = "What's this? Unless I'm mistaken, this flame has been taken from the heart of Orgrimmar itself! The fierce hearts of the orcs and trolls are reflected in its searing heat. What a fine addition to our collection--how brave you are, stealing into the enemy's lair to retrieve the sacred flame!\n\nI wonder what power lurks in the other cities..." }
WordHunterWoW_QuestEN[9325] = { title = "Stealing Thunder Bluff's Flame", description = "This flame, stolen from the shaman of Thunder Bluff, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", objectives = "Return the Flame of Thunder Bluff to the Festival Loremaster.", progress = "You're practically glowing, {race}. What do you have there?", completion = "Unless I miss my guess, this fire has been taken from the cliffs of Thunder Bluff! How it sings with the power of the spirits! You are quite the thief, {name}. Take this as just payment for your skill. Now, if only we had the flames of all three cities..." }
WordHunterWoW_QuestEN[9326] = { title = "Stealing the Undercity's Flame", description = "This flame, stolen from the ruins above the Undercity, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", objectives = "Return the Flame of the Undercity to the Festival Loremaster.", progress = "You're practically glowing, {race}. What do you have there?", completion = "Hm... what a strange fire! It is subdued, nearly smoldering, but the heat is intense. And you received this from the Undercity, you say? Fascinating. With the flames of all three cities, who knows what we could accomplish?" }
WordHunterWoW_QuestEN[9330] = { title = "Stealing Stormwind's Flame", description = "This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", objectives = "Return the Flame of Stormwind to the Festival Talespinner.", progress = "You're practically glowing, {race}. What do you have there?", completion = "And this brightly-burning fire... you say it came from Stormwind? Remarkable! That must have been quite an adventure! I'll pay you for this, of course. If you find anything else like this, be sure to speak with me again." }
WordHunterWoW_QuestEN[9331] = { title = "Stealing Ironforge's Flame", description = "This flame, stolen from the heart of Ironforge itself, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", objectives = "Return the Flame of Ironforge to the Festival Talespinner.", progress = "You're practically glowing, {race}. What do you have there?", completion = "This hearty flame must be from the halls of Ironforge; it's as stalwart as the dwarves themselves. A fine catch, {name}. If I had the fires of the other cities... ah, but never mind. Here is your payment." }
WordHunterWoW_QuestEN[9332] = { title = "Stealing Darnassus's Flame", description = "This flame, stolen from the shores of Teldrassil, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", objectives = "Return the Flame of Darnassus to the Festival Talespinner.", progress = "You're practically glowing, {race}. What do you have there?", completion = "This fire aches of ancient sorrow, {name}. You pulled this from the roots of Teldrassil, you say? Fascinating! Here is a reward for your skill. Return to me should you find anything else like this; I may have a use for it." }
WordHunterWoW_QuestEN[9333] = { title = "Argent Dawn Gloves", description = "", objectives = "If you bring me thirty necrotic runes, I will give you your choice of hand protection in return. These should prove valuable in our fight against the undead Scourge.", progress = "If you bring me thirty necrotic runes, I will give you your choice of hand protection in return. These should prove valuable in our fight against the undead Scourge.", completion = "You've done well, {name}. Take your pick of hand protection in thanks for your efforts." }
WordHunterWoW_QuestEN[9334] = { title = "Blessed Wizard Oil", description = "", objectives = "In exchange for the necrotic runes of the Scourge invaders, the Argent Dawn will give you one vial of blessed wizard oil.", progress = "In exchange for the necrotic runes of the Scourge invaders, the Argent Dawn will give you one vial of blessed wizard oil.", completion = "I hope that you will find these items useful in future battles." }
WordHunterWoW_QuestEN[9335] = { title = "Consecrated Sharpening Stones", description = "", objectives = "If you bring me eight necrotic runes from the Scourge invaders, I can give you a consecrated sharpening stone. It should be of great help in your battle against the minions of the Lich King.", progress = "If you bring me eight necrotic runes from the Scourge invaders, I can give you a consecrated sharpening stone. It should be of great help in your battle against the minions of the Lich King.", completion = "Thank you, {name}. Here are your consecrated sharpening stones. Use them prudently." }
WordHunterWoW_QuestEN[9336] = { title = "Major Healing Potion", description = "", objectives = "In addition to our other supplies, we also have a number of major healing potions you may find useful. I will give you one in exchange for fifteen necrotic runes.", progress = "In addition to our other supplies, we also have a number of major healing potions you may find useful. I will give you one in exchange for fifteen necrotic runes.", completion = "Here you are, {name}. Be careful out there. Our numbers are not so large we can afford many battlefield casualties." }
WordHunterWoW_QuestEN[9337] = { title = "Major Mana Potion", description = "", objectives = "In addition to our other supplies, we also have a number of major mana potions you may find useful. I will give you one in exchange for fifteen necrotic runes.", progress = "In addition to our other supplies, we also have a number of major mana potions you may find useful. I will give you one in exchange for fifteen necrotic runes.", completion = "Here you are, {name}. Be careful out there. Our numbers are not so large we can afford many battlefield casualties." }
WordHunterWoW_QuestEN[9338] = { title = "Allegiance to Cenarion Circle", description = "", objectives = "Even if you have no need for the material rewards we offer, these badges still mark our mutual trust and friendship.\n\nBring them to me.  I'll make due note of your service should your performance go above and beyond the call of duty.", progress = "Even if you have no need for the material rewards we offer, these badges still mark our mutual trust and friendship.\n\nBring them to me.  I'll make due note of your service should your performance go above and beyond the call of duty.", completion = "You honor us, {name}.  With your continued efforts we will overcome all obstacles." }
WordHunterWoW_QuestEN[9339] = { title = "A Thief's Reward", description = "This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the (NAME) might know more...", objectives = "Return the Flame of Stormwind to (NAME).", completion = "You've proven yourself today, {name}.\n\nWhile I have little else to give you, I do have this crown; a fitting gift for a conqueror. May it light your way." }
WordHunterWoW_QuestEN[9341] = { title = "Tabard of the Argent Dawn", description = "", objectives = "You have aided our cause greatly, {name}. If you wish, I can make available the tabard of the Argent Dawn. We are proud to have you among our allies.", progress = "You have aided our cause greatly, {name}. If you wish, I can make available the tabard of the Argent Dawn. We are proud to have you among our allies.", completion = "Take this tabard and wear it proudly. Perhaps your deeds might inspire others to take up arms in support of our fight against the Scourge." }
WordHunterWoW_QuestEN[9343] = { title = "Tabard of the Argent Dawn", description = "", objectives = "You have aided our cause greatly, {name}. If you wish, I can make available the tabard of the Argent Dawn. We are proud to have you among our allies.", progress = "You have aided our cause greatly, {name}. If you wish, I can make available the tabard of the Argent Dawn. We are proud to have you among our allies.", completion = "Take this tabard and wear it proudly. Perhaps your deeds might inspire others to take up arms in support of our fight against the Scourge." }
WordHunterWoW_QuestEN[9353] = { title = "Redeem iCoke Gift Box Voucher", description = "", objectives = "" }
WordHunterWoW_QuestEN[9362] = { title = "Warlord Krellian", description = "There isn't much time, {name}!  My scrying spells have revealed a powerful source of magic.  I cannot leave the tower, and would ask you to kill the vile creature in possession of this artifact.\n\nThe pathetic little cretin is known as Warlord Krellian, hiding behind his guards in the Temple of Zin-Malor.  Burn him to ashes and take the prismatic shell he covets so dearly.", objectives = "Retrieve the Prismatic Shell for Archmage Xylem. The Archmage resides in a tower atop the cliffs of Azshara.", progress = "There is not time to waste!  Have you the shell?", completion = "I must say, this shell has a strange aura.  It seems only fitting that part of your reward for retrieving it would be to test its magical capabilities..." }
WordHunterWoW_QuestEN[9364] = { title = "Fragmented Magic", description = "My research has revealed a unique purpose for the prismatic shell.\n\nCarry the shell and cast your polymorph spell on the Spitelash in Azshara.  If you wait a few moments, the chaotic aura of the shell will cause them to split into several smaller clones for a few moments.  Kill these clones as quickly as possible, and the shell will collect their essence.\n\nWhen the shell is full, return it to me.", objectives = "Polymorph the Spitelash of Azshara and kill the clones that appear several seconds later. When you have slain 50 Polymorph Clones, return to Archmage Xylem in Azshara.", progress = "Have you collected the magic?", completion = "Splendid!  Splendid!\n\nNow we are able to reform this magic into a new spell.  Behold!" }
WordHunterWoW_QuestEN[9365] = { title = "A Thief's Reward", description = "This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the (NAME) might know more...", objectives = "Return the Flame of Stormwind to (NAME).", completion = "You've proven yourself today, {name}.\n\nWhile I have little else to give you, I do have this crown; a fitting gift for a conqueror. May it light your way." }
WordHunterWoW_QuestEN[9367] = { title = "The Festival of Fire", description = "Midsummer is upon us once again!\n\nEach year, as tradition dictates, Flamekeepers are chosen to tend the bonfires within our capitals. While fires are burning throughout Azeroth, it is imperative that ours be the hottest and brightest, to properly pay homage to the season.\n\nIn fact, I have a task for you, if you don't mind. I've not yet heard if the fires in all capitals are properly burning. Travel there yourself and warm yourself by the fires--make sure they're hot!", objectives = "Touch the bonfires within Stormwind, Ironforge, and Darnassus, then speak to a Festival Loremaster within the capital cities.", progress = "Are the fires burning?", completion = "Excellent! It seems we've appointed dutiful Flamekeepers this year if the bonfires are as well-kept as you claim. Thank you for inspecting them for me; here, take this as a small token of my esteem." }
WordHunterWoW_QuestEN[9368] = { title = "The Festival of Fire", description = "Midsummer is upon us once again!\n\nEach year, as tradition dictates, Flamekeepers are chosen to tend the bonfires within our capitals. While fires are burning throughout Azeroth, it is imperative that ours be the hottest and brightest, to properly pay homage to the season.\n\nIn fact, I have a task for you, if you don't mind. I've not yet heard if the fires in all capitals are properly burning. Travel there yourself and warm yourself by the fires--make sure they're hot!", objectives = "Touch the bonfires within Orgrimmar, Thunder Bluff, and the Undercity, then speak to a Festival Talespinner within the capital cities.", progress = "Are the fires burning?", completion = "Excellent! It seems we've appointed dutiful Flamekeepers this year if the bonfires are as well-kept as you claim. Thank you for inspecting them for me; here, take this as a small token of my esteem." }
WordHunterWoW_QuestEN[9378] = { title = "DND FLAG The Dread Citadel - Naxxramas", description = "In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now.\n\nWe have devised a way to gain entry via a permanent arcane cloaking of sorts - an old cantrip of the Kirin Tor with a few modifications of my own. With that said, the cloaking is costly; however, your dedication to the cause of the Dawn is unwavering! We will waive all cost associations.", objectives = "Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will grant you Arcane Cloaking at no cost. You must be Exalted with the Argent Dawn.", descriptionSource = "retail" }
WordHunterWoW_QuestEN[9386] = { title = "A Light in Dark Places", description = "An eager one, aren't you? If you're willing to enter the depths once more, I'll gladly reward you.\n\nSeek out the bonfires burning within Stratholme, Scholomance, Dire Maul, and the halls of Blackrock Spire itself; I look forward to your return, {name}.", objectives = "Find and touch the bonfires located within Blackrock Spire, Dire Maul, Scholomance, and Stratholme, then speak with the Festival Flamekeeper.", completion = "You have proven that you are not entirely useless, mortal." }
WordHunterWoW_QuestEN[9388] = { title = "Flickering Flames in Kalimdor", description = "There are many flames burning throughout the world today, {name}. The trickiest fires to tend are those that burn green; they do not stay lit long without supervision. Make certain the emerald fires still burn on Kalimdor for our Flamekeeper, eh?\n\nYou will find them near Ratchet in the Barrens, close to the Master's Glaive in Darkshore, in the forest of Ashenvale by the bridge near Silverwing Outpost, and near the road to Windshear Crag along the main road in Stonetalon Mountains.", objectives = "Visit the bonfires within Ashenvale, the Barrens, Darkshore, and Stonetalon Mountains, then speak with the Festival Flamekeeper.", progress = "The fires cannot die until the festival is done!", completion = "Ahhh, so they do still burn. I am glad; it would not do for those fires to burn out before their time. You have done well, {name}. Take this with my blessing." }
WordHunterWoW_QuestEN[9389] = { title = "Flickering Flames in the Eastern Kingdoms", description = "The Midsummer Fire Festival traditionally lights up the land with a myriad of flames. Some argue that the green fires are the finest, as they are the hardest to maintain and have such a distinctive hue.\n\nMake sure they still burn in the Eastern Kingdoms for our Flamekeeper. They sit near Dun Modr in the Wetlands, close to Pyrewood Village within Silverpine Forest, on the cliffs overlooking the lighthouse in Westfall, and by the ruined tower in Hillsbrad Foothills.", objectives = "Visit the bonfires within Hillsbrad Foothills, Silverpine Forest, Westfall, and the Wetlands, then speak with the Festival Flamekeeper.", progress = "Have you seen to your task?", completion = "So you've returned, and you've seen to the emerald flames of the continent. What do you think, mm? A rare and wonderful sight, to be certain. I am aware, however, that tangible rewards are better appreciated... so please, take this for your trouble." }
WordHunterWoW_QuestEN[9415] = { title = "Report to Marshal Bluewall", description = "Are you Marshal Bluewall's new recruits? Of course you are.\n\nWhat are you waiting for? Good soldiers are dying in the desert. Aren't you excited to join them?\n\nNow, get going and don't dry out on the way.", objectives = "Speak with Marshal Bluewall at the Alliance encampment near Hive'Zora.", completion = "The Alliance needs every able body they can get. The Horde has been receiving a steady supply of reinforcements from the northern part of the continent, and it's been a struggle to keep up.\n\nLet me explain the situation to you." }
WordHunterWoW_QuestEN[9416] = { title = "Report to General Kirika", description = "You must be one of General Kirika's new recruits. It's about time you showed up. Bodies wear down quick in the desert.\n\nThe dwarves have been getting reinforcements daily, and we can't afford to lose ground in our struggle for resources in Silithus.\n\nGet your instructions from the General. It's not my job to train you, just find you.", objectives = "Speak with General Kirika at the Horde encampment near Hive'Regal.", completion = "It's good that you're hear, but there's no time to waste making small talk. You need instructions, and then you need to get out there.\n\nListen up." }
WordHunterWoW_QuestEN[9419] = { title = "Scouring the Desert", description = "We recently found out that the Horde has been scavenging the Silithus desert for resources, but paid them little mind. We thought it could not be worth it to station large numbers in this sweltering desert.\n\nHowever, it was discovered the importance of the resources, and now we are scrambling to catch up.\n\nIf I have your assistance, you must go into the desert and recover the silithyst and return it here.", objectives = "Find and deliver Silithyst to the Silithyst Extractor, then speak with Marshal Bluewall at the Alliance encampment near Hive'Zora.", progress = "Be careful out there, but also be quick. We have no time to lose.", completion = "Thank the Light you were successful.\n\nNow if we could only have started this sooner, our need would not be so desperate. We must keep the bounty of the desert from falling into the hands of the Horde." }
WordHunterWoW_QuestEN[9422] = { title = "Scouring the Desert", description = "For some time now, we have been tapping the crystal resources of the Silithus desert. The only dangers we faced were from the creatures that made this place their home and the oppressive sand and dust and heat.\n\nBut now the Alliance seems to have caught on to what we have found here. It is now a race between us to capture the natural resources, and keep them from the other.\n\nI need every set of hands that is available. I hope I have yours.", objectives = "Find and deliver Silithyst to the Silithyst Extractor then speak with General Kirika at the Horde encampment near Hive'Regal.", progress = "Be wary of the dangers of the desert, {name}. With the Alliance lurking in the dunes, any step could be your last.", completion = "You've done well, {name}. These resources will be added to our stockpiles, and every bit is to our gain and our enemy's loss." }
WordHunterWoW_QuestEN[9556] = { title = "To The Victor...", description = "You've no doubt been fighting long and hard among the towers, {race}. We would like to give something back to you in return for your defense of these lands, but first, you must prove to us you understand the weight of the tragedies that took place here.\n\nWalk the streets of Stratholme and find a vial of the holy water. Once you have it, travel to the mage quarter of Stormwind or the Undercity... There, if you are victorious within these lands, you will find my colleague.", objectives = "Collect a bottle of Stratholme Holy Water from within the city of Stratholme and deliver it to the Lordaeron Mage within the Mage Quarter of Stormwind or the Undercity when your side is victorious in the Eastern Plaguelands." }
WordHunterWoW_QuestEN[9664] = { title = "Establishing New Outposts", description = "Welcome to the Plaguelands, {name}. As you know, the Forsaken and their allies hold the lands to the west of here against our best efforts. The Alliance commanders have decided that here in the east, we will establish new fortifications to tighten the noose around our enemies.\n\nTowers long abandoned since the days of Lordaeron are to be seized and rebuilt for this purpose. These lands are dangerous, and we could use your help.", objectives = "Capture Crown Guard Tower, Eastwall Tower, Northpass Tower and Plaguewood Tower in the Eastern Plaguelands, then return to Emmisary Whitebeard at Light's Hope Chapel.", completion = "Very good, {name}. It will be important for us to hold these towers against future attacks, and for that we may need your assistance until reinforcements can be brought in to secure the area." }
WordHunterWoW_QuestEN[9665] = { title = "Bolstering Our Defenses", description = "Agents of the Forsaken uncovered an Alliance plot to establish new bases here in the Eastern Plaguelands, at abandoned towers throughout the area.\n\nIt is imperative that we not allow them to establish a significant presence on our eastern borders, and so we must stave off this Alliance incursion. Our current plans are to drive them out of any towers they may have already seized, and occupy those that we have under our control against further attacks.", objectives = "Capture Crown Guard Tower, Eastwall Tower, Northpass Tower and Plaguewood Tower in the Eastern Plaguelands, then return to Emmisary Gormok at Light's Hope Chapel.", completion = "This is good news, {name}. It will be a constant struggle here in the Plaguelands until we have fully driven back the forces of the Alliance.\n\nUntil that day, I hope that we will have your continued assistance." }
WordHunterWoW_QuestEN[65593] = { title = "Hearts of the Lovers", description = "An incubus will be drawn to the hearts of lovers, and the most aching love will create the most irresistible lure.\n\nMy scrying has revealed two that should serve exceptionally.\n\nIn Silverpine Forest, Avelina Lilly provides her tailoring services to the fallen wizards at Ambermill. In the Barrens, Isaac Pearson hopes to make his mark in the seaside town of Ratchet.\n\nThey toil on opposite ends of the world, yet their hearts yearn only for each other. Bring those hearts to Carendin.", objectives = "Bring the hearts of Avelina Lilly and Isaac Pearson to Carendin Halgar in the Temple of the Damned.", progress = "Ah, {name}, you return. Were you able to procure the lovers' hearts?", completion = "As expected. Excellently done, {name}.\n\n\n\nIdiots." }
WordHunterWoW_QuestEN[65597] = { title = "The Binding", description = "The time has come at last. Bring the hearts to the summoning circle below. Place them at its center and call forth the incubus.\n\nThe demon will not be pleased when it realizes that you have tempted it into a trap. Do not fall prey to its beguilement, {name}. You must subdue it fully.\n\nOnly then can I teach you the spell to bind it to your will.", objectives = "Using the Lovers' Hearts, summon and subdue an incubus, then return the Lovers' Hearts to Carendin Halgar in the Magic Quarter of the Undercity.", progress = "The incubus possesses martial prowess, but its illusory charms are its most potent weapon. Falter for even a moment, and the demon will seize upon the opportunity to enthrall you.\n\nDo not let it, {name}.", completion = "Impressive. Very impressive. The sayaad specialize in preying upon mortals. Many a {class} has thought themselves strong enough to command one, only to find themselves being commanded instead.\n\nThis trial did not break you, {name}, and your efforts have earned your reward. I will teach you the spell to summon the incubus." }
WordHunterWoW_QuestEN[65601] = { title = "Love Hurts", description = "A sayaad male is known as an incubus. A creature of profound evil and singular mind.\n\nThe demon must be lured into our world with an item of enticement - an object that represents great love and devotion.\n\nIf you trust a blind man to lead you, {name}, then listen. East from the Cleft of Shadow, along the main drag of Orgrimmar, lives Magar. He longs for the return of his mate, Krilge.\n\nSeek him out. He'll ask you to search for something precious. That is the key which you must bring to Gan'rul.", objectives = "Speak with Magar in Orgrimmar.", completion = "Who told you about Krilge? Have you come with any news? You better not be toying with me..." }
WordHunterWoW_QuestEN[65602] = { title = "What Is Love?", description = "You will need a powerful reagent to tempt an incubus -- an object that represents great devotion and love.\n\nWith my scrying, I have located a small figurine that should be suitable for your ritual.\n\nThousands of years ago, the figurine belonged to a young couple. The original owners are no more, but their keepsake has survived to the present day.\n\nFollow the road north into Ashenvale, then west and past Maestra's Post. You will see a house nestled amongst the trees. There you will find what you seek.", objectives = "Retrieve the Wooden Figurine and bring it to Gakin the Darkbinder in the Mage Quarter of Stormwind.", progress = "You've returned. Successfully, I assume?", completion = "<Gakin turns the wooden figurine over in his hand.>\n\nI sense the emotional energy residing within this artifact, undiminished by the passing of time. The incubus will be drawn to it like a fly to honey.\n\nTakar never disappoints." }
WordHunterWoW_QuestEN[65603] = { title = "The Binding", description = "The time has come. Take the figurine and descend into the crypts below. A summoning circle has been prepared, and you must place the figurine at its center.\n\nThen the gateway will open, and the incubus will cross into our world.\n\nA sayaad is not to be underestimated. The demon will not hesitate to attack when it realizes your ruse. You must draw upon all you have been taught to defeat it.\n\nIf you succeed, return to me and I shall bind the creature to your will. Fail, and your soul is forfeit.", objectives = "Using the Wooden Figurine, summon and subdue an incubus, then return the Wooden Figurine to Gakin the Darkbinder in the Slaughtered Lamb.", progress = "The incubus will try to lower your guard through beguilement and deception. The demon is adept at swaying the hearts of mortals.\n\nRemember that anything it may offer you is false. To the demon, you are merely prey.", completion = "Not bad, {name}. Your have bested the fiend, and your will remains unbroken.\n\nMany a {class} has believed themselves strong enough to bind a sayaad, only to become the demon's next meal instead. I am pleased to see you are not so foolish.\n\nWatch closely, and I will teach you the invocation to call upon your newly bound incubus." }
WordHunterWoW_QuestEN[65604] = { title = "The Binding", description = "Yes... I see. I feel the residual emotions bound within these threads. Love is woven into its stitches. The incubus will not be able to resist.\n\nTake this to the summoning circle in Neeru's tent, {name}. Summon forth a malevolent incubus, then show it your mastery. Do not expect it to be subdued quietly. Ready your magic and prepare yourself for a fight. Underestimating a demon has been many a warlock's final mistake.\n\nWhen you have defeated it, return the cloth to me. I will let Magar know what you found.", objectives = "Using the Withered Scarf, summon and subdue an incubus, then return the Withered Scarf to Gan'rul Bloodeye in Orgrimmar.", progress = "The sayaad are dominators of minds and torturers of souls. Their visage brings the heart joy, leaving you defenseless when they rend your flesh with whip and claw.\n\nDo not entertain the incubus' charms, {name}. Slay it quickly and let it be done.", completion = "Hah! Victorious, as expected!\n\nThe incubus is subdued, and it will be my pleasure to teach you to summon the demon. You strength is growing, and I have no doubt that this is a mere stepping stone to even greater powers.\n\nI will return the scarf to Magar. I have known that orc for many years, and never did I think he would care for someone the way he cared for Krilge.\n\nIt is a reminder of what separates us from the demons. We wield their darkness, but they will never wield us." }
WordHunterWoW_QuestEN[65610] = { title = "Wish You Were Here", description = "I met Krilge while making Mooncloth in Ashenvale. He was stationed there to protect civilians from danger, until he disappeared...\n\nThey've stopped looking for him and consider him a deserter, but I don't believe it.\n\nWe would often meet at Fallen Sky Lake before it became overrun by those aggressive bog beasts.\n\nI'm not typically one to ask favors, but if you could go to Ashenvale and look for any sign of him, I'd appreciate it.", objectives = "Investigate Fallen Sky Lake in Ashenvale and report your findings to Gan'rul Bloodeye in Orgrimmar.", progress = "Yes, what is it?", completion = "What is it you have there, {name}? A scarf made of... Mooncloth? You best not be seeking to romance me." }
WordHunterWoW_QuestEN[76156] = { title = "Stalk With The Earthmother", description = "I sense in you a hidden talent for the subtle arts, {class}. Use this mask to infiltrate the nearby Venture Company mine and steal their supplies. It may not seem like a convincing disguise, but a skilled rogue can slip past any guard with naught but a winning smile and a cunning distraction. I believe this capability lies within you as well.", objectives = "Sneak into the Venture Company mine southeast of Thunder Bluff and collect 5 Seaforium Mining Charges from carts of blasting supplies, then return them to Boarton Shadetotem in Thunder Bluff.", progress = "We'll need to work on your stealth skills, {class}.  I heard you approaching as soon as you set foot on the mesa.", completion = "Hmm... perhaps disguises are not your strength." }
WordHunterWoW_QuestEN[76160] = { title = "Stalk With The Earthmother", description = "Maybe your skills lie with poisons, not disguises. The Harpies to the north nest in a tree which produces a resin of potent toxicity. Gather the fallen cones around the nests, then crush them into a salve. When applied to a blade this salve will sear your opponent's wounds into their flesh and turn their blood to salt.", objectives = "Gather 8 Windfury Cones north of Thunder Bluff, use them with the Mortar and Pestle, then return to Boarton Shadetotem in Thunder Bluff with the result.", progress = "Be careful with the salve once you are finished, {class}.  Even skin contact could be quite painful.", completion = "{class}, this is not the venomous salve I asked for.  What you have brought me is pine nut butter.  Are you sure you followed my instructions?\n\nThis will be of far more use spread on some spice bread than on a dagger.  Although you would be quite formidable against a foe with a nut allergy." }
WordHunterWoW_QuestEN[76240] = { title = "Stalk With The Earthmother", description = "I have one last idea that may lead us to success. I still feel there is hidden talent in you, but let us try and coax it out with a less direct approach.\n\nGo and procure a Raw Brilliant Smallfish, then bring it back here. Use these daggers to clean and fillet it. Do not think too hard - do what comes naturally.", objectives = "Buy or catch a Raw Brilliant Smallfish, then use the Knife Set to fillet it in front of Boarton Shadetotem in Thunder Bluff.", progress = "Do you have something for me?", completion = "That was quite a display, {class}.  Not the rogueish precision I hoped for, but you possess an impressive ambidexterity.\n\nI see now that you will not be the one to train my people in the subtle arts, but there is one thing I can teach you.  Good luck on your travels, {class}.  The Horde will need heroes like you." }
WordHunterWoW_QuestEN[78088] = { title = "A Strange Artifact", description = "<The mysterious orb you hold fills you with cold dread. You can almost hear a voice echo faintly in your mind. Low and guttural, you understand well that the language being spoken is demonic in nature. \n\nEven as a paladin, this magic is beyond you. Find a more senior paladin here in Kalimdor who might be able to help you discern the nature of this sinister object.>", objectives = "Bring the Althalaxx Orb to Delgren the Purifier at Maestra's Post in Ashenvale.", progress = "Did you find something in the tower?", completion = "You were right to bring this to me, {name}." }
WordHunterWoW_QuestEN[78089] = { title = "Advice From Stormwind", description = "There's a powerful darkness about this orb. Its nature is clearly demonic, but past that it is beyond my ability to discern its purpose.\n\nTake the orb to the one known as Katherine the Pure in the Stormwind Cathedral. Consult with her for advice on the orb.", objectives = "Bring the Althalaxx Orb to Katherine the Pure in Stormwind.", progress = "You bring news from Kalimdor?", completion = "<Examines the orb with a worried expression>" }
WordHunterWoW_QuestEN[78090] = { title = "A Second Opinion", description = "I'm not sure what to make of this orb, {name}. I think we will need the help of... a specialist.\n\nWe are aware of a warlock sect operating out of Stormwind. Officially we reject the presence of warlocks in the city. Unofficially, their knowledge can be of use when dealing with demonic forces.\n\nFind a representative of these warlocks, and seek their opinion on the orb.", objectives = "Find the warlock sanctum within Stormwind and seek advice on the orb.", progress = "You're a long way from the cathedral, {class}. I hope you realize you have no authority here.", completion = "So the Silver Hand requires my aid? It will not come cheaply." }
WordHunterWoW_QuestEN[78091] = { title = "Earning Your Salt", description = "I will study the orb and tell you what I learn, but you must first do something for me.\n\nThe warlocks of the Blackrock clan use specially prepared salts to enhance their summoning rituals. Collect some from the orcs in Redridge.\n\nWhen you return, I will share with you the results of my studies.", objectives = "Collect 14 Summoner's Salt from Blackrock Summoners in Redridge Mountains, then return to Ursula Deline in Stormwind.", progress = "<The warlock is studying the orb intently>", completion = "Ah... the salts. I had forgotten all about them.\n\nThis orb is unlike anything I have seen, {name}." }
WordHunterWoW_QuestEN[78092] = { title = "It Must Be Destroyed", description = "The tendrils of sentience reaching out from this orb are too much for even an experienced warlock like myself to withstand for long. I am reluctant to admit this, {name}, but the orb must be destroyed.\n\nThe orb is nearly impervious, but it may be vulnerable to the weapon of a powerful demon lord. I have heard that such a blade is present in Ashenvale--at the site where the pit lord Mannoroth was destroyed.\n\nGather motes of the fallen demon's essence there, then shatter the orb upon the blade.", objectives = "Gather 12 Motes of Mannoroth from demons in Ashenvale. Bring them along with the Orb of Althalaxx to the Spear of Mannoroth at Demon Fall Canyon.", progress = "<Your hair stands on end as infernal energies surround you>", completion = "<You raise the orb towards the spear>" }
WordHunterWoW_QuestEN[78093] = { title = "Return to Delgren", description = "<The shattered remains of the orb lay at your feet. Delgren will want to see you have succeeded.>", objectives = "Return the Orb Shards to Delgren.", progress = "Did you find a way to destroy the orb?", completion = "This is a relief, {name}. But whatever was watching Azeroth through that orb... I have a feeling they will not be happy it was destroyed.\n\nTake this as my thanks for your efforts. And... be careful." }
WordHunterWoW_QuestEN[78124] = { title = "Nar'thalas Almanac", description = "", objectives = "Have you brought something to add to our collection?", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
WordHunterWoW_QuestEN[78127] = { title = "The Dalaran Digest", description = "", objectives = "Have you brought something to add to our collection?", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
WordHunterWoW_QuestEN[78132] = { title = "Dragonslayer's Helm", description = "", objectives = "The helm of the Dragonslayer once belonged to a great commander who fell in battle. It is said his tormented soul still haunts the site of his passing.", progress = "The helm of the Dragonslayer once belonged to a great commander who fell in battle. It is said his tormented soul still haunts the site of his passing.", completion = "Splendid job, {name}! With this, I am one step further on my path to glory." }
WordHunterWoW_QuestEN[78133] = { title = "Dragonslayer's Shield", description = "", objectives = "The shield of the Dragonslayer is rumored to be held by an Orcish warlord. He stole it while raiding a human settlement.", progress = "The shield of the Dragonslayer is rumored to be held by an Orcish warlord. He stole it while raiding a human settlement.", completion = "Splendid job, {name}! With this, I am one step further on my path to glory." }
WordHunterWoW_QuestEN[78134] = { title = "Dragonslayer's Lance", description = "", objectives = "The lance of the Dragonslayer has changed hands many times. Every now and then, rumor spreads of it appearing in black market arms deals. Perhaps the lance's current unsavory proprietor would be willing to part with it; for a price.", progress = "The lance of the Dragonslayer has changed hands many times. Every now and then, rumor spreads of it appearing in black market arms deals. Perhaps the lance's current unsavory proprietor would be willing to part with it; for a price.", completion = "Splendid job, {name}! With this, I am one step further on my path to glory." }
