WordHunterWoW_QuestEN[79974] = { title = "Wet Job", description = "\"Always like to keep a reserve stash nearby in the off chance I've got to flee in a hurry.\n\nThe face of this mountainside is so beautiful you might say it was carved from the waterfalls of time. \nThat's the eagles nest, that's what you're looking for.\"", objectives = "Dusting off a messenger bag emerging from the soil, you find a parchment nestled among the supplies.", completion = "Dwarven Engineering, always a marvel." }
WordHunterWoW_QuestEN[79975] = { title = "Eagle's Fist", description = "<You find a carefully folded letter inside of the toolbox.>\n\n\"From here, with the right tools, you call the shots. Great place to launch a parachute glider.\n\nMy loyalty to the Eagle and Fist requires distance in order to serve them best. This barricade has had better days, like the Old Kingdoms it once defended, but I'll never abandon it.\"", objectives = "Water spray dampens the air, the view is incredible.", completion = "A campfire is newly fed with wood, but signs of a quick departure are evident." }
WordHunterWoW_QuestEN[79976] = { title = "This Must Be The Place", description = "\"So, I've decided to take my work back underground. To stop it falling into the wrong hands.\"\n\n<The paper is torn just large enough to fit the message. You aren't sure if these are the last words you'll read from the author, or if they're a clue to the next hideout. An inadequately secured sleeping bag is unrolling itself onto your feet...>", objectives = "Whoever was here, you just missed them.", completion = "Heavy canvas is rolled over assorted equipment. You help yourself to the pack." }
WordHunterWoW_QuestEN[79980] = { title = "Scramble", description = "\"Not so bad, eh? Since you're reading this, it means my stash is still there. Take a hundred paces due north and don't break your ankles going down the steep cliffside. There should be enough to keep you going.\"", objectives = "Find what awaits you.", completion = "You pull a messenger bag out of the ground. Stuffed in with the supplies is a dirty parchment." }
WordHunterWoW_QuestEN[80001] = { title = "Rekindle", description = "", objectives = "An extinguished fire pit. The wood is even dry enough to catch a flame.", progress = "An extinguished fire pit. The wood is even dry enough to catch a flame.", completion = "You put your scout skills to work." }
WordHunterWoW_QuestEN[81730] = { title = "Duskwood Mission I: Defeat Worgen", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion in the Rotting Orchard. Defeat worgen there and return to me.", objectives = "Defeat 10 Nightmare Runners and 10 Nightmare Weavers in the Duskwood Nightmare Incursion in the Rotting Orchard and return to Field Captain Palandar.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?" }
WordHunterWoW_QuestEN[81731] = { title = "Duskwood Mission II: Defeat Ogres", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Vul'gol Ogre Mound. Defeat ogres there and return to me.", objectives = "Defeat 3 Deranged Ogres and 3 Demented Fire Weavers in the Duskwood Nightmare Incursion at the Vul'gol Ogre Mound and return to Field Captain Palandar.", progress = "You've dealt with the ogres?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?" }
