WordHunterWoW_QuestEN[81733] = { title = "Duskwood Mission IV: Ogre Intelligence", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Vul'gol Ogre Mound. Retrieve an intelligence report from Dreamwarden Thalinar there and return to me.", objectives = "Gather intelligence from Dreamwarden Thalinar in the Duskwood Nightmare Incursion deep inside the Vul'gol Ogre Mound and return to Field Captain Palandar.", progress = "You have the report?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?" }
