WordHunterWoW_QuestEN[81735] = { title = "Duskwood Mission VI: Dragon Intelligence", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Yorgen Farmstead . Retrieve an intelligence report from Dreamwarden Amalia there and return to me.", objectives = "Gather intelligence from Dreamwarden Amalia in the Duskwood Nightmare Incursion in the farmhouse at the Yorgen Farmstead and return to Field Captain Palandar.", progress = "You have the report?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?" }
WordHunterWoW_QuestEN[81736] = { title = "Duskwood Mission VII: Recover Shadowscythe", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Rotting Orchard. Retrieve a powerful artifact known as the Shadowscythe and deliver it to me.", objectives = "Recover the Shadowscythe in the Duskwood Nightmare Incursion upstairs in the farmhouse at the Rotting Orchard and return to Field Captain Palandar.", progress = "You have the Shadowscythe?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?" }
WordHunterWoW_QuestEN[81737] = { title = "Duskwood Mission VIII: Recover Ogre Magi text", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Vul'gol Ogre Mound. Retrieve an Ogre Magi Text and deliver it to me.", objectives = "Recover an Ogre Magi Text in the Duskwood Nightmare Incursion within the Vul'gol Ogre Mound and return to Field Captain Palandar.", progress = "You have the text?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?" }
