WordHunterWoW_QuestEN[81739] = { title = "Duskwood Mission X: Nightmare Moss", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove and collect Nightmare Moss from within the Nightmare Incursions. We can harness its magic to reverse the damage. You will need the assistance of an herbalist.", objectives = "Gather 10 Nightmare Moss in the Duskwood Nightmare Incursions and return to Field Captain Palandar.", progress = "You have the Nightmare Moss?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?" }
