WordHunterWoW_QuestEN[81745] = { title = "Duskwood Mission XVI: Rescue Kroll Mountainshade", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Rotting Orchard. Find the sleeping Druid of the Claw Kroll Mountainshade there and escort him to safety. Then return to me.", objectives = "Rescue Kroll Mountainshade from the Duskwood Nightmare Incursion in the guest house at the Rotting Orchard and return to Field Captain Palandar.", progress = "You rescued Kroll?", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?" }
WordHunterWoW_QuestEN[81746] = { title = "Duskwood Mission XVII: Rescue Alara Grovemender", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Yorgen Darmstead. Find the sleeping Druid of the Claw Alara Grovemender there and escort her to safety. Then return to me.", objectives = "Rescue Alara Grovemender in the Duskwood Nightmare Incursion in the stable at the Yorgen Farmstead and return to Field Captain Palandar.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?" }
WordHunterWoW_QuestEN[81747] = { title = "Duskwood Mission XVIII: Rescue Elenora Marshwalker", description = "While these demons distract us here, the Emerald Dream is being corrupted into nightmare. Quick, travel through the Emerald Dream Portal in the Twilight Grove, and journey to the Nightmare Incursion at the Vul'gol Ogre Mound. Find the sleeping Druid of the Claw Elenora Marshwalker there and escort her to safety. Then return to me.", objectives = "Rescue Elenora Marshwalker in the Duskwood Nightmare Incursion in the ruins of a farmhouse near the Vul'gol Ogre Mound and return to Field Captain Palandar.", completion = "Well done! Your services shall be well rewarded. Perhaps another mission?" }
