WordHunterWoW_QuestEN[84402] = { title = "Necromancy 101", description = "", objectives = "Have you brought something to add to our collection?", progress = "Have you brought something to add to our collection?", completion = "Thank you, {name}. Our knowledge expands through your efforts.\n\nIf you discover more magical works that might benefit the library, please bring them to me." }
WordHunterWoW_QuestEN[86574] = { title = "Stonetalon Supply Run", description = "<The unfortunate body here bears the marks of many strikes from the Pridewing wyverns. The pack nearby is rumpled and discarded, with its contents missing, and only a small note clutched in the courier's hand to indicate what was lost: a shipment meant for Innkeeper Faralia at Stonetalon Peak.>\n\n<The wyverns have probably carried off the supply bundles to line their nests.>", objectives = "Collect 6 Stonetalon Supplies from Pridewing Wyverns and deliver them to Innkeeper Faralia.", progress = "I hope that shipment comes soon...", completion = "You found the missing shipment?\n\nOh, I had no idea that the courier didn't make it. That is... a tragic state of affairs...\n\nI'll put these supplies to good use to make sure that her loss is not in vain." }
WordHunterWoW_QuestEN[86576] = { title = "Bloodfury Trinkets", description = "In addition to spreading their filth across the Charred Vale, the Bloodfury harpies gather anything shiny that they can find. I'm told that they collect a variety of golden-yellow sunstones for decoration. I have no use for such trinkets, but Mor'rogal has mentioned using them before.\n\nWhile you're fighting the harpies of the Vale, keep your eye out for Glittering Sunstones. Bring any that you find to Mor'rogal, up on the hills above us.", objectives = "Bring 15 Glittering Sunstones to Mor'rogal.", completion = "Ah, you have brought sunstones that the harpies collect! The harpies love to gather objects that are shiny, but they do not know the true value of the stones. By capturing the dazzling light of the sun, these stones reflect its majesty and allow us to adorn our shrines and homes with tiny motes of light in its honor. The moon, too, illuminates them with its silver beauty at night.\n\nThese stones remind us of the connection we have to the lights of the skies." }
WordHunterWoW_QuestEN[86585] = { title = "Banner of the Fallen", description = "The fallen mountaineer bears a standard of Ironforge. Perhaps she was scouting, or making a doomed charge. Either way, the standard has been cast down and trampled. The mountaineer was hit on the head so hard that her helm was knocked off and she was killed outright by a trogg, likely with a spiked club.\n\nThe trogg that killed her is probably still nearby, and likely remembers the banner. Raising the banner of Ironforge once more may call it out.", objectives = "Raise the standard of Ironforge, call out the trogg Headsplitter and kill it, then report to Captain Rugelfuss.", progress = "That banner looks like it's been in a war!", completion = "You found Ylva's body? Ah, the poor woman. She said she was going to show the troggs that Ironforge would never fall to their kind. She went looking for a few mountaineers who never returned from a patrol through trogg country. She was always too independent-minded to be cautious. Now we know what happened.\n\nI'll take the banner back and make sure it's cleaned up and displayed. You should take her weapon. May it serve you well against the troggs." }
WordHunterWoW_QuestEN[86613] = { title = "Excavation Tools", description = "The excavation's tools, left behind when the dwarves fled from the troggs, seem mostly untouched. Returning them to the excavators will surely aid their work.", objectives = "Return 6 Excavation Tools to Magmar Fellhew.", progress = "We just, uh, need to adjust our dig site and we can get this whole thing back on track!", completion = "Our tools!\n\nWhen the troggs overran the camp, we had to leave most of our tools behind. This'll be a big help once we get this invasion under control and can start working again!" }
WordHunterWoW_QuestEN[86614] = { title = "Silver of the Waves", description = "<Among the fishing knickknacks in the debris are some rusty hooks, broken spools of wire, and a slightly corroded but ornate silver hair clip with the monogram \"K.D.\">", objectives = "Return the Monogrammed Silver Hair clip to its owner.", progress = "I have a lot of chores today, so can you keep it quick?", completion = "My hair clip! I thought this was lost for good!\n\nThis'll shine right up with just a little work. Thank you for bringing it to me! I'll make it worth your while." }
WordHunterWoW_QuestEN[86667] = { title = "Snowbound", description = "My old mentor, Norric, sent a minor elemental with an odd request. He needs a jar of snow for some of his shamanic workings! I don't know what he's going to do with that, but I learned a long time ago not to question his ways with respect to magic.\n\nI'm busy learning about the local elementals, so I can't leave to help him. Go to the tunnel entrance at South Gate Pass where there's snow year-round. Scoop some up in this ceramic jar and bring it to him before it melts. The jar should keep it cold.", objectives = "Deliver a Jar of Snow to Norric Lochthane at his house on the northwest coast of the Loch.", progress = "Eh? What do you want?", completion = "This jar is for me?\n\nSnow! Grenhild did it! She sent the snow that I asked for!\n\nA pity, though, I was hoping she would come and visit in person.\n\nWell, regardless, thank you for your effort. This is a real help for my work." }
WordHunterWoW_QuestEN[86757] = { title = "Slowing the Orc Advance", description = "Orcs have taken over the eastern forest, and their scouts and grunts now lurk throughout the woods! It's not safe for our kind to move about Ashenvale any more.\n\nWe need to push back the orcs and secure the forest. We've been able to pick off some of the grunts and scouts by carefully sneaking around the edges of their camp.\n\nFight the orcs and bring me the jagged swords and curved knives that they use. I'll make sure their weapons are salvaged and repurposed, so nothing goes to waste.", objectives = "Bring 6 Jagged Orc Swords and 4 Curved Orc Daggers to Shandrina.", completion = "Excellent work, {name}.\n\nI deplore the situation that requires us to resort to this kind of violence, but if the orcs aren't stopped, they'll invade Astranaar and cut down the whole wood. At least we can reuse the metal of their crude weapons to make defenses of our own." }
WordHunterWoW_QuestEN[86758] = { title = "Twisting the Knife", description = "Did I ever tell you how I almost lost me hand to a crocolisk? Managed to jam me knife into its jaw, and scrambled out real quick. I thought I had the knife around here somewhere, but I can't seem to find it.\n\nAnyway, that croc is probably still out there hunting along the edge of the lake. That nasty brute probably needs to go, for the safety of the other hunters, if nothing else.\n\nI've taken to calling it Daggerfang. If you see it, give it a friendly hello from me! And by \"hello\" I mean \"stab.\"", objectives = "Find and defeat the crocolisk Daggerfang and bring back Marek's knife.", progress = "How goes the huntin'?", completion = "Hah! You did it! I never thought that ol' croc would get its comeuppance, but that does the trick!\n\nOh ah... y'know, I had to get me another knife, but maybe that one will bring you some good luck. Why don't you hang onto it?" }
WordHunterWoW_QuestEN[86776] = { title = "Ingredients for the Forge", description = "Thelsamar's a great place to live, but we don't have all of the amenities of Ironforge. I'm always running out of bronze! I need more bronze if I'm going to keep making tools and kettles and pots!\n\nI can tell you have a little experience at the forge. Think you could smelt me some bronze bars? I can pay you well for it!", objectives = "Bring 10 Bronze Bars to Morhan Coppertongue.", progress = "Gotta keep the forges going!", completion = "Ah, this is a relief! I should be able to keep the forge going now. Hopefully one of these days we'll get a trader bringing coal into town regularly!" }
WordHunterWoW_QuestEN[86784] = { title = "Sticks and Bones", description = "My associate Eleanor Shackleton prides herself on traveling the wilds, surviving against weather and monsters. She is currently camped not far from here, in the hills to the west, and I remember a piece of advice that she once gave me: \"When you think you have enough firewood, gather five times more.\"\n\nIf you have some spare time, you could collect some wood in this basket and take it to her camp. I'm sure she could give you a few tips about the existence of a traveling adventurer.", objectives = "Collect 6 Dry Branches and bring them to Eleanor Shackleton.", progress = "Welcome to my fire, traveler.", completion = "Extra firewood? That is always welcome. It will keep these old bones warm through the cold nights of the Glades.\n\nI have a sling for collecting wood myself, so you might as well hang onto that basket." }
WordHunterWoW_QuestEN[87288] = { title = "Soft Saber Pelts", description = "Hello, traveler! I hope you are enjoying your visit to our village. I like Dolanaar because it is small and rustic and everyone is friendly.\n\nI'm a local trader, and I bring in all sorts of tools and trinkets that might be useful to you in your travels. Indeed, if you are interested in a trade, I find myself in need of some nightsaber pelts. While these majestic creatures are beautiful, the local ones are rather aggressive, so don't feel too bad about defending yourself.", objectives = "Bring 6 Soft Nightsaber Pelts to Aldria.", progress = "It is good to see you again! Are you here to trade?", completion = "Oh, these are wonderful. It is a shame to resort to violence with such majestic animals, but it is important to keep the roads safe, and these pelts will make beautiful blankets and shawls.\n\nHere, let me give you something to remember them. It is both soft and sturdy." }
WordHunterWoW_QuestEN[87318] = { title = "Hearts of the Lost", description = "Thandol Span has been a dangerous place since the Dark Irons blew up the bridge, but I didn't expect to run into them there!\n\nI managed to escape, but I lost sight of my partner, Essene. I've been searching all over for her, but I haven't found any sign of her. Did the Dark Irons capture her? Did she fall into the river below? Did she make it back to the other side? I don't know! I don't even know if she's alive!\n\nPlease, if you see any sign of her, let me know!", objectives = "Search for Corma's partner Essene." }
WordHunterWoW_QuestEN[87491] = { title = "Spark of Freedom", description = "Sss! The foul Dark Irons have summoned me and kept me caged next to their petty fire pit!\n\nFire must run wild, run free! Release me! Must escape! Must BURN!\n\nNo Dark Iron is safe! Burn them to the ground! Burn their black powder! Burn their fortress, their fuses, their folly!\n\nLet me out and I will BURN THEM ALL!", objectives = "Escort the captive fire elemental out of Dun Modr and to its freedom." }
WordHunterWoW_QuestEN[87760] = { title = "Holy Diver", description = "I have received word back from Darnassus, {name}!\n\nFrom the animal samples, we learned that the naga dominated these sea creatures to use as unwilling mounts and beasts of burden. The ones that were too obstinate, or too old or badly injured, they drove out for sport. Monstrous!\n\nIt is our sacred duty to put a stop to this!\n\nThe naga have forces in the Ruins of Mathystra, and they must be seizing threshers from off the shore. Find their beastmistress, slay her, and bring back her tools of domination!", objectives = "Find a Stormscale Beastmistress, slay her, and bring back her Rod of Deep Dominion.", progress = "We will finally have resolution to this mystery, and the animals will have peace at last!", completion = "This has been a long journey, Orangequake, but it was worth it.\n\nAt long last, you have wrested away the rod that the naga use to compel the sea creatures into their service. I will make sure it is destroyed, and the threshers and sea turtles can finally live in peace.\n\nThank you again. Your persistence has finally been rewarded, and I, personally, am grateful to you." }
WordHunterWoW_QuestEN[88756] = { title = "Bring Back a Bang", description = "The Dark Irons have a few camps east of here on Direforge Hill, and they've stolen a bunch of explosives from our construction site and hauled 'em back to their tents.\n\nI don't need tae tell ya what kinda mischief Dark Irons can get up tae with a barrel o' powder!\n\nI know the Dark Irons are dangerous, but we need those barrels back. You can tell 'em from other barrels because of the red markings on 'em. We cannae let the Dark Irons keep 'em!", objectives = "Retrieve 3 Stolen Explosives from the Dark Iron Dwarf camps.", completion = "Ach, that's a load off me mind. At least the Dark Irons won't be able to roll a bomb-cart into our wagons... or lob 'em in a trebuchet... or roll 'em down the hill at us... or feed 'em tae slimes and then let the slimes loose near are camp and set 'em on fire.\n\nNow we just have tae make sure the powder stays dry!\n\nThanks!" }
WordHunterWoW_QuestEN[88757] = { title = "Accessories of the Lost", description = "While I was fleeing from those Dark Irons, I wound up dropping lots of my gear!\n\nIt looks like I lost... my green leather waterskin, my spellbook, my necklace, and... well I need these things!\n\nIf you can find them while I repack and catch my breath, that would be a great help.", objectives = "Bring back Essene's Necklace, Essene's Spellbook, and Essene's Waterskin." }
WordHunterWoW_QuestEN[88758] = { title = "Sentiments of the Lost", description = "I just need to finish repacking, and I can get out of here!\n\nIf you'll do me one last favor, here--take this note to Corma. It'll let her know that I'm alive and I'm on my way!", objectives = "Bring Essene's note back to Corma Villard." }
WordHunterWoW_QuestEN[90902] = { title = "Rediscovering the Light", description = "I am proud to welcome another newly risen paladin to our ranks. As you begin to reconnect with the light you may notice that certain abilities that were once second nature to you may cause you considerable pain to use now, particularly those involving channeling the light to heal yourself or others. \n\nThe only way around this problem is--unfortunately--to go through it. Like any other muscle that has atrophied, you must push through the pain and exercise the flesh for it to return to full function.", objectives = "Heal 5 Injured Deathguard with your Holy Light ability.", progress = "Mastery of the light will return, in time.", completion = "Pain is nothing new to those who have endured death, and as such the Forsaken are particularly hardy to it. Pain has a purifying property as well that you should embrace as a badge of honor and evidence that you are, in fact, still a servant of the light despite your new circumstances. \n\nBe well and walk in the light once more, {class}." }
WordHunterWoW_QuestEN[91208] = { title = "Coming to Terms", description = "Not all of our fellow Paladins who rise again are quick to acclimate to our new reality. Some struggle to reconcile that they are now, in a way, the very thing they spent their lives fighting against.\n\nThese individuals often simply need a kind gesture and a sympathetic ear. Unfortunately, many others are quick to turn violent. Find the frightened paladin who fled into the hills directly west of this chapel. Extend a hand in friendship. Lead them back into the light if you can.", objectives = "Find the Frightened Paladin in Deathknell.", completion = "Tragically, more than a few of our brothers and sisters succumb to a similar madness after being risen. As precious as every Forsaken soul is, sometimes the best we can do is grant those that cannot acclimate a clean end.\n\nI will say a prayer to the light for her. Thank you for doing what must be done, {name}." }
WordHunterWoW_QuestEN[91209] = { title = "Continue Your Training", description = "Lordaeron may not be what it used to be, but our home still needs protection from all manner of threats and it's time for you to go out and face the world. Your next stop should be the town of Brill in central Tirisfal Glades. Go and meet with Shari Stilwell there. She can see to your continued training. \n\nOne last bit of advice before you go--take extra care as a paladin traveling through Forsaken lands. There are many in the Dark Lady's service who distrust us and our proximity to the light.", objectives = "Follow the road east out of Deathknell to find the town of Brill. Report to Shari Stilwell to continue your training.", completion = "Welcome aboard, {class}. It's always encouraging to see more of our number roaming these lands. There are many here in Brill in need of assistance from adventurers such as yourself. Seek employment and grow stronger in the light. Return to me whenever you need training. \n\nWhen you've proven yourself to myself and the people of Brill, I will provide guidance for the next leg of your journey.\n\nGo with the light, {class}." }
WordHunterWoW_QuestEN[91282] = { title = "A Second Home", description = "It is encouraging to see my newly risen brothers and sisters thrive as you have. It is only through community and shared faith that we can truly realize our full potential however, and to that end we've begun to form a new paladin order right here in Tirisfal. \n\nIf you wish to learn more, you should visit our monastery at Northface Rock. It is called Bandarion Keep. It's on the bluffs just northwest of the Solliden Farmstead, and should be hard to miss.", objectives = "Find the fortress of Bandarion Keep and report to Breton Samuels there.", completion = "Another fresh recruit? Welcome to Tyr's Watch, brother." }
WordHunterWoW_QuestEN[91285] = { title = "Murlocs at the Gates", description = "Normally we'd show our newcomers a bit more hospitality, but we've got a bit of a murloc problem at the moment.\n\nA tribe of murlocs used to use the keep as their spawning grounds. They've been a problem since we moved in and kicked them out, but now it's starting to get out of hand. You look like you've seen some action. Do you think you could help us drive back some of these pests? You'll find them lurking in the bluffs along the road to the east, and in the camps around the lake to the west.", objectives = "Slay 8 Vile Fin Attackers and 8 Vile Fin Seers and report back to Breton Samuels when it is done.", completion = "We appreciate the assistance. I'm sure this won't stop the attacks entirely, but it'll hopefully slow them down a bit. It's hard enough rebuilding this place without a murloc trying to stab you in the back with a spear." }
WordHunterWoW_QuestEN[91294] = { title = "Touring the Grounds", description = "Now that the immediate threat of the murloc attacks is under control, I'd encourage you to show yourself around our stronghold. It isn't much yet, but it's home.\n\nWhen you are done exploring, seek out Danitha Morr, our leader. She can help you get settled in.\n\nI'm very glad to have met you, {name}. May the light be your guide.", objectives = "Speak to the residents of Bandarion Keep.", progress = "Welcome to Bandarion Keep, {class}. It's always good to see a new face.", completion = "Breton sent you up here, eh? Excellent.\n\nMy name is Danitha Morr, and I am the closest thing this keep has to a commander. If you come seeking fellowship amongst those that still remain loyal to the light, you've come to the right place.\n\nThere's a lot of work to do here before we can fully establish ourselves, and we'd be most appreciative if you would be willing to lend aid." }
WordHunterWoW_QuestEN[91316] = { title = "Making Repairs", description = "This far from the Undercity, logistics are challenging and we have a dire shortage of building materials needed to help restore this fortress. I'd like your help with that.\n\nThe ruined village of Shadowvale can be found in the Whispering Forest, just southwest of here. One of the buildings has an old root cellar used to store all sorts of things. There are likely to be usable materials down there. Scavenge what you can and return to us.", objectives = "Collect 12 pieces of Sturdy Lumber from Shadowvale in Tirisfal Glades.", progress = "They say location is everything. While this fortress may look imposing perched upon these bluffs, its turning out to be quite the challenge to stay supplied this far from proper civilization. An unfortunate oversight on our part.", completion = "I'm glad to see that your trip to Shadowvale bore fruit. I'll send Breton and a few of the other new recruits over later to clear the rest of the cellar out and retrieve anything left down in the dark." }
WordHunterWoW_QuestEN[91317] = { title = "The Tarnished", description = "Not all risen paladins have acclimated well to our new existence, as you may have seen yourself already. Some have carried forward their prejudices from life, and continue to visit violence upon their fellow Forsaken.\n\nAs it stands we are mistrusted by our people who remember well the persecution inflicted by the living in the name of the light, and these attacks do not help. A number of these tarnished have taken up residence at Shadowvale to the southwest. End them and bring me their leader's head.", objectives = "Slay 8 Tarnished Drudges, 6 Tarnished Zealots, and collect the head of Commander Rudolph Gelhardt in Tirisfal Glades.", progress = "The Tarnished threaten what little goodwill we have with the other Forsaken. As much as it pains me to cross blades with our former brothers and sisters, they must be stopped if our fledgling order is to survive.", completion = "Excellent work, {name}. Every time one of these Tarnished strike out and kill one of the Forsaken, it becomes that much easier for our detractors to stoke mistrust towards us paladins. Eliminating them will help further our cause and solidify our place here in Tirisfal.\n\nI suspect it may take a long time for us to be fully embraced by the Forsaken and the horde. It could take years... or maybe even decades, but the best we can do is keep trying to prove ourselves." }
WordHunterWoW_QuestEN[91723] = { title = "Delicate Instruments", description = "Blast it! Every time I try to calibrate these sensitive arcane instruments, they get thrown off again by a surge of energy.\nThe surges seem to be coming from the north, where those primitive Kobolds have been practicing their crude magic. Could you clear some of them out, so I can continue my work?", objectives = "Kill 8 Kobold Geomancers in Jasperlode Mine, then return to Hamish Bergwort in the Tower of Azora.", completion = "Well done, my friend. Let me try my calibrations again..." }
WordHunterWoW_QuestEN[91724] = { title = "Delicate Instruments", description = "Almost there, and... By the Nether! Something is still disrupting my instruments.\nThis is most frustrating, {name}. I have heard rumors that the local bandits have been practicing spells near Stone Cairn Lake. Maybe if you stop them, these disruptions will finally cease and I can get some work done?", objectives = "Kill 6 Defias Rogue Wizards at Stone Cairn Lake, then return to Hamish Bergwort in the Tower of Azora.", completion = "It seems like everything is working properly. Thank you, {name}." }
WordHunterWoW_QuestEN[91725] = { title = "Stolen Enchanting Supplies", description = "I was sent by Master Theocritus to pick up some enchanting supplies from the trading post, but on the way back I was ambushed by a pack of gnolls!\n\nI dropped the package and escaped, but if I return without it, I'll be cleaning up after the polymorph experiments for weeks as punishment! Do you think you could find the supplies for me?", objectives = "Collect 5 Stolen Enchanting Supplies from gnoll camps around Stone Cairn Lake, then return to Blixie Fitzwink near the Tower of Azora.", progress = "Did you find the supplies?", completion = "Oh, that's a relief! It looks like it's all here. Thank you!" }
WordHunterWoW_QuestEN[91732] = { title = "Good Steel", description = "Good steel is in short supply after the war, and our tools have suffered for it. The Jasperlode miners used finely-crafted picks, and I imagine some of them are still there in the depths of the mine. Could you retrieve some for me, and I'll see if I can repurpose the steel?", objectives = "Collect 4 Mining Tools from Jasperlode Mine, then return to Hagar Lowe in Eastvale Logging Camp.", progress = "Have you been to the mine yet?", completion = "Oh, very nice. Do you see that shine? Truly, they don't make them like they used to." }
WordHunterWoW_QuestEN[91733] = { title = "Downstream", description = "I was bringing back a supply shipment from the trading post, but my wagon tipped over and the supplies fell in the river! Before I could catch them, they had already washed downstream.\nBetween the murlocs and wolves down there, I don't stand a chance of retrieving the supplies on my own. You seem like the hardy sort - do you think you could find them for me?", objectives = "Collect the Waterlogged Axe, Waterlogged Saw, and Waterlogged Toolbox that have washed downstream from Eastvale Logging Camp, then return to Ormin Pelford.", progress = "Did you find the supplies?", completion = "You look a bit damp, {name}. Sorry about that. But thank you for retrieving the supplies." }
WordHunterWoW_QuestEN[91736] = { title = "Applejack Still", description = "", objectives = "A strong scent of apples burns your nose as you inspect the device.", progress = "A strong scent of apples burns your nose as you inspect the device.", completion = "The machine dispenses a clear liquid into a bottle..." }
WordHunterWoW_QuestEN[91738] = { title = "An Apple Treat", description = "", objectives = "The sergeant's eyes light up as he notices your bottle of Thunder Applejack...", progress = "The sergeant's eyes light up as he notices your bottle of Thunder Applejack...", completion = "Do my eyes deceive me? I haven't seen a drop of Thunder Applejack in months!\nThis should put a smile on the troops' faces. You have my thanks, {class}!" }
WordHunterWoW_QuestEN[91740] = { title = "Croaky's Head", description = "This murloc has no doubt been terrorizing the local roads for some time. You suspect the nearby watch guards will want to know of its demise.", objectives = "Deliver Croaky's Head to Merell Ross at Ridgepoint Tower.", progress = "Yes?", completion = "We lost two members of the watch last week to the murlocs, {class}. Hopefully with their leader slain, we can start pushing them out of Elwynn." }
WordHunterWoW_QuestEN[91741] = { title = "Nibbled-On Book", description = "<One of the kobolds dropped this book. It looks like the kobold might have tried to eat it.\n\nBrother Paxton inside the abbey has a small library he maintains. The book must have come from there.>", objectives = "Return the book to Brother Paxton.", progress = "What's that you got there? It looks like one of my books.", completion = "Hey! How did you end up with that? It's supposed to be on the shelf! Oh dear, the kobolds have been stealing my books again. They must want to eat them!\n\nThanks for bringing back the book, but what will I do about the rest of my missing collection?" }
WordHunterWoW_QuestEN[91743] = { title = "Rascally Rodents", description = "Those awful kobolds are eating my books! You have to get them back before they devour my whole library.", objectives = "Retrieve 8 Stolen Books from kobolds in Northshire Valley and return them to Brother Paxton.", progress = "Have you rescued my books yet, {name}?!", completion = "Thank you so much! Here! Take one of these how-to books. I don't need them.\n\nBut there's still so many books missing. The kobolds don't seem to be eating them. So, why do they want them?" }
WordHunterWoW_QuestEN[91745] = { title = "Mining Consultant", description = "Go talk to the new mining apprentice, Kelsey Fargo. She works right outside the mine and has probably seen what the kobolds are up to. Maybe she can teach you a thing or two about mining while you're at it.", objectives = "Talk to Kelsey Fargo outside the Echo Ridge Mine in Northshire Valley.", completion = "Kobolds with books? Yah, I've seen kobolds running back and forth with books, yelling at each other. They must be stealing them from the library inside the abbey." }
WordHunterWoW_QuestEN[91746] = { title = "Elmpaw's Head", description = "The trophy serves as an impressive reminder of your victory over Elmpaw. A local hunter or skinner might be interested to hear the story.", objectives = "Deliver Elmpaw's Head to Helene Peltskinner near Goldshire.", progress = "Yes?", completion = "So, you took down Elmpaw? Very impressive, {name}!\n\nLet me give you something in return for your trophy - I know a few collectors who will pay quite well to have this on their mantle once I've prepared it." }
WordHunterWoW_QuestEN[91751] = { title = "Rough Wolf Pelts", description = "Are you looking for an opportunity to practice skinning? My husband usually helps with hunting wolves, but he's busy up by the abbey. I could use a hand collecting more pelts to finish the orders I'm working on.", objectives = "Skin wolves around Elwynn Forest to obtain 7 Rough Wolf Pelts, then deliver them to Helene Peltskinner near Goldshire.", progress = "Any luck with those wolf pelts?", completion = "Excellent work collecting these pelts, {class}. You have a real talent for hunting." }
WordHunterWoW_QuestEN[91752] = { title = "The Big Picture", description = "Every once in a while, a kobold comes through yelling \"Picture for Narf!\" I don't know who Narf is. Maybe one of the head kobolds at the back of the mine? I bet he has a whole sack of books by now.\n\nGo get those books and bring them to our local law enforcement, Marshal McBride. You should find a friend to help. Those kobolds inside the mine are a lot meaner.", objectives = "Retrieve a Sack of \"Picture\" Books from Shinyfinder Narf. Bring the sack to Marshal McBride just inside Northshire's Abbey.", progress = "Have you retrieved those stolen books yet?", completion = "Thank you for returning these stolen books, {name}. I'll get them back to Brother Paxton at once.\n\nYou're becoming quite the hero around here. Great job!" }
WordHunterWoW_QuestEN[91753] = { title = "An Enchanting Lesson", description = "Academic rigor is of course essential to the enchanter's craft, but a practical foundation can pay dividends. Consider, as an example, the lowly Kobold. Lacking formal education, they nevertheless demonstrate a sort of innate aptitude for simple cantrips and enchantments.\n\nObtain some of their wax effigies and deconstruct the enchantments bound within them. You may find it elucidating.", objectives = "Kitta Firewind in the Tower of Azora wants you to collect 3 Luminous Residue.\n\nLuminous Residue can be obtained by disenchanting Crude Wax Effigies dropped by Kobold Geomancers.", progress = "What have your studies revealed?", completion = "Theory and practice are two sides of a coin, {name}. Remember this." }
WordHunterWoW_QuestEN[91758] = { title = "Follow That Kobold!", description = "You're not done with those kobolds yet. We just got word from Kelsey that a kobold left the mine carrying a large sack of books. I need you to track down this kobold so we can retrieve the books for Brother Paxton.\n\nGo talk to Tordrin Sternblade. He's the new Hunter trainer that just arrived from Ironforge. You can find him behind the abbey, near the stable. He can help you track this kobold thief.", objectives = "Speak to Tordrin Sternblade near the stable behind Northshire's Abbey.", completion = "I can help ye' track down this varmint. Let me whip somethin' up for ye'." }
WordHunterWoW_QuestEN[91772] = { title = "Shhh! We're Hunting Kobolds", description = "Alright. Take this kobold tracking kit. It'll let ye' track the kobold that Marshal McBride is concerned with.\n\nFollow the tracks and bring what ye' find to Marshal Dughan in Goldshire.\n\nI have a feelin' these varmints are up to somethin' outside Northshire. So ye'll be needin' Dughan's help.", objectives = "Follow the kobold tracks and report to Marshal Dughan in Goldshire with your findings and the Kobold Tracking Kit.", progress = "Have you figured out where the Kobolds are heading?", completion = "What's this, {name}? Tracking kobolds?\n\nWell, of course they're headed toward the Fargodeep mine! That place is infested with kobolds.\n\nGood work, I guess. I'm going to need someone to take care of that problem." }
WordHunterWoW_QuestEN[91775] = { title = "Book Return", description = "While you're investigating the Fargodeep Mine, see if you can find any of Brother Paxton's books to return. In particular, Paxton is very concerned about a book titled, \"Fun with Elementals\". He thinks even a kobold could use it to summon an elemental servant. Be warned, the depths of the mine are fairly dangerous. You should bring friends.\n\nTake this book bag to protect the books when you find them!", objectives = "Find 6 Lost Books and \"Fun with Elementals\" and return them to Marshal Dughan.", progress = "Have you found all the books yet?", completion = "I applaud your diligence, {name}. Brother Paxton sent a list of books, and you've found most of the missing ones. The rest must have been taken to the Jasperlode Mine.\n\nYou can keep that book bag!" }
WordHunterWoW_QuestEN[91777] = { title = "Rare Books", description = "There's just two books left missing on Brother Paxton's list: \"Geomancy for Curious Young Wizards\" and \"Arcane Explainer: Magical Stuff in Simple Words\".\n\nThe kobolds must have taken them to the Jasperlode Mine. Please track down those two books and bring them back to Brother Paxton.\n\nBut I'm afraid it will be quite dangerous. If the \"apprentice\" kobold was summoning an elemental, who knows what the master can do. I'd bring some friends if I were you.", objectives = "Recover \"Geomancy for Curious Young Wizards\" and \"Arcane Explainer: Magical Stuff in Simple Words\" and return them to Brother Paxton inside Northshire's Abbey.", progress = "Have you found all my missing books yet?", completion = "Oh, {name}! Thank you so much for saving my library. You've done me an amazing service. Please take one of these fine weapons. They were intended for the militia, but you can make better use of them." }
WordHunterWoW_QuestEN[91858] = { title = "Diplomatic Incident", description = "A most unfortunate turn of events in Silverpine has presented a unique opportunity for us to prove our worth in the eyes of the horde.\n\nA pair of dignitaries from the Earthen Ring went missing in Silverpine Forest en route to Tarren Mill. We don't know much else but rumors say that this is becoming quite the diplomatic incident. If we can recover these missing persons, it could help gain us the legitimacy we so dearly need.\n\nWe have a man at The Sepulcher, Trevan Rol. Travel there and speak with him.", objectives = "Travel to The Sepulcher in Silverpine Forest and speak with Trevan Rol about the missing Earthen Ring travelers.", completion = "Danitha sent you? Well in that case I already know why you are here. You just walked into a damned fine mess, {class}." }
WordHunterWoW_QuestEN[91859] = { title = "A Curious Pair", description = "Cutting straight to it, these \"dignitaries\" are no ordinary diplomats. One was a Tauren. Ordinary enough for the Earthen Ring, but the other--and you'll scarcely believe this--was an elf. A *high* elf. They were cloaked, but I've seen quel'dorei before and I'd bet my good pinky finger that's what I saw.\n\nWhy was an elf accompanying a Tauren through horde territory? Well, your guess is as good as mine. That's as much as I know, so I'd suggest speaking with Deathguard Baldren near the entrance to town.", objectives = "Speak with Deathguard Baldren about the mysterious Earthen Ring travelers who recently passed through The Sepulcher.", completion = "I might not care for you paladins, but I will say that your timing is impeccable. It's better to be lucky than good, I suppose?" }
WordHunterWoW_QuestEN[91860] = { title = "A Grim Fate", description = "Out on patrol last night I spotted a group of gnolls dumping a very large body onto a pyre on the shores of Fenris Isle. I didn't see an elf or any smaller corpses, but I'd say this doesn't bode well for them.\n\nIf you are brave or stupid you are welcome to charge into Fenris Isle to learn more, but if you ask me, its a lot of work to find some snooty elf that's probably long dead.\n\nI know you paladins love swearing oaths and taking on lost causes, but this one isn't worth it. Trust me.", objectives = "Investigate Fenris Isle to the east and learn the fate of the Earthen Ring traveling party.", completion = "<The corpse before you was certainly Tauren and you can tell that it was gnawed on heavily before it was tossed onto the pyre. You see no signs of the elf woman that was described to you though. Perhaps she is still alive somewhere deeper in the fortress nearby?\n\nThis will be dangerous, but there's only one way to find out for sure.>" }
WordHunterWoW_QuestEN[91861] = { title = "Into Fenris Keep", description = "<The fact that you only found only one body is a hopeful sign. Perhaps the High Elf that Trevan and Hadrec described is still alive somewhere deeper inside the nearby fortress?>", objectives = "Investigate Fenris Keep to the north and attempt to locate the missing member of the Earthen Ring party.", completion = "You are one of the Forsaken, yes? Can you help free me? \n\nTime is short for me, I am afraid. Please hurry!" }
WordHunterWoW_QuestEN[91862] = { title = "Lumina Windsinger", description = "Quel'dorei? No, I am no \"quel'dorei\". I am Lumina Windsinger and I am shen'dorei. One of the Windshaper Skyborne.\n\nI came to these lands as a guest of the Earthen Ring. My companion Banon and I were passing through Silverpine to reach the Arathi Highlands so that we could study the elemental convergences there. Clearly, we didn't make it.\n\nWe have no time for this now though. Kill the gnolls nearby. Retrieve the key to this cage and free me. I will tell you the rest once we are safely away.", objectives = "Retrieve the Fenris Isle Key from the Rot Hide Gnolls and use it to free Lumina Windsinger.", progress = "Gnolls are the second worst creatures I've encountered yet on Azeroth.", completion = "Thank you, {class}. Unfortunately we aren't out of danger yet." }
WordHunterWoW_QuestEN[91899] = { title = "A Sealed Crate", description = "", objectives = "Another delivery! Fantastic. Set it over by the pile and we can discuss your compensation.", progress = "Another delivery! Fantastic. Set it over by the pile and we can discuss your compensation.", completion = "Thank you for your hard work, {name}. There has been an uprising in bandits and thieves intercepting trade routes as of late. If you find other crates laying around, please bring them here and we'll handle the rest.\n\nHere is your payment." }
WordHunterWoW_QuestEN[91900] = { title = "A Sealed Crate", description = "", objectives = "Another delivery! Fantastic. Set it over by the pile and we can discuss your compensation.", progress = "Another delivery! Fantastic. Set it over by the pile and we can discuss your compensation.", completion = "Thank you for your hard work, {name}. There has been an uprising in bandits and thieves intercepting trade routes as of late. If you find other crates laying around, please bring them here and we'll handle the rest.\n\nHere is your payment." }
