WordHunterWoW_QuestEN[91906] = { title = "A Sealed Crate", description = "", objectives = "" }
WordHunterWoW_QuestEN[91920] = { title = "Wild Eyes", description = "I wouldn't dare to question the effectiveness of Apothecary Renferrel's formulae, however I would be lying if I said that the potion made any noticeable difference.\n\nAlong the shore of Lake Lordamere are a swarm of murlocs, and of note, murlocs have eyes. I suspect the apothecary's willingness to try new things is suppressed by his recent obsession with hearts. Bring him a few.\n\nIf my choice is to inevitably die a second death or have Renferrel kill me for questioning his methods, I choose the latter.", objectives = "Gather 3 murloc eyes and bring them to Apothecary Renferrel at the Sepulcher.", progress = "Oh. You're back?", completion = "The potion didn't work? Of course it didn't work. You brought me insufficient hearts. The recipe clearly calls for six. You brought three.\n\nHowever, I confess I hadn't considered applications for murloc parts until now...\n\n<Renferrel takes the eyes.>\n\nI can afford to sacrifice a few of my own hearts to get your Deathstalker's strength back." }
WordHunterWoW_QuestEN[91921] = { title = "Return to Quinn (Again)", description = "Here is the new potion to aid in Quinn's recovery, made with love extracted from six whole hearts.\n\nNow, please excuse me before your presence necessitates more paperwork.", objectives = "Bring Quinn's potion to Quinn Yorick at the Ivar Patch, north of the Sepulcher.", progress = "You return! I was beginning to come to terms with devolving into a ghoul.", completion = "<Quinn takes the potion and drinks it.>\n\nYes, I can feel it working.  I will soon be able to travel.\n\nYou have done me a great favor, {name}." }
WordHunterWoW_QuestEN[92109] = { title = "My First Alchemy Set", description = "Erm... 'Ello, <mister/miss>. I'm not supposed to talk to strangers, but... Hey, what are those shiny bottles sticking out of your backpack for? Are you an alchemist? That's so cool!\n\nWhen I grow up, I want to be an alchemist too. Daddy won't let me play with any of his herbs; too dangerous, he says.\n\nWell, I want to start learning now. Could you maybe get some supplies for me, pretty please?", objectives = "Gather 5 Empty Vials, 5 Silverleaf, and 5 Peacebloom to the young, aspiring alchemist inside the barn of Moonbrook in Westfall.", progress = "'Ello again! Did you bring back alchemy stuff?", completion = "Oh my gosh! Look at these! Did you pick the herbs yourself?\n\nWow, thanks mister, I am going to see what I can make with these right now! Do you want to watch?" }
WordHunterWoW_QuestEN[92110] = { title = "My First Real Potion", description = "Wow, my very first potion! Did you know that mixing those two herbs together would change the potion to a bright red color when you first started?\n\nThat was fun, but mixing a few flowers doesn't seem like the kind of alchemy Daddy does. He uses other ingredients too.\n\nI don't know what else to use, so let's try the first thing that comes to mind! Let's see... maybe murloc eyes? That sounds so gross, but I bet something will happen.", objectives = "Gather 3 Murloc Eyes for the young, aspiring alchemist inside the barn of Moonbrook in Westfall.", progress = "Don't worry about me, I'm a big girl. I can take care of myself. Just don't tell anyone I am hiding here, it's our little secret.", completion = "You brought me murloc eyes! I am so excited for my first REAL potion I can't breathe!\n\nI snuck out and grabbed a few more herbs while you were away and found some empty vials downstairs. Um... you can do the mixing this time.\n\n<The child watches enthusiastically you mix the ingredients, but her nose crumples as you add the eyes. The concoction takes on a sickly orange in mere seconds.>\n\nWow! See, I was right. I wouldn't drink that, but here's my recipe if you wanted to make more. Come back sometime!" }
WordHunterWoW_QuestEN[92124] = { title = "Book Inventory", description = "We need to take stock of how many books are missing!\n\nGo talk to my useless assistant, Daniel. He can do a quick inventory and let us know how serious the problem is.\n\nHe's obsessed with the various trade professions in Elwynn Forest. The boy keeps focusing on those instead of his important work helping me.\n\nDon't let him prattle on about tradeskills, and find out what's happened to my books!", objectives = "Speak to Daniel, Brother Paxton's assistant in the library.", completion = "Yah, I overheard. I warned Brother Paxton three times about the kobolds tunneling under the abbey.\n\nIt looks like the kobolds have taken a lot of books. There are whole bookshelves emptied out. You should probably see what Brother Paxton wants you to do about it.\n\nWhile you're here, can I talk to you about tradeskills? I'd be happy to answer any questions you have, or point you toward the local trainers." }
WordHunterWoW_QuestEN[92401] = { title = "A Frightened Request", description = "It's my husband Edward...\n\nHe has not returned from his weekly journey to the graveyard in the Lordaeron ruins. Our son was lost when Arthas razed the city, and my dear Edward is still filled with guilt and sorrow that we never found his body. I've tried to warn him against searching those overrun ruins, but he refuses to give up. I try not worry, but it's been days.\n\nThere are things there I cannot contend with but if you are willing, I need to know the fate of my husband.", objectives = "Investigate the disappearance of Edward Heartweaver in the Ruins of Lordaeron.", completion = "What I asked of you was not fair, nor would it have been unjust for you to simply walk away. Thank you stranger. I am unable to repay you in kind but I hope one of these is acceptable.\n\nI hope our paths cross again without such sorrow." }
WordHunterWoW_QuestEN[92415] = { title = "Remember That I Love You", description = "<A torn and stained bundle of parchment has barely survived the undead trodden grounds of the graveyard. It mentions a missing child of the Heartweaver family. Perhaps the orphan matron in Stormwind City will know more.>", objectives = "Bring the Blood-Stained Letter to Orphan Matron Nightingale in Stormwind City.", progress = "What is it, {name}? What are you looking for?", completion = "Heartweaver? Heartweaver...\n\nOh! Little Jeremy Heartweaver. He was brought in years ago after the attack on Lordaeron. Lost both of his parents in the attack, poor thing.\n\nHe was actually adopted not too long ago by a sweet woman out in Duskwood." }
WordHunterWoW_QuestEN[92421] = { title = "Light's Justice", description = "As a paladin of the Forsaken, it is my duty to exact the will of our Dark Lady while tending to our people's needs. We are fortunate with an opportunity to accomplish both.\n\nAbove the Undercity, the scourge still roam unchecked in great numbers. Our forces dwindle trying to reclaim our land, and decaying flesh cannot be reknit. Not without replacements.\n\nWould that our glorious captain Garek Bandarion still be with us, I know what he would wish. To finish what he started and heal our kin. For Lordaeron!", objectives = "Collect 25 Intact Limbs within The Ruins of Lordaeron for Morbin Lightbane in the Undercity.", progress = "What remains of the invading scourge? Have you managed to find suitable replacement parts?", completion = "Let those who fall from the Banshee Queen's grace meet our justice!\n\nWith these parts, our brothers and sisters have hope to see another day. You do Captain Bandarion proud." }
WordHunterWoW_QuestEN[92422] = { title = "The Wrath of Rath'mael", description = "Reports have come in from the Lordamere Overlook deep within the Ruins of Lordaeron. An unholy fog has taken over the streets and graveyard, affording the scourge up there some measure of stealth. \n\nOur scouts indicate they're being conjured by a new power within their ranks, a necromancer known as Rath'mael. We do not have the luxury of waiting this one out, {name}.\n\nIf you have allies, summon them and their aid to the Forsaken. Drive this creature out of our lands.", objectives = "Kill Rath'mael in the Ruins of Lordaeron for Deathguard Kristof in Brill.", completion = "While I have no doubt something of his kind will be replaced, we can only hope their ranks thin in the meantime.\n\nThank you {name}." }
WordHunterWoW_QuestEN[92432] = { title = "An Alarming Request", description = "I bring ill tidings from Dalaran. Something has disrupted our ley lines, causing erratic and destructive behavior from our constructs in the city.\n\nWe know not yet what is causing this mayhem. The high council has ordered us to keep this matter private so as to not bring shame to our order. But we cannot keep up this charade forever. The city is being overrun as we speak!\n\nArchmage Modera has dispatched me to solicit outside aid. Seek her image out near Dalaran beside Lordamere Lake.", objectives = "Report to the Image of Archmage Modera near the City of Dalaran." }
WordHunterWoW_QuestEN[92434] = { title = "Blood in the Streets", description = "Whatever caused Dalaran's barrier to lower has left the city in turmoil. With you having dealt with their patrols, there is no better time than now to make our way inside and discover their secrets.\n\nTake the key you found at the internment camp and seek out their sewers along the northern border of the city. With luck, those mages had no reason to put a ward over such a... disagreeable point of entry.", objectives = "Find a way into Dalaran along the Lordamere Lake." }
WordHunterWoW_QuestEN[92454] = { title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Dalia Windbreeze in Thendal Grove.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", objectives = "Bring the Thendal Grove Gift Voucher to Dalia Windbreeze." }
WordHunterWoW_QuestEN[92456] = { title = "A Green Sample", description = "If you're going to bother me you can at least make yourself useful. I have an errand I need run.\n\nFor a city of mages, Dalaran has a surprising interest in botany. The Kirin Tor keep to themselves, but I would love a sample of their mana-infused vegetation.\n\nYou're clearly someone who is comfortable being where people don't want you, maybe you could find a way into the city. If you do, bring me back whatever is growing in their central garden.", objectives = "Collect a Fel Infused Blossom from the City of Dalaran for Shylamiir in Stormwind City." }
WordHunterWoW_QuestEN[92457] = { title = "Starving Arcane", description = "The breach has affected many of our factotums and enchantments throughout the city, including many that are seeing to our defenses. This fragmented arcane energy has spoken to rogue elementals who seek to saturate themselves in this free flowing magic.\n\nWhile we are busy tending to the wards and other major incidents, it would be a favor to the Kirin Tor if you could cull this elemental throng.", objectives = "Defeat 8 Seeking Remnants, 8 Saturated Remnants, and 8 Mana Echoes inside the City of Dalaran for Archmage Modera outside of Dalaran." }
WordHunterWoW_QuestEN[92458] = { title = "Heart of Disruption", description = "Whatever disturbed the ley lines, it started at the top of the Violet Citadel. A thunderous crash rang out from the parlors above, and now we are overrun with rampant arcane power. It's taking all we have just to keep the wards in place.\n\nWe cannot afford to stall any longer. We need help.\n\nThe Kirin Tor are busy inside, but you will still need a less public approach to gain entry. Take this key and meet me in the citadel once you've made your way into the city. We must put an end to this disruption.", objectives = "Collect the Arcane Mote for the Image of Archmage Modera near the City of Dalaran." }
WordHunterWoW_QuestEN[92460] = { title = "Coming of Age", description = "Look at you, bright eyed and ready for adventure! We've been awaiting your arrival and anticipating your much needed help here in Thendal Village. I imagine you are brimming with both nerves and excitement for what is to come. After all, you only get to come of age once in a lifetime.\n\n<Ailee smiles kindly.>\n\nGo, seek out our village leader Rorian the Dayseeker at the entrance to the greatfather tree just west of here. He will get you started on your journey.", objectives = "Speak with Rorian the Dayseeker in Thendal Grove.", completion = "Gale's greetings, {name}. I am honored to bestow your coming of age relic today as you are recognized for the potential you bring to the shen'dorei. Our people have faced great hardship and persecution in our complex history.\n\nToday you are given this relic which is one of many held by those before you. Someday when your ashes are scattered to the winds it will pass to another to continue our tradition.\n\nAs you take this relic with you know that the winds of home will be with you wherever you travel." }
WordHunterWoW_QuestEN[92461] = { title = "Harmony in Balance", description = "We live in times of great uncertainty for our people. We face unprecedented challenges that may require bold solutions, but we also must contend with the ordinary and mundane here in Thendal Grove. Take, for example, the recent unsustainable rise in the vuldren population.\n\nThe vuldren are a vital part of our ecosystem. However, imbalances must be corrected to maintain the delicate harmony that all creatures in Thendal Grove share.\n\nHead east and cull some of the vuldren there.", objectives = "Slay 8 Vuldren Juveniles in Thendal Grove.", completion = "Thank you for your service to Zephras, young {class}.\n\nThe vuldren are typically quite docile, but the animals that call Zephras home can sense when the magic on the winds is out of balance, which can lead to dangerous and unpredictable behavior if left unchecked." }
WordHunterWoW_QuestEN[92462] = { title = "Infestation Investigation", description = "One of our rangers recently reported an infestation of cirrusflies here in Thendal Grove. \n\nCirrusflies can be dangerous if the swarm is allowed to grow too large, so please head to the eastern end of the Grove and exterminate as many as you can.", objectives = "Slay 8 Pesky Cirrusflies in Thendal Grove.", progress = "Such pests cannot be allowed to find root in our peaceful grove. An infestation can quickly grow dangerous if left unchecked.", completion = "Judging by the amount of bug entrails covering you, this must be quite the infestation." }
WordHunterWoW_QuestEN[92463] = { title = "The Cirrusfly Queen", description = "If the forest is as thick with these insects as it sounds, simply killing the workers won't be enough.\n\nGo deeper into the forest and find the queen. She'll be close to the hive and surrounded by bigger and more aggressive soldiers, so be careful.\n\nPut her down and return here when it's done. That'll be one less problem to think about around here.", objectives = "Destroy the Cirrusfly Queen in Thendal Grove.", progress = "Cirrusflies aren't to be underestimated. They might not seem dangerous, but you have to watch out for the bigger ones. The bigger they are, the meaner!", completion = "Excellent work, {name}. You'd make a fine ranger if this whole \"adventurer\" thing doesn't work out for you." }
WordHunterWoW_QuestEN[92464] = { title = "Elemental Unrest", description = "Ever since our elemental benefactors left us, it seems that we are simply moving from one unrest to another. The problem we face now is that the manifestations of the winds near the standing stones to the northeast are agitated.\n\nNot truly self-aware like the sentient wind spirits that once lived here, these simple sprites respond in kind to forces, emotions, and intentions of the creatures around them. \n\nMy apprentice Yala Windwatcher went to observe them. Seek her out and discover what she's learned.", objectives = "Speak to the Yala Windwatcher in Thendal Grove.", completion = "Rorian sent you? Good. I could use your aid." }
WordHunterWoW_QuestEN[92465] = { title = "Agitators", description = "The Al'Aketh cult is a blight upon this island. These cultists are surely the ones responsible for agitating the simple wind sprites that reside here and turning them violent.\n\nRegrettably, we'll need to disperse these roiling winds here before they harm someone. We also need to send a clear message to the cult that they are not welcome in the grove.\n\nWill you lend me your aid, {class}?", objectives = "Slay 6 Roiling Winds and 7 Al'Aketh Converts in Thendal Grove.", progress = "Is it done?", completion = "It pains me to shed shen'dorei blood here in the grove, but we do what we must." }
WordHunterWoW_QuestEN[92466] = { title = "Call of Earth", description = "While we owe much of our prosperity to the elements of wind, the path we walk requires that we obey the call of all four of the primary elements and undertake a trial for each. Before you begin your first trial in earnest however, you must prove the strength of your resolve.\n\nTravel to the standing stones to the east. A force of Al'Aketh converts has been spotted there and they must be driven off. Confront the cultists there and bring me one of their signets as proof of your deeds.", objectives = "Bring a Signet of Akir to Windshaper Boro.", progress = "The Al'Aketh cult represents the most direct and urgent danger to our homeland. Their increasingly extremist actions have destabilized our society and damaged our already-weakened connection to the spirits of the four winds. The elements demand action to prove our resilience and resolve, which are traits that are endemic to the domain of the element of earth.", completion = "You have returned and brought what I have requested and thus your grit and determination are unquestionable. You are ready for the next step, {name}." }
WordHunterWoW_QuestEN[92467] = { title = "Call of Earth", description = "A sapta is a drink created to bind our spirits to the elements. Fused with magic, the potion will allow the strong willed to see the elements as no one else can. Your spirit will be connected to the element the sapta was created for, and only a select few shaman know the recipe.\n\nThe sapta is always drunk in a sacred place, and never anywhere else--remember that.\n\nSeek out the Rise of Spirits up the pass northeast of here. Drink your sapta there, and... well, you will see what you need see.", objectives = "Find the Rise of Spirits and drink the Earth Sapta.\n\nProvided item:", completion = "Ah... {name}... child of the four winds... You seek understanding. You seek answers. Why have the winds left you? How may you get them back? These are answers I cannot provide, for I do not know the motives or movements of the winds.\n\nI can, however, teach you much of the earth. Its strength, its resolve. Even here, high in this endless sea of clouds, you are still a creature of the earth. If you hope to find the strength to speak to the spirits of the four winds once more, this is the path you must walk." }
WordHunterWoW_QuestEN[92468] = { title = "Call of Earth", description = "Take this Rough Quartz from me and bring it to the one you call Windshaper Boro as proof of our meeting. He will craft a totem for you, and this shard will be the heart of it. As small as it may seem, you will come to find that size does not matter, and that even the smallest of things can outlast many others.\n\nBe patient, {name}. Remain strong. And seek wisdom. This is what the elements ask of you. In the end, you shall become one with the earth--respect it as it shall respect you.", objectives = "Bring the Rough Quartz to Windshaper Boros in Thendal Grove.", progress = "As you will come to learn, the path we walk is not as simple as it may seem. While we seek to find the voice needed to speak with the spirits of the winds, the winds are but one of the elemental forces of this world. Only through understanding, and--we hope--mastery of all four elements will we regain our voice to again sing the songs of the wind.", completion = "Good!\n\nThe totem I will craft for you is more than a symbol of your status among {class}--it has abilities beyond that. One use of the totem is as a focus for spells. Those spells are tied to the earth, and as you earn greater and greater wisdom, more of the earth's abilities will be made accessible to you.\n\nThe trainers will know when you are ready for greater knowledge.\n\nBut for now, take this earth totem..." }
WordHunterWoW_QuestEN[92469] = { title = "Return to Rorian", description = "You've done enough here, {class}. I'll stay and clean up any stragglers down there.\n\nHead back to the Village and tell Rorian about the cult's presence. He will not be pleased.", objectives = "Bring word of the Al'Aketh to Rorian the Dayseeker in Thendal Grove.", completion = "This is most troubling, but unfortunately unsurprising. We've been aware of the cult's movements for some time, but we've been content to watch from afar. Their agitation of the wind spirits near the standing stones is a clear escalation on their part.\n\nYou've performed a difficult but necessary service for Thendal Grove, {name}. Thank you." }
WordHunterWoW_QuestEN[92470] = { title = "Foul Matriarch", description = "Rorian informed you that I've been watching you. I now offer you a test of resolve. However, be warned--it will send you into great danger.\n\nGo to the caves to the south. Thin out the ursera's numbers there, and find their matriarch, one the rangers call \"Urs'anah\". Put her down and bring me proof of her demise. Once you have done that, you will have taken an important step on your path.", objectives = "Slay 8 Ursera Scavengers and collect the head of the den mother, Urs'anah in Thendal Grove.", progress = "What I ask of you is not easy, but you must be prepared for much greater challenges if you are to survive long enough to be of service to Zephras Isle.", completion = "Very well done. You've felled beasts and laid low cultist interlopers. You have shown great promise but your path must soon take you beyond the relative safety of Thendal Village." }
WordHunterWoW_QuestEN[92471] = { title = "Aetheen of the Gales", description = "You may not realize this but everything you've done has been a trial of sorts. A test for what is to come for you. It's a big island out there, and Zephras needs spirited young adventurers such as yourself if we are to survive the trials our people face.\n\nThe one called Aetheen of the Gales is one of the leaders of our people here on Zephras Isle, and she has been watching you. She has a task that you must complete. Speak with her to learn more.", objectives = "Speak with Aetheen of the Gales in Thendal Grove.", completion = "Rorian has told me much of you. I am likely unknown to you, but I am a member of the Council of Elders here on Zephras Isle. I've come to read the flow of the winds here in Thendal Grove. I'm also here to assess young shen'dorei such as yourself that are coming of age.\n\nSo tell me, are you ready to take your next step? Are you ready to serve Zephras Isle?" }
WordHunterWoW_QuestEN[92472] = { title = "The Next Step", description = "One of the most pervasive threats on Zephras Isle is the Al'Aketh Cult. They are religious zealots devoted to the worship of the supposed elemental ruler of Skywall, Al'Akir the Windlord. They are brutal, single minded, and their power and ambitions are growing more deadly by the day.\n\nYour path will soon take you to Shen'dar Village to the south. Present yourself to Constable Aonda when you arrive. The cult threatens Shen'dar and they are in need of aid. Tell Aonda that I sent you.", objectives = "Report to Constable Aonda in Shen'dar Village.", completion = "Aetheen sent you, then? I'll confess, you don't look like much to me, but Shen'dar Village won't turn down willing aid, much less aid sent from Elder Aetheen herself." }
WordHunterWoW_QuestEN[92473] = { title = "Aggressive Encroachment", description = "The ursera den to the southwest is rapidly becoming a problem. Just last week the rangers had to kill an adolescent ursera who wandered too close to the village and attempted to attack a boy playing near the base of the elder tree in the center of the village.\n\nWe were fortunate that the boy escaped with his life. Hunger and desperation makes these beasts too dangerous to be left unchecked. Go south and put the scrawniest among the ursera down. Bring me their claws as proof when it is done.", objectives = "Collect 6 Scrawny Ursera Claws from Scrawny Ursera in Thendal Grove.", progress = "The ursera have grown far more aggressive of late. I wonder what has changed to cause this shift in behavior?", completion = "Well done, {class}. The Rangers of the Grove are in your debt." }
WordHunterWoW_QuestEN[92474] = { title = "Falling With Style", description = "Well hello there, {name}! Want to play a game?\n\nAll you've got to do is step up on that ledge... then jump! Use your innate ability to walk on the air to slow your fall and see how far forward you can float.\n\nThe rules are made up and the points don't matter, but you get bonus points if you can land right in front of Rorian the Dayseeker and startle him! He won't like it but I'll certainly get a good laugh if you can get him all worked up! Hah!", objectives = "Jump from the top of the watchtower in Thendal Grove and use your Walk on Air ability to slow your fall.", progress = "Using your ability to walk on air can get you out of--and, well... into--all kinds of trouble!", completion = "How many times do I need to tell Myriaal not to encourage others to make reckless usage of our skyborne gifts!\n\nThat being said, I suppose that a little bit of practice in the relative safety of the village is... acceptable.\n\nIn the future I'd simply suggest you to use your ability judiciously. You do not want to exhaust your magic thoughtlessly and then not be able to use it when you truly need it." }
WordHunterWoW_QuestEN[92479] = { title = "A Scribbled Letter", description = "I was asked to bring this to your attention as soon as you returned from the kobold camps, {name}. It appears to be a letter sealed with the mark of Tordrin Stemblade, our local hunter trainer. Take a moment to read it before you go about any other business here in the Abbey.", objectives = "Read the Scribbled Letter and speak to Tordrin Stemblade in Northshire Abbey.", progress = "Ah, ye got me letter, {name}... good.\n\nTime was when ye'd not catch a {race} dead wit' a bow in their hand--no more, I guess. It's good for Stormwind, but bad for the kobolds and man eatin' beasts in the area.", completion = "Get yerself squared away, learn the lay o' the land, and come back to me whenever you need training. I'll be here night or day.\n\nThis land is grown' more dangerous, and as ye meet other folk, I think ye'll find they all have problems they could use some help with--help a skilled {class} can give 'em. Good luck." }
WordHunterWoW_QuestEN[92480] = { title = "zzOLD UNUSED Cult Ambush", description = "The cultist you just killed dropped what appears to be orders from a high priestess of the Cult of Al'Akir. It makes mention of a spy in Shen'dar Village and cult operations in a place called Falaath Village. The authorities at Shen'dar Village will want to learn of this.", objectives = "Bring the Orders from the High Priestess to Shen'Dar Village and present it to whomever is in charge there." }
WordHunterWoW_QuestEN[92481] = { title = "A Student of the Arcane", description = "While you were away dealing with our vuldren problem, our resident mage trainer--Dorii Brightwhisper--left this recall crystal for you. It contains some sort of message for you, so give it a look. Afterwards, you can find Dorii in the structure just behind me.", objectives = "Examine the Glowing Recall Crystal, then speak with Dorii Brightwhisper in Thendal Grove.", progress = "Greetings, {name}. I'm pleased to have the privilege of furthering your magical studies.", completion = "Let me have a look at you. Yes, I believe you will make a fine young {class}. The power of the arcane has waned amongst our people, but there are those who would seek to rediscover much of what we've lost in the millennia we've spent here amongst the clouds. I am sure that you will lead the charge in this never ending search for arcane knowledge, and ultimately make us proud.\n\nSpeak with me again if you wish to take your next steps." }
WordHunterWoW_QuestEN[92482] = { title = "The Way of the Hunter", description = "While you were away dealing with our vuldren problem, our resident hunter trainer--Tai'ree Farsight--left this note for you. You can find her just over yonder near the center of the village. Read the note then seek her out.", objectives = "Read the Scribbled Note and then speak with Tai'ree Farsight in Thendal Grove.", progress = "<Tai'ree nods at you curtly.>", completion = "The way of the {class} is fraught with danger, and only those with the keenest senses and quickest reflexes can thrive in the wilds. I look at you and I am reminded of myself when I stood before my mentor, so many years ago. I believe that you have what it takes, but in the end that is up to you alone.\n\nSpeak with me again if you wish to take your next steps." }
WordHunterWoW_QuestEN[92483] = { title = "At Home in the Shadows", description = "While you were away dealing with our vuldren problem, our resident rogue trainer--Akeri Duskblade--has requested to speak with you. He left this note, so read that first, then seek him out inside the watchtower, here in the village.\n\nHe's a shady fellow, but then again, so are you. I think you'll get along well.", objectives = "Read the Simple Note then speak with Akeri Duskblade within the watchtower in Thendal Grove.", progress = "<Akeri eyes you suspiciously.>", completion = "I almost did not hear you approach me, young {class}.\n\nAlmost.\n\nAlmost won't be good enough when you leave Thendal Grove. You must be a slender blade, silent and steady. Ever vigilant and ever mindful of your surroundings. You might have what it takes to survive the dangers of Zephras. You also might end up with your throat slit in a ditch. Ultimately that's entirely up to you.\n\nSpeak with me again if you wish to take your next steps." }
WordHunterWoW_QuestEN[92484] = { title = "Embracing the Elements", description = "While you were away dealing with our vuldren problem, our resident Shaman trainer--Windshaper Boro--left this recall crystal for you. Please examine it, then speak with Boro just over yonder near the center of the village.", objectives = "Examine the Humming Recall Crystal then speak with Windshaper Boro in Thendal Grove.", progress = "Winds guide you, {name}.", completion = "Can you hear it? The whispers of the winds? Doubtful, considering that the spirits stopped speaking with us when they left us those years ago. \n\nThose among us who would seek audience with the spirits of the four winds once more hone our understanding of the elements and the natural world, dearly hoping to reestablish the dialogue that was so abruptly ended. \n\nWould you walk this path and master the elements?\n\nSpeak with me again if you wish to take your next steps and I will train you." }
WordHunterWoW_QuestEN[92485] = { title = "A Student of Nature", description = "While you were away dealing with our vuldren problem, our resident druid trainer--Xyton Silverwind--left this note for you. Read it as soon as you can, and then seek out Silverwind on the ground floor of this great tree just behind me.\n\nHeed his words and his counsel, he can teach you much.", objectives = "Read the Folded Parchment then speak with Xyton Silverwind in Thendal Grove.", progress = "Greetings, I am Xyton Silverwind, keeper of druidic lore.", completion = "The flora and fauna of Zephras Isle represent a rich tapestry of vibrant life. The ecosystem requires constant balance to maintain the harmony of nature, and we druids are the keepers of that balance. I see much potential in you, but this path is not an easy one, and you will need guidance as you grow in strength as a student of the fang, the claw, the feather, and the branch. \n\nSpeak with me again if you wish to take your next steps." }
WordHunterWoW_QuestEN[92489] = { title = "Power Overwhelming", description = "The Kirin Tor have long been allies of the Alliance. With the destruction of their city at the hands of the arch demon Archimonde, the once proud city of mages has now become reclusive and distrusting of outsiders.\n\nIn recent years they have begun reconstruction efforts to bring the city of Dalaran back to its former glory. However, reports show they are struggling to contain an outbreak of wayward arcane energies.\n\nWe must help them disperse these attacks lest we lose one of our most powerful allies.", objectives = "Slay the Mana Elemental in the City of Dalaran for High Sorcerer Andromath in Stormwind City." }
WordHunterWoW_QuestEN[92514] = { title = "Welcome to Shen'dar Village", description = "You've got that \"Windshaper\" air about you. Something about how I can feel a tiny bit of static on my skin when near someone spirit-touched that gives it away. Before I properly put you to work around here, you should check in with our resident Windshaper elder, Illaya Amberwind. She's just outside, near the center of town.\n\nOh, and check in with Coriella Calmbreeze as well, she runs the local inn and can provide lodging and supplies, should you need them.", objectives = "Speak with Illaya Amberwind and Coriella Calmbreeze in Shen'dar Village.", completion = "Checked in with Illaya then? Great. Lots of tension between the High Order and the Windshapers these days, but they keep things civil here in Shen'dar. Everyone here is well aware that we've got bigger problems than their quibbles.\n\nNow that that's done, you look like someone who might be looking for something to do with their hands and I've got a bandit problem that I was hoping you could help me with." }
WordHunterWoW_QuestEN[92515] = { title = "The Problem With Prideclaws", description = "As if bandits and mad cultists weren't enough, the hills are thick with prideclaws as well right now. They are starting to encroach on the village borders and growing bolder by the day. It's only a matter of time before someone's pet or child is taken. It would be a mercy for us to cull their numbers now rather than after some tragedy occurs.\n\nBring me a dozen or so of their pelts. I can turn them into all sorts of goods that will be of aid to the village.", objectives = "Collect 10 Prideclaw Pelts from the Prideclaws in Shen'dar Highlands.", progress = "If you ask me, I think Prideclaws are actually kind of cute. From a safe distance... and while standing behind someone holding a sword, of course.", completion = "I didn't say it wouldn't be a dirty job, did I?" }
WordHunterWoW_QuestEN[92516] = { title = "Hippogryph Harrassment", description = "A flock of Hippogryph have recently established nesting grounds southeast of Shen'dar Village and they've been wreaking havoc on travelers on the road. I need someone to head down there and thin them out for us.", objectives = "Slay 8 Hippogryph Youths, 6 Hippogryph Protectors and a Hippogryph Matriarch in the Shen'dar Highlands.", progress = "Hippogryphs are very proud creatures. It's probably the noise from the wagon trains that rile them up and cause them to attack. Whatever the reason for the attacks, dead caravaneers aren't something that we can ignore.", completion = "Well done, and quickly too. Not too bad at all." }
WordHunterWoW_QuestEN[92517] = { title = "The Criminal Element", description = "There's a cave not far to the north, hidden behind a waterfall. It's well known to me that there's a group of bandits that are operating out of that cave. They were a problem for us before the cult arrived, but now they are a real terror. I can't spare the people to go and clear them out, unfortunately.\n\nI need you to go there and take care of them for me. Kill as many as you can, and if possible, take out their leader, the one they call \"Badwind\" Bennic. That cave is dangerous, so be careful.", objectives = "Kill 10 Highlands Bandits and their leader, \"Badwind\" Bennic in the Shen'dar Highlands.", completion = "With the bandits dispersed, that is one less problem for us to deal with. Though I confess that now I worry that any bandits who survived may turn next to the cult for protection, further bolstering their increasingly alarming numbers.\n\nStill though, we'll take the victories where we can get them." }
WordHunterWoW_QuestEN[92519] = { title = "Ward Restocking", description = "Apothecary Jorell was supposed to bring us a case of antidotes and elixirs days ago, but we're still empty handed. That fool has probably poisoned himself again by brewing in that poorly-ventilated shack he calls his lab.\n\nIf you want to further help our ward, you would be a far more reliable individual for this job.\n\nFollow the road to Go'shek farm, south and a bit west of here. You'll likely find it packed and ready to go, with Jorell either missing or unconcerned with his obligations.", objectives = "Pick up a case of Packaged Tonics at Jorell's lab in Go'shek Farm and return to Doctor Gregory Victor in Hammerfall." }
WordHunterWoW_QuestEN[92528] = { title = "Among the Faithful", description = "The faithful of Al'Akir grow ever stronger with each eager new recruit like yourself. As you can see, our strength gives form to the storm itself!\n\nNormally I'd send you straight to Skypriest Aanders for assessment, but he is occupied at present receiving a guest at the inn on the north side of town. Please avoid that place for now. An unshaven recruit like yourself in the presence of such a guest would be inappropriate.\n\nFor now, just don't get in anyone's way.", objectives = "Look around Falaath Village to learn about the cult's intentions in the Shen'dar Highlands.", progress = "What did you learn?", completion = "Lorthuna herself was there? She's the leader of the whole damned cult!\n\nIf they are making a move on Shen'dar Village and the western watchtower, we've got to be ready. What is strange is... why the watchtower?\n\nThe Village I can understand, but the tower? It doesn't have much strategic significance, other than as a minor lookout post.\n\nRegardless, we will be prepared for them. They'll find that highlanders aren't as easy to catch flat footed as they might think." }
WordHunterWoW_QuestEN[92529] = { title = "Falaath Village", description = "It gladdens my heart that you wish to serve Al'Akir. Our current trials as a people stem from our own complacency. We grew prideful and took the bounty of the winds for granted. The stagnation that followed is the reason the spirits of the wind abandoned us.\n\nOnly through acts of contrition may we feel the wind's caress once more. If you seek the fellowship of like-minded shen'dorei, go to Falaath Village and find Missionary Jasaan there. I will mark you so that the faithful will know you as a recruit.", objectives = "Report to Missionary Jasaan near the entrance to Falaath Village.\n\nIf you lose your Mark of Akir, speak with Sania Silverstream in Shen'dar Village to regain the effect.", completion = "What is this? A new acolyte seeking to serve the windlord sent by sister Sania? Truly we are blessed by the touch of the four winds this day!\n\nWe welcome all who seek to bask in the blessings of Al'Akir." }
WordHunterWoW_QuestEN[92532] = { title = "The Warrior's Path", description = "While you were gone our warrior trainer--Blademaster Ren--requested that we send you their way when you returned. She dropped this note off for you as well.\n\nGive it a read, then find Blademaster Ren inside the village watchtower.", objectives = "Read the Crumpled Note you've been given, then seek out Blademaster Ren inside the Thendal Village watchtower.", progress = "So you've come for training, then?", completion = "You are about to embark upon a dangerous journey. Our world is changing and it will need those who have the will to lead and protect others if our people hope to survive. As you grow in power you will need guidance. Come to me--I will do what I can to train you as you progress.\n\nGood luck, {name}, may the winds guide you." }
WordHunterWoW_QuestEN[92534] = { title = "jktestquest1a", description = "", objectives = "" }
WordHunterWoW_QuestEN[92544] = { title = "Al'Aketh Thugs", description = "A band of Al'Aketh cult ruffians have taken up residence near the temple ruins just southwest of here, led by a real monster called Malduko Cloudcrush. This rabble has no doubt been dispatched here by High Priestess Lorthuna at the Shrine of Akir to attack travelers and coerce our people into joining the cult.\n\nI need to stay here at my post to alert travelers leaving the grove of the danger, but I would be grateful if you could do something about those cultists and their leader for me.", objectives = "Slay 6 Al'Aketh Brutes, 4 Al'Aketh Neophytes, and Malduko Cloudcrush in Thendal Grove.", progress = "I suspect that seeing a few of their fellows bleeding on the ground will do wonders to dissuade any zealous ambitions these thugs might have had.", completion = "It was all I could do to stop myself from going over and joining you from my position here. I can only hope that these louts got the message and clear out of here soon. \n\nThank you, {class}. You have the gratitude of the Rangers of Thendal Grove." }
WordHunterWoW_QuestEN[92550] = { title = "Havoc in the Highlands", description = "Our best defense here might just be a strong offense. The advantage we now have is that we expect an attack is coming. What they won't expect is for us to hit them first.\n\nI've already asked a lot of you, but please head back over to Falaath Village. Kill as many cultists as you can and if you can get close enough, kill the commander and bring me his head. I'll stay here and organize the citizens and our few peacekeepers to prepare a defense... just in case you don't return.", objectives = "Travel to the ruins of Falaath Village and slay 6 Al'Aketh Stormcallers, 4 Living Lightning and take the head of Commander Cyclas.", progress = "It feels good to turn the tables on these zealots.", completion = "Thank the winds you've returned!\n\nSania Silverstream snuck out of town just before you returned, no doubt fleeing at the sight of our people arming themselves.\n\nYou've done an incredible thing for the people of Shen'dar Village and we owe you a debt of gratitude. If the cult returns to the highlands, they will find that Shen'dar is not such an easy target.\n\nWinds guide you, {name}." }
WordHunterWoW_QuestEN[92551] = { title = "Stolen Supplies", description = "I overheard you might be going to Falaath Village? While you are there, please keep an eye out for our stolen supply caches.\n\nThe Al'Aketh have been raiding our supply caravans carrying various goods such as food and windstones to and from the lowlands for months. They've been blaming the bandits, of course, but we all know that it all ends up in the same place. If there's any of that stuff left in Falaath, it would be a huge help if you could recover it.", objectives = "Collect 10 packs of Stolen Shen'dar Supplies from Falaath Village in the Shen'dar Highlands.", progress = "There's a lot of hungry and desperate skyborne here who need these supplies.", completion = "This is great! We've been barely squeaking by without our regular supply deliveries. I'll work with the constable to ensure that these supplies get redistributed to the townsfolk who are in most dire need." }
WordHunterWoW_QuestEN[92553] = { title = "Restocking the Larders", description = "Up for a bit of work? I could use a bit of muscle from a strong adventuring-type such as yourself. With how dangerous things are getting around here, no one's had much time to hunt or forage of late, and I need someone to get out there and source me fresh eggs and strider meat to keep this village fed.\n\nI'd be happy to teach you one of my famous recipes if you can bring me what I need. What do you say?", objectives = "Collect 3 Small Eggs and 8 Strider Meat from creatures found throughout the Shen'dar Highlands.", progress = "No matter how much things change here on Zephras and how uncertain things get, I always say that a pipe full of dried peacebloom and nice full belly is a comfort that can't be beat!", completion = "These eggs aren't easy to get but wind save me, they are DELICIOUS fried up in a bit of ursera tallow.\n\nIf you've got a bit of time to spare and you enjoy cooking, I can teach you a few tips and tricks I've picked up. Say the word and I'd be happy to train you." }
WordHunterWoW_QuestEN[92579] = { title = "To Valanaar", description = "For now it seems the pylon and the village are safe, so I'd like you to deliver this report to the Valennia Stormfist in Valanaar, at the southeastern edge of the island. Valennia is the leader of the peacekeepers on the island and she needs to know what happened here.\n\nThe cult is expanding rapidly and the peacekeepers have avoided direct conflict until now, but those days are over. Valanaar will need to be ready for a fight.\n\nAt any rate, thank you. You'll always have friends in Shen'dar, {name}.", objectives = "Deliver Aonda's Written Report to Valennia Stormfist in Valanaar.", progress = "A letter from Aonda. What's that crafty highlander been up to?", completion = "<Valennia's expression darkens as she reads the letter.>\n\nAonda trusted you to deliver this and she speaks highly enough of you in this letter, so I'll try to trust you too. Before we speak further, I need to consult with the few peacekeepers we have left here and formulate a plan in case the cult strikes here next. Enjoy your stay in Valanaar for now.\n\nIf you are looking to keep yourself busy, there are plenty of townsfolk that can likely use the help of a strong young adventurer like yourself." }
WordHunterWoW_QuestEN[92595] = { title = "The Windshapers", description = "<Illaya smiles warmly at you.>\n\nI am glad you returned to speak with me, child of the winds. I knew it the first moment you walked into my presence, that you were strong in the skysight. Do you find this surprising? Even those who have not trained as a Shaman may possess the gift. \n\nCome, let us speak about the mandate of the Windshapers, the nature of our struggles on Zephras, and the plight of our people.", objectives = "Listen to what Illaya Amberwind has to say.", progress = "The world is changing and the path forward will be difficult. We have but one chance to save ourselves.", completion = "I think you now understand how important the mission of the Windshapers is. Every soul who commands the skysight is of vital importance if we hope to establish dialogue with the spirits of the winds once again.\n\nBetween threats from within such as the Al'Aketh, and the uncertainty of our safety here in Skywall, it is our responsibility as Windshapers to use our gifts to save our home and ensure that the Shen'dorei can survive these trying times." }
WordHunterWoW_QuestEN[92596] = { title = "The High Order", description = "The aura of arcane energy that surrounds you is strong, even though you are not initiated as a mage. I am quite sure that you are going to be a capable adventurer, and your connection with our ancient magic will only ever be a boon to you even if you were to never utter a single word of power in spellcasting.\n\nCome, let us sit and speak some on my order, the nature of the arcane here on Zephras, and the plight of our people.", objectives = "Have a seat and speak with Rathiril Sunlance.", progress = "Our land is going through changes, but there may yet be some good to come of this.", completion = "The High Order's mission is vital to the survival of our people. We hold our elemental benefactors in the utmost regard, but we must face reality; they are gone now, and we are on our own.\n\nBetween threats from within such as the Al'Aketh, and uncertainties of our security on this plane, it is our destiny as Highborne descendants of our ancestral home of Eldre'Thalas to use our gifts to ensure that the shen'dorei can stand on our own once again." }
WordHunterWoW_QuestEN[92597] = { title = "Reading the Ley Lines", description = "Here in the elemental plane, we derive much of our arcane strength from ley lines that still run through the ground under our feet. Of late, these ley lines have begun to pierce the surface, giving us more direct and powerful access to these latent arcane energies.\n\nGo to the standing stones to the northeast. There is a ley line there. Tap into your birthright and draw in its energy.", objectives = "Use your Read Ley Line racial ability at the ley line in Thendal Grove.", completion = "Do you feel it? Yes? Good! You have taken your first steps. You'll find that with your abilities, you will be able to tap into latent magical energy in many locations. Doing so will provide a myriad of benefits, some profound, others more subtle. You won't know until you tap into them, But that's the best part of the gift... making the unknown known.\n\nIf we are to survive these dire times, we must be unwavering in our search for knowledge... and power." }
WordHunterWoW_QuestEN[92598] = { title = "The Gift of Skysight", description = "As a Windshaper, you have the ability to use the sacred skysight gifted to us by the elemental spirits. Travel to the standing stones to the northeast of the village. Find the elemental convergence there and use your gift.\n\nYou'll find that you may draw upon the skysight anywhere, but its boon is much more powerful if you do so in the presence of an elemental convergence. You may at times receive other bits of wisdom from the spirits that are drawn to such places of power, as well.", objectives = "Use your Skysight racial ability at the Elemental Convergence in Thendal Grove.", completion = "Like a muscle, your skysight must be exercised if you hope to grow stronger in the gift. Leveraging your skysight to bridge the distance between the mortal and the spiritual may prove invaluable to you in your adventures.\n\nYou'd do well to remember what you've learned here today. Our ability to use our gifts to hear what the elements tell us could be the key to our survival." }
WordHunterWoW_QuestEN[92640] = { title = "Desperate Times", description = "Since engaging the cult in the open is not viable, our best chance is going to be to use this opportunity to attack the shrine itself. We can take Lorthuna herself off the board before she can finish her part of this scheme.\n\nIt so happens that Valennia has been preparing a strategy for a potential assault on the Shrine for some time now. The only problem is, we will need help. \n\nSpeak with Valennia for the details.", objectives = "Speak with Valennia Stormfist in Valanaar and follow her instructions.", completion = "Tensions between the Windshapers and High Order are high right now, but we couldn't hope to carry out this plan without both groups on board." }
WordHunterWoW_QuestEN[92642] = { title = "Disrupting Logistics", description = "Valennia only sent one person to help repel a full-scale assault... by the winds.\n\nYou don't look like much but I'll take what I can get. We need to inflict as much damage as possible to stop this soon. My people can't hold out much longer.\n\nGo down the hill and disrupt their logistics. Their healers are keeping the attackers coming, if we take them out we might be able to rally and push them back. Any other cultists you kill while you are out there are helpful as well.", objectives = "Slay 4 Al'Aketh Healers and 8 Al'Aketh Brawlers in the Gustberry Lowlands.", completion = "You are still alive? Thank the winds for small miracles, I suppose." }
WordHunterWoW_QuestEN[92643] = { title = "The Turncoat", description = "There is a turncoat amongst the Al'Aketh. They claim to know the cult's true intentions for the island and want to come in, but will only do so with assurances of protection.\n\nThis defector is hiding at a secluded residence just northwest of Valanaar inside the highlands. I need someone who can discreetly go there, find the traitor, and escort him back to us. This might be a trap, but if this information is as important as this traitor claims, its worth some risk.", objectives = "Find the cultist turncoat at the house just inside the highlands northwest of Valanaar.", completion = "<This man is clearly dead, killed by the assassins that you fought outside the house. As you kneel down to inspect the body you notice the glinting reflection of something shiny...>" }
WordHunterWoW_QuestEN[92644] = { title = "Unfortunate News", description = "<You reach beneath the still-warm body of the turncoat cultist and recover a small, glowing blue crystal. It appears to be damaged, but it may still be important. High Elder Shadowsong may be interested in this.>", objectives = "Deliver the glowing crystal to Talanaanis Shadowsong in Valanaar.", progress = "You are back? And... alone?", completion = "The turncoat was already dead when you arrived, you say? This is unfortunate news.\n\n<You hand over the crystal you found on the dead cultist's body.>\n\nInteresting..." }
WordHunterWoW_QuestEN[92645] = { title = "Breaking the Breaker", description = "This attack is going to be hard to repel unless we can take out the cult commander. Belguilos \"the Breaker\" they call her, and she's a veritable terror. She used to be a peacekeeper before the cult got out of control, and even then she was... off. As a cultist I can only imagine how much worse she could be now.\n\nI might just be sending you to your death, but someone needs to take Belguilos out if we are going to survive here. You can find her at the villa at the hill's base. Good luck, {class}.", objectives = "Slay Commander Belguilos in the Gustberry Lowlands.", completion = "Belguilos is dead? Four winds bless you, {class}. \n\nWe might just make it out of this alive after all." }
WordHunterWoW_QuestEN[92646] = { title = "Confront Lorthuna", description = "Lorthuna fled up to the spires above using some sort of portal. Ayessa and Elaadrin went in after her. That was just a few moments ago.\n\nI'm afraid I took one too many hits and this is where I stay. Go through the portal, find Ayessa and help them stop Lorthuna.\n\nUnless that help that Elaadrin and Ayessa said they sent for arrives soon, you are on your own from here. Good luck, {class}.", objectives = "Take the portal to the Rohashi Spires overhead and join Elaadrin Evengale and Ayessa Dawnsinger in their confrontation with the High Priestess Lorthuna.", completion = "I sent a few of our healers to ensure that Valennia and her remaining forces made it back in one piece. She should be resting in the High Elder's residence now.\n\nMuln has already departed back to Azeroth, but he and I spoke of what is next for the Windshapers and our mission to Azeroth. Unfortunately, the island is more vulnerable than ever now and we need a plan to protect Zephras from what is to come." }
WordHunterWoW_QuestEN[92679] = { title = "Blood Tithe", description = "H--Hello, stranger. You have the look of a capable adventurer about you. I...\n\n<The Skyborne man winces, clearly suffering terrible pain>\n\n...I was wondering if you were seeking employment? I came here to Valanaar to recruit fighters to help save my farm. If you are interested, please go find my wife Aamelia Windfield at our orchard to the west of Valanaar, in the lowlands.", objectives = "Listen to what Alvarion Windfield has to say and find Aamelia Windfield at the Windfield Orchard.", progress = "What? Alvarion is alive?", completion = "<Aamelia listens while you explain what became of Alvarion.>\n\nAt least I know he's going to be safe in Valanaar.\n\nStranger, I hate to tell you this but I think my idiot husband likely just sent you here to die for nothing. If you have any sense at all, you should leave now. This isn't your fight." }
WordHunterWoW_QuestEN[92682] = { title = "Make Yourself Useful", description = "Oh, so you've got more courage than sense, then? Fine, I won't argue.\n\nFerauu and his goons aren't due to pick up their take of the harvest just yet, so I'm going to put you to work for your meals until they arrive.\n\nHead outside and gather today's batch of stormapples for me. Oh, and the bandits lurking around the stormapple trees... They think they are sneaky. They aren't. Kill them for me. \n\nLet's see what you've got in a fight.", objectives = "Gather 10 Ripe Stormapples and slay 5 Hungry Bandits at the Windfield Orchard.", progress = "These bandits are more likely to double cross and steal from each other than they are to steal from normal folks. I bet if Ferauu knew some of his people went rogue and came here early to tamper with the harvest, he'd kill them himself.", completion = "I watched you take down those bandits from the window. Not bad." }
WordHunterWoW_QuestEN[92683] = { title = "Flutterfly Dust", description = "I'm sure you've noticed the giant flutterflies out in the outer fields near the orchard? They are pleasant to look at, but they also have other benefits; namely their wing dust. It can be a mess, but if you can gather it up in large amounts, it has useful household applications.\n\nTake this Flutterfly Swatter and give the big bugs a good swat for me. They'll usually just get scared and flee, but sometimes they'll take some offense. Either way, they'll give their rumps a shake and drop a pile of dust.", objectives = "Gather 5 Flutterfly Dust from the Flutterflies around the Gustberry Lowlands.", progress = "Flutterflies are normally docile and calm, but rub them the wrong way and sometimes they'll surprise you.", completion = "This stuff can be a bit messy and it tends to get everywhere. You'll probably be shaking this out of your trousers for weeks, unfortunately. I do appreciate it, though. I've had this on my to-do list for weeks, but getting too far from the house when it's just me on my own with bandits lurking everywhere is a big risk.\n\nDon't bother asking me what I use this stuff for. Things. Stuff and things. Don't worry about it." }
WordHunterWoW_QuestEN[92684] = { title = "Ornery Ornery Galestriders", description = "As if the harvest wasn't light enough this year already, the galestriders in the area have been getting into the orchard and stealing my stormapples. Think you can head out to the fields and cull them for me?\n\nTake care though stranger, these lowlands galestriders are bigger and angrier than the highlands variety. Watch yourself. A well timed kick is all it takes to put you down for good if you aren't paying attention.\n\nBring me some of their meat and I can make us a hot meal with it as well.", objectives = "Gather 7 Lowlands Galestrider Tenderloins from the Ornery Galestriders found throughout the Gustberry Lowlands.", progress = "I don't think I've had real meat for dinner in... well, too long.", completion = "These are big tenderloins! You must have taken down some real monsters out there." }
WordHunterWoW_QuestEN[92685] = { title = "The Hills Have Eyes", description = "The bandits have camps all over and there's a small one in the hills just north of here. Head up there and start cracking skulls. If we can catch them off guard and take them out before they come for us, we might just even the odds enough to stand a chance.\n\nBring me their masks. The bloodier the better.", objectives = "Loot 7 Blood-Stained Bandit Masks from Highwayman Bandits in the Gustberry Lowlands.", progress = "If you manage to bring me enough bandit masks, maybe I'll stitch a blanket out of them and give it to Ferauu.\n\n<Aamelia laughs loudly.>", completion = "When I said the bloodier the better, you really listened. Good. It lets me know you made it hurt.\n\nOn a serious note, thank you for what you've done so far. I've been floating aimlessly around this farm for weeks as if I was just waiting for the end to come. I think I'm starting to have hope again.\n\nFerauu and his thugs are due any time now. All that's left is to go out and face them. What do you say, will you see this through to the end with me?" }
WordHunterWoW_QuestEN[92693] = { title = "Standing Our Ground", description = "You've done a lot to give us a fighting chance. Even if we die today, we'll at least know we gave it our best shot.\n\nThis is your last chance, stranger. If you want to head back to Valanaar and live another day, I wouldn't blame you.\n\nOn the other hand, if you really have a thing for lost causes just let me know when you are ready to go. We'll walk out there with our heads held high and whatever happens, happens.", objectives = "Speak with Aamelia Windfield when you are ready to confront the bandit leader.", progress = "There's not enough stormapples in skywall to repay you for this.", completion = "I... can't believe it's over. I need to stop and calm myself before my heart leaps right out of my chest." }
WordHunterWoW_QuestEN[92698] = { title = "What Is My Purpose?", description = "<You lean in close to try and hear the words coming from beneath the giant construct's armor plates.>\n\n...Function error...\n\n...Question...\n\n...What is....\n\n...Function...\n\n<These fragmented words and phrases seem to just repeat. Maybe someone nearby knows more about this construct?>", objectives = "Speak with Aamelia Windfield about the Malfunctioning Cyclone Construct.", completion = "The construct? It's been wandering around the fields for decades. Since the wind elementals left us, I think. Alvarion suspected that it used to haul harvests to market, or maybe tend to livestock back before this was an orchard. That could have been a thousand years ago though.\n\nIn the old days, the Windshapers used to maintain these constructs. We've talked about petitioning them to come and take a look at it, but it's never been a pressing concern to us. Mostly we just ignore it these days." }
WordHunterWoW_QuestEN[92699] = { title = "The Supreme Magister", description = "Now that you've arrived in Valanaar, you'll likely want to check in with the other members of the High Order here. The current Supreme Magister, Elaadrin Evengale and his people operate out of the lodge on the far southeastern part of Valanaar.\n\nYou should also take care, the High Order and Windshapers don't get along very well here. Be careful and give the Windshapers a good, wide berth. We've got enough to worry about with the cult, I won't tolerate faction violence in the streets of Valanaar.", objectives = "Find Elaadrin Evengale in Valanaar.", completion = "Hello and welcome. Rathiril sent me a magical missive about you and he mentioned you had some promise.\n\nWith you standing before me now, I can see why he suggested you seek me out. You have a vibrant arcane aura about you. Few enough of us anymore have the aptitude, let alone the will, to do what is needed to save our home. Do you have the boldness and strength needed to aid The High Order?\n\nI suppose we will see." }
WordHunterWoW_QuestEN[92700] = { title = "The Grand Skyseer", description = "Now that you've arrived in Valanaar, you'll likely want to check in with the other members of the Windshapers here. The current Grand Skyseer and her people operate out of the lodge near the center of Valanaar.\n\nYou should also be aware, the Windshapers and High Order don't get along very well in these parts. Be careful and give the High Order a good, wide berth. We've got enough to worry about with the cult, I won't tolerate faction violence in the streets of Valanaar.", objectives = "Find Ayessa Dawnsinger in Valanaar.", completion = "Elder Amberwind sent me a message about you and your exploits in Shen'dar Village. You are most welcome here, friend.\n\nYou have a strong aura, and you clearly have a resonance with the spirits. Fewer and fewer of us have the skysight of late, and Zephras needs those with the gift if we are to survive these trying times. I am glad you have found your way to me.\n\nI look forward to further making your acquaintance." }
WordHunterWoW_QuestEN[92701] = { title = "To Valanaar", description = "For now it seems the pylon and the village are safe, so I'd like you to deliver this report to the Valennia Stormfist in Valanaar, at the southeastern edge of the island. Valennia is the leader of the peacekeepers on the island and she needs to know what happened here.\n\nThe cult is expanding rapidly and the peacekeepers have avoided direct conflict until now, but those days are over. Valanaar will need to be ready for a fight.\n\nAt any rate, thank you. You'll always have friends in Shen'dar, {name}.", objectives = "Deliver Aonda's Written Report to Valennia Stormfist in Valanaar.", progress = "A letter from Aonda. What's that crafty highlander been up to?", completion = "<Valennia's expression darkens as she reads the letter.>\n\nAonda trusted you to deliver this and she speaks highly enough of you in this letter, so I'll try to trust you too. Before we speak further, I need to consult with the few peacekeepers I have left here and formulate a plan in case the cult strikes here next. Enjoy your stay in Valanaar for now.\n\nIf you are looking to keep yourself busy, there are plenty of townsfolk that can likely use the help of a strong young adventurer like yourself." }
WordHunterWoW_QuestEN[92703] = { title = "Deliver the News", description = "I guess it doesn't feel quite right to keep calling you stranger after all of this so... thank you, {name}. \n\nIf you wouldn't mind and are back out that way, please let Alvarion know what happened here. Also, tell him that once he's up on his feet he needs to bring a windshaper back here to look at that construct for us to make sure it's safe to have around our... our family.\n\n<Aamelia touches her belly gently.>\n\nHe doesn't know about this part. Let's just keep that bit between us for now.", objectives = "Speak with Alvarion Windfield in Valanaar.", completion = "<Alvarion's eyes tear up as you finish retelling the story of what happened at the orchard.>\n\nI don't know how to thank you, friend. I came to Valanaar looking for hope. A vain hope, I was almost certain. But instead I found a hero. A real hero, like the stories from before we came to Skywall. \n\nI'll never forget what you did for us, {name}. You'll always be welcome at the Windfield home." }
WordHunterWoW_QuestEN[92706] = { title = "WANTED: Bruuz", description = "Calling all anglers!\n\nA giant shark has been circling the waters near the shipping dock, attacking sailors and small boats. Dockworkers have given it the nickname \"Bruuz\". A hefty reward will be given to whoever brings me its fin!\n\n-- Gazlowe", objectives = "Bring Bruuz's Dorsal Fin to Gazlowe in Ratchet.", progress = "What can I do for ya, {race}?", completion = "Finally, somebody killed that thing! Do you know how hard it is to get a crew in the water when everyone in town's crying \"Shark!\"all the time?\n\nI might just put that monster's fin into a soup for dinner tonight, just to have the last laugh." }
WordHunterWoW_QuestEN[92707] = { title = "The Giant in the Den", description = "Wrenched from its hulking corpse, the goliath's bracers are massive. Your whole arm, up to the shoulder, can fit through one without touching the sides.\n\nYou should bring these back to Hammerfall, as a warning. Drum Fel ought to know what he's up against.", objectives = "Bring the Goliath's Wristguards to Drum Fel in Hammerfall." }
WordHunterWoW_QuestEN[92708] = { title = "A Grand Adventure", description = "The Windshapers have been hard at work trying to respond to the current crisis on Zephras Isle. We have made several surprising discoveries in our search for the missing wind spirits, and we are developing a plan of action that could help us gain the means to save the island.\n\nWe'll need strong young adventurer's like yourself for this to work however. Please, if you have a moment, let us speak on this further.", objectives = "Listen to what Ayessa Dawnsinger has to say.", completion = "So now you see? There is a world of knowledge and untapped potential outside of Skywall. This will never stop being our home, but I've come to believe that the path to our salvation lies below. We must travel to Azeroth and gain the power and means to save Zephras Isle. This is the way.\n\nWill you have the courage to join us when the time comes?" }
WordHunterWoW_QuestEN[92709] = { title = "A Grand Adventure", description = "Your highborne lineage shines as clearly in your eyes as the sky above. You are one of us, and its youth like yourself that will help us save our home. But first, let me tell you more of our mission and plans here on Zephras... and beyond.", objectives = "Listen to what Elaadrin Evengale in Valanaar has to say.", completion = "So do you now see? Rediscovering the ancient magic of our forebears is the key to unlocking the secrets of Zephras Isle and securing our future, but in order to save our home, we must rediscover what we've lost these past millennia.\n\nAzeroth is the key. The Kirin Tor will show us the way.\n\nWhile we make ready to leave, you should check in with the other members of the High Order here in Valanaar. Most of them have tasks that they could use help from one such as yourself to see completed." }
WordHunterWoW_QuestEN[92727] = { title = "The Missing Scholar", description = "Seeking knowledge is the primary mandate of the High Order, but this work has never been more dangerous than it is now on Zephras.\n\nOne of our scholars--Fillion Flamebreeze--was en route to the Shen'dar Highlands to gather data on the windborne magic that congregates in some areas there. Regrettably, he has not returned and we fear that something may have befallen him on the road.\n\nIf you can, please locate him for us. He was last seen on the road leading west from Valanaar towards Shen'dar Highlands.", objectives = "Discover what became of Fillion Flamebreeze.", completion = "<The satchel lying before you has a few specks of what appears to be dried blood on the flap. Studying the stain you also notice that the flap also has a name embroidered onto it. It reads \"Fillion Flamebreeze\".>" }
WordHunterWoW_QuestEN[92741] = { title = "Unwelcome Visitors", description = "The Shadowgale Forest is incredibly dangerous and is usually off limits to normal adventurers. In recent months there's been an explosion in the shriekling population and they've started to expand their territory outside the woods, which is a potential problem. I have an interest in the alchemical properties of shriekling talons, so a much-needed culling also presents an opportunity for scholarly gain.\n\nTravel to Shadowgale Forest and hunt the beasts. Bring me as many of their talons as you can.", objectives = "Travel to Shadowgale Forest and collect 8 Shriekling Talons for Iaadaria Bitterwind in Valanaar.", progress = "The High Order does not make it a habit to employ themselves as simple trappers and game wardens, but when performing a service such as this can lead to scholarly gain, we are happy to engage in acts of community service.", completion = "That is quite the haul of talons you've brought me. I cannot wait to dig into this!\n\nThank you for your service to the High Order, {class}." }
WordHunterWoW_QuestEN[92742] = { title = "Testing the Wells", description = "We must determine the source and nature of the poison corrupting this land. Let us begin with the groundwater under the farms in the area.\n\nGo to the Jansen Stead in the north and the Molsen Farm northwest of here, and collect samples from the wells there.", objectives = "Use the Well Water Sample Kit to collect samples from the wells at the Jansen Stead and the Molsen Farm.", progress = "Did you collect the samples?", completion = "Thank you. Let me see..." }
WordHunterWoW_QuestEN[92743] = { title = "A Conqueror's Crown", description = "As the strongest centaur clan in all the land, we deserve armaments with ferocity that matches our strength! \n\nWarug needs one most of all. A helm... no, a crown! A conqueror's crown! I heard legends of a fearsome conqueror across the seas. Go to a place they call the Badlands and seek out a crypt there. Return to me only when you have found the crown.\n\nDo this for me, and I will reveal the Magram's greatest strength.", objectives = "Maintain your reputation with the Magram, and return a Conqueror's Crown from the Badlands to Warug in Magram Village." }
WordHunterWoW_QuestEN[92744] = { title = "Murloc Gills", description = "The corruption affecting Westfall's crops may have seeped into the ocean as well. If the local fish are affected too, it could doom Stormwind to famine.\nCollect gills from the murlocs along the shoreline and bring them to me. Murlocs are quite hardy, but their physiology is extremely sensitive to contaminants. Any toxins in the seawater will be readily apparent in the gills you find.", objectives = "Alba Fairmoon wants you to collect 7 Longshore Murloc Gills along the shoreline of Westfall.", progress = "I hope the murlocs did not give you too much trouble?", completion = "I see... these gills appear to be healthy, for now. But we must not be complacent." }
WordHunterWoW_QuestEN[92745] = { title = "The State of the Mines", description = "The well samples you collected contain toxic metals! If we do not put an end to this corruption quickly, it will be decades before crops can grow in this soil again.\nThe Defias have seized the mines of Westfall and use creatures as labor to strip their resources. Disrupt them by slaying their miners in the Jangolode Mine to the north, and the Gold Coast Quarry to the west.", objectives = "Slay 4 Kobold Diggers in the Jangolode Mine and 6 Riverpaw Miners in the Gold Coast Quarry.", completion = "Well done, {name}. But I fear the source of the poison may lie somewhere else..." }
WordHunterWoW_QuestEN[92747] = { title = "Moonbrook Espionage", description = "Strange - the poison does not seem to originate from the mines you investigated.\n\nI am told the Deadmines under the town of Moonbrook are the largest, deepest mines of Westfall, but they have been abandoned since the First War. Could the Deadmines be active again?\n\nPlease travel to Moonbrook, {name}, and look for evidence of mining or industrial activity. This is the last lead we have!", objectives = "Collect 8 Suspicious Industrial Supplies from Moonbrook.", progress = "Did you find anything?", completion = "What is all this?" }
WordHunterWoW_QuestEN[92748] = { title = "Explosive Consultation", description = "The supplies you found point to a massive industrial operation somewhere in the Deadmines. There's no question that this is the source of the toxins plaguing the farmland of Westfall. We need to stop it, quickly.\n\nWhatever's down there will be difficult to destroy. Go to the Dwarven District of Stormwind, and find an engineer who can supply us with some explosives.", objectives = "Travel to the Dwarven District in Stormwind and find an engineer who can help.", completion = "Need something blown up?" }
WordHunterWoW_QuestEN[92749] = { title = "A Dynamite Plan", description = "Industrial sabotage? You've got my attention!\nWe'll start with some dynamite...", objectives = "Obtain 10 Coarse Dynamite from crafting, trading, or the auction house, then return to Sprite Jumpsprocket in the Dwarven District of Stormwind.", progress = "Show me those explosives, {name}!", completion = "This is a great start! Now to tie it all together... and add a little extra zing..." }
WordHunterWoW_QuestEN[92750] = { title = "Detonation at a Distance", description = "I assume you want a \"controlled\" explosion? Not as much fun, but a good choice if you want to keep all your limbs.\nI'm afraid I don't have a remote detonator - why don't you go check with the sneaky folks down at Stormwind Intelligence? They should be able to find us something.", objectives = "Talk to someone in Stormwind Intelligence about acquiring a remote detonator.", completion = "Hmm... Looking for something specific, are you?" }
WordHunterWoW_QuestEN[92751] = { title = "Detonation at a Distance", description = "You need something destroyed? Would this have anything to do with your activities in Moonbrook? Don't look surprised. SI:7 stays apprised of all that goes on in Stormwind's lands.\nIf you're planning to set off an explosion in the caves below Westfall, you'll want to be well outside beforehand. Take this remote detonator - it's a recent prototype from our own engineers.\nOh - and it would be best if you didn't mention my involvement to your elf friend.", objectives = "Bring the Remote Detonator Kit to Sprite Jumpsprocket in the Dwarven District of Stormwind.", completion = "Great - that's the detonator we need!" }
WordHunterWoW_QuestEN[92752] = { title = "Explosive Consultation", description = "That's it - the bomb's ready to go! Careful with that detonator, now.", objectives = "Return to Alba Fairmoon in Westfall.", completion = "I'm glad you've returned, {name}." }
WordHunterWoW_QuestEN[92753] = { title = "Destruction in Deadmines", description = "The source of the poison is likely a large metallurgical forge of some kind. Find a way into the Deadmines and locate the forge, then place the explosives.\nI will wait for you in the hills behind Moonbrook. Once you return, we can detonate the explosives. Hopefully with the forge gone, the land can begin to heal.", objectives = "Find the forge hidden in the Deadmines, and plant the Extra-Destructive Explosives nearby. Then, meet up with Alba Fairmoon at the Deadmines exit.", completion = "So you found the forge, and planted the bomb... only one thing remains to be done." }
WordHunterWoW_QuestEN[92754] = { title = "A New Need for Shadow Protection", description = "Our clanmates continue to venture further south, to and beyond the cursed Valley of Bones.\n\nDespite your standing with our clan, I do not trust you enough to share the details of their ventures. They would be boring to you anyway, outsider.\n\nWhat matters to you is our need for Greater Shadow Protection Potions, in bulk, to ensure their continued survival. Bring some to me, and I will put in a good word for you.", objectives = "Maintain your reputation with the Magram, and bring 3 Greater Shadow Protection Potions to Mirda in the Magram Village in Desolace." }
WordHunterWoW_QuestEN[92812] = { title = "Economic Warfare", description = "", objectives = "" }
WordHunterWoW_QuestEN[92818] = { title = "Big, No, MASSIVE Iron Axes", description = "WE NEED MORE WEAPONS.\n\nMORE. WEAPONS.\n\nHOW ELSE IS THE MAGRAM GOING TO SMASH PUNY GELKIS?\n\nI WANT TO SEE WHAT YOU CAN MAKE, OUTSIDER. BRING ME AXES. BIG, NO, MASSIVE ONES.\n\nHURRY UP.", objectives = "Maintain your reputation with the Magram, and bring 2 Massive Iron Axes to Grolkar in the Magram Village in Desolace." }
WordHunterWoW_QuestEN[92819] = { title = "Destruction in Deadmines", description = "We are almost finished. Use the detonator, and end this.", objectives = "Use the detonator.", completion = "I don't know what to say, {name}. To think that Stormwind would put their military ambitions over the livelihood of their people..." }
WordHunterWoW_QuestEN[92834] = { title = "Avenged Tenfold", description = "When the cult began their campaign of violence, the Peacekeepers and Windshapers responded with posturing. I saw this as foolish escalation so I advocated for peaceful dialogue. Yesterday I dispatched my friend Belathaan Brightwish to the Shrine of Akir, hoping to establish that dialogue.\n\nA box just arrived containing Belathaan's tongue, dipped in silver pigment. \n\nIts clear to me now that there is no reasoning with the cult. Kill any cultists you see, and bring me the prayer charms that they carry.", objectives = "Collect 10 Al'Aketh Windstone Charms from Al'Aketh cultists found north of Valanaar at the Gustberry Fields or Shrine of Akir.", progress = "The mark of a leader is the ability to admit when they were wrong. I don't agree with the Windshapers often, but they were right to dismiss the idea of trying to engage peacefully with the Al'Aketh. My attempt to take the high road cost a dear friend his life and is a mistake I will have to live with for the rest of my days.", completion = "The High Order prides ourselves in our pragmatism and logic, and logic dictates that the avoidance of conflict and loss of life is the most prudent option in most situations.\n\n<Elaadrin's eyes begin to glow and crackle with arcane energy.>\n\n...however, the cult mistook our prudence for weakness and they are not nearly ready to pay the cost of that error." }
WordHunterWoW_QuestEN[92840] = { title = "Catching Wind", description = "Fillion was sent to the Overlook Standing Stones with a special device used to measure and study the elemental energy there.\n\nTake this--an Index Esoteria--and use it to extract data from the massive windstone formations that form there. Be on your guard however, as the Windshapers are likely to be jealously guarding this site now.\n\nShould any attempt to obstruct you, well... do what you need to do. I have no more patience for their interference.", objectives = "Take the Index Esoteria to the Overlook Standing Stones in Shen'dar Highlands and use it on the Windstone Formations in the area to gather data.", progress = "It's often difficult for me to establish a distinction between the Windshapers and the Al'Aketh, save that one is more overtly violent than the other. Equally slavish to their misplaced beliefs, they are both equally dangerous if left to their own devices.\n\nThey see our desire to better understand this realm and its magic as a desecration of their traditions. Their small-mindedness is why our mission is so important. If not us, who will have the courage to save Zephras?", completion = "It would not have been my preference to spill Windshaper blood but the blame for this pointless conflict rests solely on their shoulders. We sought to peacefully gather information, and they responded with violence.\n\nUnfortunately, word has spread and the Windshapers are already calling it a 'massacre'. They wouldn't dare to retaliate here in Valanaar, but they will certainly not forget.\n\n{name}, you have been of tremendous aid to the High Order. Thank you." }
WordHunterWoW_QuestEN[92849] = { title = "The Missing Scholar", description = "<Judging by what you've just found, it's very likely that Fillion befell some misfortune here. He may still be nearby, and he might be in need of aid. You notice a cave just to the north of your current location. You should continue searching for him there.>", objectives = "Keep searching for Fillion Flamebreeze.", completion = "Th... thank you, stranger. I was walking down the road on my way back to Valanaar when a looming shadow appeared overhead. I turned to look and saw a massive, terrible beast bearing down at me from the sky. I tried to run, but I was hit hard and the world went black.\n\nI think its fair to say that if you hadn't come along, I'd have been dinner for that beast and its young." }
WordHunterWoW_QuestEN[92850] = { title = "The Missing Scholar", description = "I am feeling much better already. I have some skill with the arcane arts and we are but a short distance from Valanaar. I can make it on my own. More important than my safety however is how close to Valanaar these shrieklings have nested and the danger they pose. If you would be so kind, please head back inside and take the head of that beast!\n\nAfter it's done, you'll find me back in Valanaar. I need to report to the Supreme Magister what occurred here and the status of my mission.", objectives = "Slay the Shriekling Matriarch in the Shriekling Den then return its head to Fillion Flamebreeze in Valanaar.", progress = "That fool Fillion...", completion = "Well, I confess that I am intensely relieved that Fillion has returned to us. He never was good at minding his surroundings. Always too busy lost in thought, or with his nose in a book.\n\nThank you, {class}." }
WordHunterWoW_QuestEN[92860] = { title = "In Service of Zephras", description = "The High Order has done our best to avoid direct conflict with the cult, but that is clearly no longer an option. Their hostility has been clearly demonstrated, and now there's rumors of larger-scale cult movements around the island. They are clearly gearing up for something and whatever it is can't be good for the people of Zephras.\n\nReport to Valennia Stormfist and inform her that the High Order offers our full support in Valanaar's efforts against the Al'Aketh, should the need arise.", objectives = "Report to Valennia Stormfist and let her know that High Order is with them in their fight against the Al'Aketh.", completion = "I am sorry to hear about Belathaan. He was actually my cousin and he was a good mage and servant of Zephras. We will avenge him.\n\nYou seem eager to lend aid immediately. Come, let's speak further on the current situation." }
WordHunterWoW_QuestEN[92871] = { title = "In Service of Zephras", description = "Valennia Stormfist and her peacekeepers have ever been the protectors of Zephras, and we've done our best to lend aid where we can. There's rumors of larger-scale cult movements around the island, and they are clearly gearing up for something.\n\nReport to Valennia and reiterate to her that the Windshapers offer their full support in Valanaar's efforts against the Al'Aketh, should the need arise.", objectives = "Report to Valennia Stormfist and let her know that the Windshapers are with them in their fight against the Al'Aketh.", completion = "You seem eager to lend aid immediately. Come, let's speak further on the current situation." }
WordHunterWoW_QuestEN[92880] = { title = "Return to Valanaar", description = "I suspect it will take a bit of time for us to mop up what's left of the attackers, but our chances are far better now. Head back to Valanaar and let them know that we are stable here now.\n\nI can't thank you enough for your help. We'd be in much worse shape without you. I asked for reinforcements and it seems that I got a burgeoning hero instead. I'll take that.\n\nMay the four winds bless you, {class}.", objectives = "Bring Yorna's Report to Valennia Stormfist in Valanaar.", completion = "<Valennia looks visibly relieved as you tell her about the status of the eastern watchtower.>\n\nThank the winds." }
WordHunterWoW_QuestEN[92881] = { title = "The High Elder's Request", description = "The attack on both the western and eastern watchtowers are not a coincidence. Based on what you told us about what occurred at the western watchtower with that skypriest, our best guess is that the cult is trying to do something to the anchor pylons.\n\nPlease speak with High Elder Shadowsong. He will tell you about a lead that could prove to be promising.", objectives = "Speak with Talaanis Shadowsong in Valanaar.", completion = "I have a small matter that requires just the kind of assistance that an adventurer like yourself can provide." }
WordHunterWoW_QuestEN[92909] = { title = "Harvesting the Harvesters", description = "Oh no... I'm in for it now!\n\nI heard about the harvesters terrorizing the fields of Westfall, so I traveled all the way from Ironforge to see if I could recalibrate them. But they're far more aggressive than my calculations anticipated, and they chased me into this stable!\n\nIf I had some isosprings and gyrostabilizers from the harvesters, I could build a device to cover my escape. Could you gather the parts for me?", objectives = "Ozwin Ironsprocket at Saldean's Farm wants you to bring him 14 Golem Isosprings and 5 Harvester Gyrostabilizers.", progress = "It's a mess out there, {name}! Did you collect the parts I need?", completion = "Thanks a bunch! I'll get to work on an escape plan. In the meantime, take this!" }
WordHunterWoW_QuestEN[92910] = { title = "Harvesting the Harvesters", description = "The part you managed to salvage from the harvester appears mostly intact. Someone interested in harvest golems may want to see it.", objectives = "Bring the Precessive Autocognition Assembly to Ozwin Ironsprocket at Saldean's Farm.", completion = "What's this?" }
WordHunterWoW_QuestEN[92911] = { title = "Harvesting the Harvesters", description = "I see... this gives me some insight into what makes those monsters tick. I have an idea how we could override their systems, at least momentarily.\n\nI'll continue tinkering with the assembly you brought me. In the meantime, could you scrounge up some parts for the device?", objectives = "Ozwin Ironsprocket at Saldean's Farm wants you to bring him 8 Golem Isosprings, 4 Copper Modulators, and a Crude Scope.", progress = "How's the project coming, Raton?", completion = "Here it is, Raton! Should work great. Go give it a try!\n\n...Me? No, I'll stay here. It's starting to feel like home, anyway." }
WordHunterWoW_QuestEN[92947] = { title = "Making Our Move", description = "Everyone is here, good. I've just sent a few of my best fighters in through the front of the shrine to cause a bit of trouble and serve as a distraction, while I lead the Windshapers and High Order in from the flank.\n\nIf all goes well, we should be able to punch through quickly and take out the High Priestess. As for you, get in there and start cracking skulls. Meet my second, Hyusaa Quickbreeze, near the steps to the shrine after you've caused some trouble.\n\nWinds guide you, {class}.", objectives = "Slay 7 Al'Aketh Guardians, 7 Al'Aketh Spiritcallers, and 7 Al'Aketh Blademasters, then report to Hyusaa Quickbreeze at the Shrine of Akir.", completion = "We fought hard to get this far but it isn't over yet." }
WordHunterWoW_QuestEN[93036] = { title = "Infiltrating the Cult", description = "You may or may not be aware of this, but Sania Silverstream over there is a \"missionary\" for the Al'Aketh. They like to play at being a normal religious order and send non-threatening emissaries around to recruit. We've tolerated Sania so far to avoid direct conflict with the cult, but its obvious the illusion of peace won't last much longer.\n\nYou are new here and unknown to most, so I'd like to see if you can use Sania to get close to the cult and find out what their plans are for the village.", objectives = "Speak with Sania Silverstream in Shen'dar Village.", completion = "Greetings child, my name is Sania Silverstream and I am a junior priestess in the Order of the Al'Aketh. Do you wish to learn more of our sovereign, the Windlord Al'Akir?\n\nThere is always room at the Windlord's table for the righteous and the repentant." }
WordHunterWoW_QuestEN[93065] = { title = "Prepare for Battle", description = "The Peacekeepers are mobilizing and we are all gearing up to head out. Make whatever preparations you need to make and meet us at the eastern road leading north out of town. We'll have one final check-in with everyone before we move out.", objectives = "Speak with Valennia Stormfist in the Gustberry Lowlands.", completion = "We are as ready as we'll ever be." }
WordHunterWoW_QuestEN[93066] = { title = "Bristleback Retreat", description = "On the other side of the valley, we have established a small foothold to prepare to march into the forest nearby. Before you head straight there, I want you to deal with a recent Bristleback intrusion along the way. They seem to have arrived right around the same time we did, but managed to secure an artifact from the nearby temple that has kept us at bay.\n\nThis task is simple. Look for the thorns and the pigs. Kill a bunch, indiscriminately. Then report to Hagiak at the camp I mentioned.", objectives = "Maintain your reputation with the Magram, and slay quilboar at Bristleback Retreat. Then report to Hagiak at the Magram Front on the other side of Valley of Bones in Desolace." }
WordHunterWoW_QuestEN[93072] = { title = "Long-Term Solutions", description = "There is a second centaur village out here, to the southwest. That one belongs to the Gelkis. You expect me to send you over just to spill some blood, right? Good. That had best be your first thought, else I would cast doubt on your allegiance to the Magram!\n\nWhat are you waiting for? Go! Kill!", objectives = "Maintain your reputation with the Magram clan and slay 2 Outcast Scouts, 6 Outcast Marauders, and 8 Outcast Necromancers then return to Hagiak at the Magram Front." }
WordHunterWoW_QuestEN[93089] = { title = "What Comes Next", description = "Please extend my thanks to Elaadrin for all that the High Order and your new friends from this \"Kirin Tor\" have done for Zephras Isle. I'm aware of the High Order's plans to leave the island, and your order has my blessing and well-wishes in this expedition.\n\nI can only hope that whatever arcane solution the High Order finds can truly provide us with the stability we've lacked these past years. If you plan to go with them... well, his mission will be all the stronger for it.\n\nWinds be with you, {name}.", objectives = "Speak with Elaadrin Evengale when you are prepared to leave Zephras Isle.", completion = "It gladdens me to hear that we have High Elder Shadowsong's blessing for our expedition. Now that the cult has been defeated and preparations have been made, I think it's finally time.\n\nAnsirem has worked diligently to help us get stable skycutter transport going between the city of Dalaran and Zephras Isle. We've done as much testing as we can, and the time has come for vanguard to depart." }
WordHunterWoW_QuestEN[93090] = { title = "What Comes Next", description = "Please extend my thanks to Ayessa for all that the Windshapers and your new friends from this \"Earthen Ring\" have done for Zephras Isle. I'm aware of the plan to take the Windshapers shamans and leave the island, and your order has my blessing and well-wishes in this expedition.\n\nI can only hope that whatever solution the Windshapers find can truly provide us with the stability we've lacked these past years.\n\nWinds be with you, {name}.", objectives = "Speak with Ayessa Dawnsinger when you are prepared to leave Zephras Isle.", completion = "I'm pleased to hear that we have High Elder Shadowsong's blessing for our expedition. Now that the cult has been defeated and preparations have been made, I think it's finally time.\n\nMuln has worked diligently to help us get stable skycutter transport going between Zephras Isle and a place called Mulgore, where the Earthen Ring make their home. We've been doing test voyages and some of our people are already waiting on the other side." }
WordHunterWoW_QuestEN[93129] = { title = "Threat of Starvation", description = "Since you seem overly eager to help our clan, I am sure you would be willing to fetch some supplies while you are over in the Outcast Hideaway.\n\nFelling our foes should be enough motivation for a Magram, but I see no reason why we could not profit from the endeavor, too.\n\nWhen we have the exiles dealt with, we can secure this place for the Magram and raise an army to bring the other clans to their knees!", objectives = "Maintain your reputation with the Magram, and bring 6 Stolen Supplies back to Hagiak at the Magram Front." }
WordHunterWoW_QuestEN[93159] = { title = "The Strange Hermit", description = "Uh, um... h-hello, I mean to say, hi! Greetings, even! I'm sorry... its um, been so long since I've actually spoken to another person. I'm afraid I'm a bit rusty at this.\n\n<The strange hooded figure shifts uncomfortably before you.>\n\nSo er, um... how is your day going?", objectives = "Speak with the Strange Hermit in the Shadowgale Forest and learn more about him.", progress = "So that's the story...", completion = "...that's about all I have to say about it. I was--um--somewhere else before I was here. Now I'm here and I have my friends, and my things. T-things I built, I mean. That's about all I need. I think that's all I need, anyway.\n\nI have to say though, it is nice to talk to someone who will talk back. The forest spirits try, but they just end up singing at me. That's nice in its own way, but not exactly s-stimulating conversation." }
WordHunterWoW_QuestEN[93160] = { title = "The Forest's Bounty", description = "I do appreciate you stopping by to talk with me! I-If you do want to help out, I could use a bit of help gathering up acorns from the forest floor. I've gathered most of the ones close by but there sure are a lot of raptor-bird things in the forest. It's dangerous out there and I'd rather not become a giant bird's lunch!\n\nSo if you want, you could maybe gather them for me? I'll make us something tasty if you do!", objectives = "Gather 8 Shadowgale Acorns in Shadowgale Forest.", progress = "Mmm, I think you are going to like what I can cook up with these acorns!", completion = "Thank you, stranger! You'll find that these are delicious once roasted! \n\nPlease excuse me, it won't take me long to whip this up." }
WordHunterWoW_QuestEN[93165] = { title = "Mercy Falls on Deaf Ears", description = "The Al'Aketh have visited great tragedy upon our enclave, and blood must be repaid with blood.\n\nI have an offer for you, stranger. Should you find conflict with these accursed cultists, bring me the ears of those you kill. I will reward you for each that you return with in both coin and, in time, access to the Nightclaw's secrets should you prove yourself to be a true friend.", objectives = "Collect 10 Al'Aketh Cultist's Ears from the Al'Aketh cultists in Shadowgale Forest, the Shine of Akir, or Gustberry Lowlands.", progress = "I will not rest until my fangs have gone through the throat of every single cultist on this isle.", completion = "Excellent work. Only good things can happen by eliminating the cult. Hopefully this sends a message that the Nightclaw are not to be trifled with and that our resentments run deep.\n\nI suspect you have your work cut out for yourself, taking on the cult. If you gather more ears bring them here." }
WordHunterWoW_QuestEN[93172] = { title = "Free the Hollows", description = "Most of the elves on this island seem to think that these woods are haunted, and they aren't wrong.\n\nAt the old ruins to the northeast, a strange type of ghost-like spirits gather. Some nights, you can almost hear them \"singing\". It's not like any song I've heard before, but its definitely a song and its... just so sad.\n\nI'm not sure why, but I think something terrible happened there at some point, and the spirits are trapped there somehow. If you are feeling brave, maybe you can help set them free?", objectives = "Destroy 10 Wind Hollows in Shadowgale Forest.", progress = "We can only hope that those poor spirits are able to find peace after being freed from this place.", completion = "Thank you, stranger." }
WordHunterWoW_QuestEN[93173] = { title = "(UNUSED) The Rusty Gadget", description = "<As the roiling currents that hold the Wind Hollow together begin to dissipate, A small metal device tumbles to the ground at your feet. It appears to be some sort of mechanical gadget. The Strange Hermit mentioned he was still missing some equipment. He might be interested in this.>", objectives = "Return the Rusty Gadget to The Strange Hermit in Shadowgale Forest" }
WordHunterWoW_QuestEN[93176] = { title = "My Little Friends", description = "Admiring my little menagerie, are you? They are my un-life's work. I've spent countless hours studying them: their anatomy, their diets, even their social rituals.\n\nDo you wish to join me in the hobby? Here, take this package. The notes and materials contained within should get you started. If you lose it, you'll have to purchase another one from me for a small fee.", objectives = "Use the items contained in the Entomology Starter Kit to find and catch an Arbor Tarantula, Hay Weevil Specimen, and a Flesh Picker." }
WordHunterWoW_QuestEN[93224] = { title = "Carved Centaur Totems", description = "It likely comes as no surprise to you that both of the centaur clans are hesitant to accept aid from anyone outside of their clan. This is especially true for folks like you and me - you know, non-centaurs.\n\nOne thing we all have in common is an understanding that money is power, and we have learned that the local centaur barter with carved wood. If you bring me a few samples of their designs, I can put in a rush order for similar etchings. Perhaps we can buy ourselves an advantage.", objectives = "Acquire 5 Carved Centaur Totems by slaying centaur of any clan throughout Desolace, then return them to Captain Pentigast at Nijel's Point." }
WordHunterWoW_QuestEN[93225] = { title = "Carved Centaur Totems", description = "I have noticed that centaur from different clans sometimes gather away from settlements and engage in trade. I have observed this across numerous nights and seemingly with every clan; most importantly I have seen the currency they use: carved totems.\n\nI believe we can turn the tides in our favor with either the Gelkis or the Magram if we deliver a heavy bundle of totems right to them. I have already begun carving some, but I doubt they will be easily fooled without a few authentic ones.", objectives = "Acquire 5 Carved Centaur Totems by slaying centaur of any clan throughout Desolace, then return them to Gurda Wildmane at Ghost Walker Post." }
WordHunterWoW_QuestEN[93226] = { title = "Buying Friendship: Magram", description = "Siding with the Magram would be my choice. There is no question that they are the dominant clan in the present day, regardless of their previous struggles. I have heard reports that they are brutally hostile against the Gelkis.\n\nI sympathize with both warring clans and especially the Gelkis, but this is their war; not ours. We ought to side with the faction that poses the least risk to our cause. I believe that to be the Magram.\n\nBring this to their quartermaster in Magram Village to the southeast.", objectives = "Bring the Totem Tote to the Magram Quartermaster at Magram Village in the Desolace to significantly increase your reputation with that clan. You must be of at least Neutral standing with the Magram Clan Centaur." }
WordHunterWoW_QuestEN[93227] = { title = "Buying Friendship: Gelkis", description = "At first glance, I would wager that the Gelkis are struggling. Their numbers are far fewer than the Magram, and I rarely hear of them stomping around from our scouts.\n\nNonetheless, they are one of the dominant clans in the Desolace and survive to this day. They must be doing something right.\n\nIf you want to make peace with the Gelkis, take this tote of totems with you to Gelkis Village far to the southwest. Primitive as they may be, they are likely to have a treasurer of some kind.", objectives = "Bring the Totem Tote to the Gelkis Quartermaster at Gelkis Village in the Desolace to significantly increase your reputation with that clan. You must be of at least Neutral standing with the Gelkis Clan Centaur." }
WordHunterWoW_QuestEN[93317] = { title = "Crab Season", description = "Are you familiar with Windsong Crawlers? You see, these crabs are native only to Windsong Lake here on Zephras, and they are only able to be harvested a few weeks of the year.\n\nWith all of the cult activity of late, I've not been able to get out to the lake to harvest them, and our window is rapidly closing. I'd be appreciative if you could go and gather some for me. They can generally be found along the shorelines around the lake and in rivers.\n\nDo be careful though, they are meaner than they look!", objectives = "Collect 6 pieces of Windsong Crawler Meat.", progress = "Windsong Crawler meat is common enough here but it was something of a delicacy on the islands of Anvilas and Siroccas. Was a time, back when the skystreams were open that the locals would mob me for the stuff when I'd make the trip to Shen'dramar or New Eldre'naar.\n\nNot been able to visit those places in... well... a long time.", completion = "Winds bless me this meat looks fantastic! \n\nThank you so much, {class}." }
WordHunterWoW_QuestEN[93318] = { title = "WANTED: Vulgara the Insatiable", description = "By order of Constable Aonda of the Peacekeepers, a bounty is hereby placed upon the scourge of the highlands, Vulgara the Insatiable. Last spotted on a hilltop rise just southwest of Shen'dar Village, the winged vuldren terror is highly dangerous and should be approached with caution.\n\nDeliver the beast's head to Danarii Bellowveil to receive your reward.", objectives = "Kill Vulgara the Insatiable in the Shen'dar Highlands and bring her head to Danarii Bellowveil.", progress = "I'll need the creature's head as proof of the deed.", completion = "If we didn't have enough on our plates between the cult and the highlands bandits, we don't need a giant vuldren terrorizing our citizens as well. You've done a great thing here today. As promised, here is your reward." }
WordHunterWoW_QuestEN[93319] = { title = "Pilfered Windstones", description = "We are relying on windstones more and more for day to day living here on Zephras so we try and maintain a cache of them in reserve for emergencies. Lately I've noticed some go missing from our stores.\n\nWe've found windstones on bandits we've captured recently, and I suspect they are behind our shortages.\n\nIf you find yourself near the bandit cave to the north, mind knocking a few heads together and reclaiming some of our pilfered windstones for me?", objectives = "Collect 10 Pilfered Windstones from the Highlands Bandits in the Shen'dar Highlands.", progress = "These sneakthieves have likely been breaking into our supplies for months. I tried to convince Aonda to put a raid together to clear out that bandit cave for good, but she didn't want to pull the few peacekeepers we have away from the village. \n\nWith the cultists at Falaath Village to the south growing in numbers, I suppose I can't fault her for that.", completion = "Thanks {class}. This should help us get by for now. If we can't get the supply routes squared away soon though, a few stolen windstones will be the least of our worries." }
WordHunterWoW_QuestEN[93320] = { title = "Tower Defense", description = "I've just received word that the cult is attacking the pylon watchtower just outside of town! I've sent the few extra peacekeepers we have here to try and break through the enemy back line to relieve the defenders, but any additional help could mean the difference between our people there living or dying.\n\nPlease leave immediately for the east watchtower and provide whatever aid you can.\n\nMy lieutenant Yorana Windyreed led the relief force. If she still lives she can tell you how best to help.", objectives = "Report to Yorana Windyreed at the eastern watchtower in the Gustberry Lowlands.", completion = "We are holding them off for now, but they have greater numbers and our fighters are starting to get tired. We need to do something to break the stalemate, and do it fast." }
WordHunterWoW_QuestEN[93429] = { title = "Blood of My Blood", description = "Although they are our kin, the Lost Ones of Fallow Sanctuary have become beings of pure violence and hatred.\n\nThere can be no redemption or salvation for them. They are doomed to wander this swamp as mindless, hateful creatures for all their lives.\n\nTheir suffering must end. Someone must put them out of their misery. A grisly task, I know, but would you do it to protect those of us who remain?", objectives = "Slay 10 Lost Ones in the Fallow Sanctuary." }
WordHunterWoW_QuestEN[93430] = { title = "Taking the Bait Back", description = "Now they've really done it! As if those wretches weren't already enough to deal with, one of them has stolen my lucky lure!\n\nI was just out fishing this morning, when one came up out of the muck, cut my line, and ran off with it. The thief is almost certainly one of the Lost Ones' own fishermen, hoping to use the lure themselves.\n\nWell, our supply of fish depends on that lure, so I need it back. The Lost Ones fish along the banks east of here. Find that thief, {race}!", objectives = "Find the Lost One Fisherman who stole Pelluk's lure, and take it back." }
WordHunterWoW_QuestEN[93459] = { title = "More Al'Aketh Ears", description = "The Al'Aketh cult normally gives this forest a wide berth, fearing the rumors that it is haunted... rumors we are happy to maintain. The Druids of my order wish only to live quiet, peaceful lives here in Shadowgale and they threaten that. \n\nMany among us are afraid.\n\nI come with an offer. Fight the cultists for us, and bring us the ears of those you kill. We will reward you for each that you return with in both coin and, in time, access to our secrets should you prove yourself to be a true friend.", objectives = "Collect 10 Al'Aketh Cultist's Ears from the Al'Aketh in Shadowgale Forest, the Shine of Akir, or Gustberry Lowlands and return them to Vayn Moonclaw in Shadowgale Forest.", progress = "<Vayn nods at you.>", completion = "As promised, here is your reward." }
WordHunterWoW_QuestEN[93461] = { title = "Welcome to Shen'dar Village", description = "You've got that \"High Order\" look to you. Those with Highborne ancestry always seem to have a slight twinkle in their eyes that gives it away. Before I properly put you to work around here, you should check in with our resident High Order elder Rathiril Sunlance. You can find him here in the main lodge, just around the corner from me.\n\nOh, and check in with Coriella Calmbreeze as well, she runs the local inn and can provide lodging and supplies, should you need them.", objectives = "Speak with Rathiril Sunlance and Coriella Calmbreeze in Shen'dar Village.", completion = "Checked in with Rathiril then? Great. Lots of tension between the High Order and the Windshapers these days, but they keep things civil here in Shen'dar. Well, at least in the village anyway. What happens out in the wilds stays in the wilds.\n\nNow that that's done, you look like someone who might be looking for something to do with their hands. I've got a few things that need doing, if you are game for a bit of work?" }
WordHunterWoW_QuestEN[93464] = { title = "The Visiting Mage", description = "Allow me to admit something, {name}. While draenethyst is sacred to us, and keeps us sane, none here fully understand it.\n\nI recall a mage who once came to the Harborage, from Desolace. A human by the name of Azore. He feared the power of the draenethyst; said it shouldn't fall into the wrong hands. \n\nAt the time, we drove him away to protect what was ours. Lately, however, I find myself wondering what exactly he knew.\n\nI ask that you find this mage, {race}. His knowledge could be of immense value to us.", objectives = "Find the mage in Desolace who knows about the power of draenethyst." }
WordHunterWoW_QuestEN[93465] = { title = "Notes on Draenethyst", description = "I suppose it would be more accurate to say I know someone who knows a thing or two about draenethyst.\n\nYou see, the warlocks of the Burning Blade have been studying it. It is a substance from beyond the dark portal, so it follows that those involved with darker arts might wish to harness it to their own ends. We cannot allow this, obviously.\n\nThe specific warlock you seek is named Gimashi. She can be found atop her tower, which is in a ravine to the southeast. Her notes will have the answers you seek.", objectives = "Take Gimashi's notes on Draenethyst, and bring them back to Azore Aldamort." }
WordHunterWoW_QuestEN[93552] = { title = "Harvesting Windstones", description = "Windstones are a critical resource on Zephras Isle as they contain the raw, concentrated energy of the winds themselves. The wind elementals who used to live here on zephras with us vanished several centuries ago, and since then, the magic that sustains this island is slowly fading. Not without limitations, the Windstones are still a reliable energy source, and are incredibly valuable to us.\n\nYou'll find raw Windstones scattered around the grove, think you can help me harvest them?", objectives = "Collect 15 Windstone Clusters from Raw Windstones in Thendal Grove.", progress = "Hello there, {class}.", completion = "Thank you very much for these. As elves we all have a deep connection to magic and these windstones are becoming more and more precious as the magic imbued into this island by the great anchor pylons continues to fade. \n\nwindstones aren't the only beneficial thing you can harvest from the land. Please, take one of these manuals." }
WordHunterWoW_QuestEN[93585] = { title = "This Light of Mine", description = "Oh thank goodness, someone civilized!\n\nI came here on behalf of the Church of the Holy Light to make contact with the draenei of the Harborage. The Alliance has no foothold here, you see, and a bit of diplomacy with the locals may help us in that regard. The Light welcomes all into its fold, after all!\n\nHowever, the road past this bridge is crawling with the draenei's more savage kin. If I am to make it to the Harborage safely, I will need protection. Would you aid me, {class}?", objectives = "Escort Father Tuttle to The Harborage." }
WordHunterWoW_QuestEN[93663] = { title = "Lost in Transit", description = "The draenei of the Harborage are skilled fishermen, and willing to trawl more dangerous waters than I. We occasionally trade. They give us some of their catch, and I offer some of our extra supplies.\n\nI'd sent a goblin courier to deliver my latest shipment, but he never returned. A crocolisk likely made a meal of him.\n\nMore importantly, my business reputation is at stake. That shipment must be found, and delivered to the harborage. Please, find it if you can. Check near the waters along the road.", objectives = "Find the missing courier, and ensure Dar's shipment is delivered to the Harborage." }
WordHunterWoW_QuestEN[93680] = { title = "Key to the City", description = "The Alliance had an army of mages known as the Kirin Tor. While they were powerful, the demonic Burning Legion proved to be even more so. In one fell swoop, the arch demon Archimonde flattened their city like it was a child's plaything. Those who remained were reduced to merely dispossessed vagabonds.\n\nThat is, until they rebuilt Dalaran. And on the Dark Lady's very doorstep, no less!\n\nWhile in their camps, search for something that can get us into the city unnoticed. I must know more.", objectives = "Acquire the Dalaran Sewer Key for Magus Wordeen Voidglare in Tarren Mill." }
WordHunterWoW_QuestEN[93735] = { title = "The Broken Construct", description = "Historically, the Windshapers have seen to the tending of the magical instruments and devices that were gifted to us by the spirits of the wind. This includes the myriad of magical constructs around the island. Since the spirits left us, only a scant few of these are still functional.\n\nOne of the few remaining working constructs in Valanaar has become damaged. One of our artisans was dispatched to help, but he may be in need of aid. Travel to the west end of the city and offer any assistance you can.", objectives = "Find Riaani Nightwind on the west side of Valanaar.", completion = "<Riaani's face is buried under the heaving armor plates of the construct, attempting to work on the mechanisms underneath. He does not notice your presence at all.>\n\nStorms curse where is the core?! Who thought it would be a good idea to remove the Gyrozephyr as well? It's a miracle this construct's winds haven't dissipated entirely by now!" }
WordHunterWoW_QuestEN[93736] = { title = "Unwelcome Spirits", description = "The paramount concern of the Windshapers is to better understand why the spirits left us, and what we may be able to do to bring them back. One curious fixture of Shadowgale Forest to the north is the presence of a curious form of wind sprite that some call \"hollows\". We know little of them and why they are there, but we do know that they first started to appear after the spirits of the wind left us.\n\nI need you to go there and disperse them. Gather the remains and bring them back here.", objectives = "Gather 10 Wind Hollow Essences from Wind Hollows in the Shadowgale Forest.", progress = "Shadowgale Forest is a dangerous place. Some even say its haunted. I'm quite sure that I don't believe that, but I do know that its not for the faint hearted, or the unprepared.", completion = "Handling these essences fills me with a sense of... deep disquiet. I can almost feel a malevolent, regretful aura emanating from them. It's enough to make me faint.\n\n<Endaria shudders slightly.>\n\nI do not look forward to studying these further." }
WordHunterWoW_QuestEN[93737] = { title = "The Broken Construct", description = "Oh, hello. Ayessa sent you to assist me? Very well then. \n\nNot sure what an obvious novice like yourself can do, but if you give me a moment to pull my head out of this construct's innards I might have a few ideas of things you can do to help.", objectives = "Speak with Rianni Nightwind and list to what he has to say.", progress = "I can't imagine why anyone would want to steal these components from this construct. Other than the gyrozephyr these components have almost no practical application. Even the gyro would be nigh-useless outside of its intended purpose.", completion = "Thank you for scavenging these materials. I imagine that some of this wasn't terribly easy to get. \n\nWith these parts I can get the construct up and running again. From there we can just hope that its memory is intact and it can tell us who took its components." }
WordHunterWoW_QuestEN[93738] = { title = "The Broken Construct", description = "Brightwish, eh? So the High Order wanted to remove these components for some reason. But why though?\n\nThe High Order has always been meddlesome, constantly wanting to experiment with the wind spirits' magic. They are too bold by a mile, and we've strictly forbade them from meddling with knowledge under Windshaper purview, but lately they've been testing our patience. \n\nI think you should report what you've learned back to Ayessa Dawnsinger. She can instruct you further on what to do.", objectives = "Report back to Ayessa Dawnsinger in Valanaar.", completion = "Very interesting, so it was the High Order that was responsible for the construct breaking down?\n\nI know Belathaan. He's Valennia Stormfist's cousin and his mother was actually a Windshaper. It's disappointing that he was involved in this.\n\nI need to reflect on this for a moment." }
WordHunterWoW_QuestEN[93739] = { title = "Exploring the Horde", description = "Azeroth is a large world, and the territory of the Horde is vast. The Undercity, Orgrimmar, and Thunder Bluff all have very unique people and culture.\n\nIf you are to be a guest of the horde here on Azeroth, it would do you good to visit each of our capital cities in turn. Speak with my advisor Nazgrel for directions.", objectives = "Speak with Nazgrel in Grommash Hold to receive further instructions. Use the instructions received to locate and speak with Vol'jin, Cairne Bloodhoof, and Lady Sylvanas Windrunner.", completion = "So you have returned. I hope that you learned much in your journey.\n\nIt is my understanding that your people are still establishing themselves in Mulgore. While you wait for them, I'd encourage you to explore the territory around Orgrimmar. The Barrens in particular is always in need of eager adventurers like yourself." }
WordHunterWoW_QuestEN[93740] = { title = "Blood for Blood", description = "A number of our Windshaper novices were found dead in the Highlands this morning. We can't be certain but there is a strong chance that the Al'Aketh are responsible. Windshapers trade blood for blood, every time.\n\nHead north and kill any Al'Aketh you encounter. Bring me their windstone prayer charms as proof of the deed. We do not forgive and we do not forget.", objectives = "Collect 10 Al'Aketh Windstone Charms from the corpses of Al'Aketh cultists in the Gustberry Lowlands.", progress = "The Al'Aketh have engaged in their bloody zealotry for far too long. This is only the start of the reckoning they face.", completion = "<Ayessa looks shaken and distant as you hand her the windstone charms.>\n\nDon't mind me, {name}. Today has merely been... a trying day. Thank you for your service to the windshapers thus far." }
WordHunterWoW_QuestEN[93746] = { title = "A Firm Response", description = "The High Order has been warned of the consequences of meddling with the Windshaper's affairs. I think we need to make an example out of Belathaan and send him back to the High Order with a few bruises and a healthy respect for the boundaries we set.\n\nBelathaan was seen leaving town, traveling north towards the Shrine of Akir. I don't know why he was going there, but confronting him alone on the road is the safest option. Find him, and put a bit of fear into his heart.", objectives = "Confront Belthaan Brightwish along the road to the Shrine of Akir.", completion = "Wait--what?! Belathaan... is dead? \n\n<Ayessa listens as you give your account of what occurred.> \n\nThe High Order was meeting with the Al'Aketh to discuss peace? There is no peace with the cult, they are murderous zealots. What was Elaadrin thinking sending Belathaan to treat with them alone?\n\nPay this no mind, {name}. You are not at fault for this. The arrogance of the High Order is to blame, yet again. You were merely in the right place at the wrong time." }
WordHunterWoW_QuestEN[93791] = { title = "Speak with Belann", description = "{name}, it is clear your skill with magic is growing and I believe it is time for you to partake in one of the High Order's oldest traditions for young and aspiring mages. It is time for you to craft a spell focus of your own.\n\nSeek out Belann Windwood in Valanaar. He has been crafting staves and wands for the High Order for over a century, so you will be in good hands.", objectives = "Speak with Belann Windwood in Valanaar.", completion = "Ah, you must be {name}? It is heartening to see young mages eager to learn our ways and history. Come, I will explain the next steps to crafting your spell focus." }
WordHunterWoW_QuestEN[93797] = { title = "Boughs in the Wind", description = "It is a time-honored tradition for young mages to create their own spell focus when they have shown a certain degree of magical proficiency. This is typically done by gathering a fallen branch from our oldest trees, as they have some lingering traces of elemental wind.\n\nI have found the most ideal ones to be near the wind shrine, just south of Falaath Village. Go and bring me back a large branch and I will teach you about the traditions as we create your spell focus.", objectives = "Bring a Wind-Infused Bough to Belann Windwood in Valanaar.", progress = "Every year that passes in Zephras sees fewer and fewer of those who are gifted with a talent for magic. \n\nI am glad to see young mages such as yourself participate in our oldest traditions to help keep our history and culture alive and well.", completion = "Thank you, {name}. I can indeed feel the elemental energies in this bough waiting to be harnessed by those that have the gift to do so. This will make an excellent spell focus.\n\nDid this branch sing to you, perhaps? It has often been the case that the branch picks the {class}, and not the other way around." }
WordHunterWoW_QuestEN[93835] = { title = "Confront Lorthuna", description = "Lorthuna fled up to the spires above using some sort of portal. Ayessa and Elaadrin went in after her. That was just a few moments ago.\n\nI'm afraid I took one too many hits and this is where I stay. Go through the portal, find Elaadrin and help them stop Lorthuna.\n\nUnless that help that Elaadrin and Ayessa said they sent for arrives soon, you are on your own from here. Good luck, {class}.", objectives = "Take the portal to the Rohashi Spires overhead and join Elaadrin Evengale and Ayessa Dawnsinger in their confrontation with High Priestess Lorthuna.", completion = "I sent a few of our remaining mages to ensure that Valennia and her forces were able to escape as well. She should be resting at High Elder Shadowsong's residence now.\n\nAnsirem had to return to Azeroth, but he and I discussed the next steps for the High Order before he departed. We survived the day, but Zephras is dangerously vulnerable now and we must make plans for what is to come." }
WordHunterWoW_QuestEN[93836] = { title = "The Fate of Zephras", description = "Muln has told me much of the elemental lords and I am afraid that we have good reason to fear Al'Akir. Now that the wards that have hidden Zephras from his view are down, we are utterly defenseless. If he chooses to attack us, we stand no chance against him here in his own domain.\n\nHigh Elder Shadowsong needs to know of the danger we are in, and more importantly, what our intentions are for our mission to Azeroth. We will find the means to save our home. I swear it.", objectives = "Speak with Talaanis Shadowsong in Valanaar.", completion = "<Talaanis Shadowsong listens intently as you tell him of what transpired above the Shrine of Akir, and of Ayessa's plan to leave Zephras Isle.>\n\nI need to reflect on this further, but looking at the upside, we have rid ourselves of Lorthuna and deprived the cult of their leader. Our home has not been invaded yet and on the timeline of elemental gods, it could be years... decades even, before Al'Akir deigns to turn his attention to us.\n\nThere is much to fear now, but much to celebrate as well." }
WordHunterWoW_QuestEN[93862] = { title = "Crate Return", description = "", objectives = "" }
WordHunterWoW_QuestEN[93926] = { title = "The Western Watch", description = "Whatever reason the cult has for attacking the tower, it's not worth losing our people over.\n\nI'd like for you to head to the southwest and check in on that watchtower for us. Find the peacekeepers there and tell them to head back to the village. Holding that tower is not worth the lives it would cost and I'd rather concentrate the defenders we do have here to protect our citizens.\n\nPeacekeeper Vaaniel is in charge, let him know to head back here as quickly as possible. Hurry!", objectives = "Find Peacekeeper Vaaniel at the western watchtower.", completion = "<The body here is somewhat fresh, clearly only recently having been killed. Judging by the burns and scorch marks on this peacekeeper's skin, its clear that they were killed by the cult's storm-wielding spellcasters.>" }
WordHunterWoW_QuestEN[93927] = { title = "A Last Request", description = "<As you inspect the body of the dead peacekeeper, a bloody note falls free of his hands. Picking it up and reading it may give you a clue as to how to proceed from here.>", objectives = "Collect the note you found near the dead peacekeeper and read it to determine your next steps.", progress = "What news from the western watch?", completion = "So they are all dead, then. Storms curse on these cult bastards!\n\nWhile you managed to take out the priest and stop the cultists at the tower, I confess that I'm now doubly concerned about whatever it was you said that they were doing to the pylon. The fact that there was such a massive cache of windstones there with them tells me that they needed enormous energy for it.\n\nI have to wonder, what's the end goal here? Violating the pylon, attacking the village? To what end?" }
WordHunterWoW_QuestEN[93928] = { title = "Of Mice and Milk", description = "I need a cookie, see? \n\nNyeah!", objectives = "Get the mouse a cookie.", completion = "(PH) Thanks!" }
WordHunterWoW_QuestEN[93948] = { title = "Deliver the Signet", description = "Since you are going to Valanaar anyway, please deliver the signet ring you recovered from the tower to Talaanis Shadowsong in Valanaar. \n\nHe will want this back, and more importantly, he will want to learn the fate of his nephew. Talaanis is the High Elder of Zephras Isle and more importantly, he is a good man who is well loved by the people, despite our current hardships. It pains me to think of how he will react to this news. Please express my condolences for his loss.", objectives = "Deliver the Shadowsong Family Signet to Talaanis Shadowsong in Valanaar.", progress = "What is that you have for me? Oh... oh no.", completion = "I... am very sorry to hear that my nephew is dead. I thank you kindly for recovering this, and bringing it to me.\n\nIt's not common that such capable young shen'dorei come down from the highlands. If you need work, please speak with Valennia Stormfist, the captain of the peacekeepers here in Valanaar. These days we need all the help we can get." }
WordHunterWoW_QuestEN[93949] = { title = "Bugged", description = "We've been bugged.\n\nIt's skyhopper season in the lowlands, which means the pests are everywhere. One of the High Order mages reported that one of the insects that they killed had an enchantment of some kind placed upon it. When we inspected it closely it seems to be some sort of listening spell.\n\nWe suspect that the cult is using these enchanted insects as spies. Go and exterminate them for us. You won't be able to tell which are enchanted by looking at them, so you'll just have to kill them all.", objectives = "Kill Skyhoppers in Valanaar until you've eliminated 8 Enchanted Skyhoppers.", completion = "I'm sure there are more of these critters around Valanaar, but every enchanted skyhopper we stomp out makes the city just a tiny bit safer." }
WordHunterWoW_QuestEN[93951] = { title = "A Little Beauty", description = "The Hippogryph that have taken up residence southwest of the village can be a nuisance, but they also present a rather unique opportunity to obtain their feathers. Many skyborne love to adorn their hair with vibrant plumes and the down feathers of a hippogryph are exceptionally vibrant and more importantly, silky soft.\n\nIf you are heading that way, try and gather as many of the fallen feathers as you can from in and around their nesting grounds. Do be careful, as wild hippogryph are not tolerant of guests.", objectives = "Collect 8 Hippogryph Down feathers in the Shen'dar Highlands.", progress = "What beautiful things did you bring me?", completion = "It might seem a bit of a vain triviality, gathering feathers for our hair. However, even in times like these, one needs to embrace the small joys as much as possible. \n\nIf one thing I create brings someone joy, then I will consider that to be a good day. Thank you for bringing me these and helping me bring some joy to Zephras." }
WordHunterWoW_QuestEN[93958] = { title = "The Inner Sanctum", description = "Valennia's forces just breached the inner sanctum. The fighting was thick in there at first, but it's grown... unsettlingly quiet. Go in there and do your best to link up with Valennia and her forces... if any of them are left.\n\nI'll stay here and watch your back.", objectives = "Speak with Valennia Stormfist inside the inner sanctum at the Shrine of Akir.", completion = "<Valennia looks gravely wounded.>" }
WordHunterWoW_QuestEN[93963] = { title = "Exploring the Alliance", description = "Stormwind, Ironforge, and Darnassus all have unique peoples and cultures. As a guest of the Alliance here on Azeroth, you should take some time to visit each of our capital cities in turn. \n\nSpeak with Randal Emerson in the southern antechamber for directions to get you started.", objectives = "Speak with Randal Emerson in Stormwind Keep to receive further instructions. Use the instructions received to locate and speak with King Magni Bronzebeard, High Tinker Mekkatorque, and Tyrande Whisperwind.", completion = "Ah, you are back.\n\nI hope your adventures have given you a sense of the scale and wonder of our world. I know it must seem overwhelming to you, but if you are to help your people, you must be prepared for whatever may come your way while you are on Azeroth.\n\nWhile you wait for your order to establish itself in Dalaran, I suggest you turn your attention to the lands around Stormwind. Westfall in particular can always use more strong adventurers to lend them aid, if you are willing." }
WordHunterWoW_QuestEN[94003] = { title = "The Skybreaker Bulwark", description = "I am all that remains of the line of Skybreakers here on Zephras Isle. The rest were murdered by the Al'Aketh.\n\nThe only thing that outweighs my sorrow is my shame. My family's ancestral shield--the Skybreaker Bulwark--is now in the hands of a cultist named Zaal Stormshield. Family lore holds no harm may befall a worthy wielder of this shield.\n\nZaal is not worthy, of that I am sure. Find this man at the Shrine of Akir and reclaim my shield from him. Do this and I will teach you the Skybreaker Defense.", objectives = "Reclaim the Skybreaker Bulwark from Zaal Stormshield at the Shrine of Akir.", progress = "<Seena nods curtly at you.>", completion = "You have done what I could not and restored my family honor. For this, I will bestow a gift that few on Zephras are worthy to receive. I will teach out the secrets of the Skybreaker Defense.\n\nAlso, you will need a shield to put what I have to teach you into practice. Please, take this one. I have little use for it now that the Skybreaker Bulwark has been returned to me.\n\nBanu'Adoraah, friend." }
WordHunterWoW_QuestEN[94004] = { title = "Craftsman's Writ: Elixir of Ogre's Strength", description = "<Penned in faded ink, the note is requesting X Elixir of Ogre's Strength, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Wut?", completion = "You brought da elixir!!\n\nT'anks, {race}. You come all this way to help Sos'mol. No ogre ever done that before.\n\nSos'mol will remember this. Pay you back someday. Me promise." }
WordHunterWoW_QuestEN[94006] = { title = "The Great Ursera Spirit", description = "Greetings, {name}. You have progressed in your druidic studies far enough that I think it is time for you to meet one of the great spirits that reside here on Zephras. Urs'endris is a wise and noble spirit, who has taught druids how to take on the ursera shape for generations. Unfortunately his domain has begun to wither and fall into the sky like many other areas of Zephras.\n\nTo find him, travel northeast near the waterfall in the shadow of the Shrine of Akir. He should be able to instruct you further.", objectives = "Speak with Urs'endris near the falls northeast of Valanaar.", completion = "So, you wish to embrace the way of the claw, child? Very well. Let us speak." }
WordHunterWoW_QuestEN[94007] = { title = "Taming the Beast", description = "Now that you've gained a level of comfort in the wilds of the highlands, I believe it is time for you to seek your very own animal companion.\n\nGo to the port of Valanaar to the southeast, and speak with Quel'ana Quickgale there. He will instruct you in the art of beast taming.", objectives = "Report to Quel'ana Quickgale in Valanaar.", completion = "I am most glad that you came. Come, let us begin." }
WordHunterWoW_QuestEN[94013] = { title = "Taming the Beast", description = "You've returned triumphant from taming two beasts, it's time now for your last trial. The winds of Zephras whisper of greater challenges ahead. \n\nTake this Taming Rod and journey to the Gustberry Lowlands. There, tame a Vuldren Alpha and prove your mastery. \n\nComplete this lesson and you'll be ready to learn the deeper ways of the hunter.", objectives = "Use the Taming Rod to tame a Vuldren Alpha in the Gustberry Lowlands. Practice your skills, then return the Taming Rod to Quel'ana Quickgale in Valanaar.", progress = "You will learn, {name}, and one day you will be a great {class}.", completion = "Excellent, {name}! You are quite a fast learner. Now that you know the basics, I can teach you how to forge a lasting bond with an animal companion.\n\nGo with this knowledge and thrive. Be the {class} that Zephras Isle needs you to be." }
WordHunterWoW_QuestEN[94050] = { title = "Training the Beast", description = "You now have the power to tame a pet, but you must also gain the skills to train it. For this, there is none better than my sister, Quel'dora. She will give you the ability to train your new pet. \n\nGo with the winds, young {class}.", objectives = "Speak to Quel'dora Quickgale in Valanaar.", completion = "A fledgling {class}, I see. Yes, I can bestow you with the skills you need to train and guide your pet. Not only will you be able to teach your pet new abilities, you will now be able to feed your pet, as well as revive it, should it fall in battle.\n\nRemember, {name}, always respect the balance and live in awe of nature around you. Now, go forth. We shall speak again, at a later date." }
WordHunterWoW_QuestEN[94212] = { title = "Craftsman's Writ: Elixir of Wisdom", description = "<Penned in faded ink, the note is requesting X Elixir of Wisdom, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Come, warm yourself by the fire.", completion = "I will admit, I expected the treacherous winds of the highlands to tear that letter to shreds. I had not imagined that someone would see my humble request, let alone deliver it straight to me.\n\nYour efforts are kind and admirable, {race}. I will use this to aid my meditation.\n\nFeel free to stay and share a tale or two of your travels. I enjoy the company." }
WordHunterWoW_QuestEN[94213] = { title = "Craftsman's Writ: Lesser Mana Potion", description = "<Penned in faded ink, the note is requesting X Lesser Mana Potion, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Good day, {race}. I appreciate the company but my attention is elsewhere. If we do not have business, please be on your way.", completion = "Ah, is this the potion I requested?\n\n<The elven woman respectfully takes the vial from you.>\n\nYour arrival is timely, and generosity deeply appreciated. I accept this, and offer you a small token of my gratitude.\n\nThank you, may we meet again." }
WordHunterWoW_QuestEN[94214] = { title = "Craftsman's Writ: Shadow Protection Potion", description = "<Penned in faded ink, the note is requesting X Shadow Protection Potion, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94215] = { title = "Craftsman's Writ: Free Action Potion", description = "<Penned in faded ink, the note is requesting X Free Action Potion, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "<You approach a thrashing creature clearly trapped in spider silk, exactly where the writ marked on the map.>", completion = "<You waste little time offering the wiggling mass the Free Action Potion that was requested. It seems either unaware of your presence, or unable to claim the item.\n\nA handful of coins are scattered just beside the cocoon. You may decide to leave the potion there, and take the coins for yourself. Nature will surely sort itself out, in that case.>" }
WordHunterWoW_QuestEN[94216] = { title = "Craftsman's Writ: Elixir of Lesser Agility", description = "<Penned in faded ink, the note is requesting X Elixir of Lesser Agility, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Are you here about...\n\n<Ziz looks around his tiny hut suspiciously, and lowers his voice.>\n\nThe elixir?", completion = "<Ziz continues to talk in a hushed tone.>\n\nI'm not about to give you the whole spiel about how I got into this position, but here's some advice for you.\n\nSometimes, all you gotta do to impress your new boss is take credit for someone else's work. So you're going to hand over the elixir, and I am gonna talk about how much blood, sweat, and tears I poured into making it.\n\nIt's a new gig, okay? I need to make a good first impression!" }
WordHunterWoW_QuestEN[94217] = { title = "Craftsman's Writ: Lesser Troll's Blood Elixir", description = "<Penned in faded ink, the note is requesting X Lesser Troll's Blood Elixir, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Yarr, you be bringin' me my elixir?", completion = "Exactly what Short John Mithril ordered!\n\nHere's ye' coin. I'd keep it clutched to your chest as ye' scuttle out of here, the arena combatants thirst for riches as much as they thirst for blood!" }
WordHunterWoW_QuestEN[94218] = { title = "Craftsman's Writ: Elixir of Defense", description = "<Penned in faded ink, the note is requesting X Elixir of Defense, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94219] = { title = "Craftsman's Writ: Draught of Water Breathing", description = "<Penned in faded ink, the note is requesting X Draught of Water Breathing, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94220] = { title = "Craftsman's Writ: Pearl-Handled Dagger", description = "<Penned in faded ink, the note is requesting X Pearl-Handled Dagger, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "It is unwise to sneak up on me, {race}. Speak quickly, and speak quietly.", completion = "Oh, you are delivering my dagger? Hah, I suppose my threat rang quite hollow then, hm?\n\nI must stay on high alert given my duties here, and especially with oth-- ahem, the foul Syndicate roaming about elsewhere here.\n\nWould you be so kind as to part with the blade, now? I must get back to my task." }
WordHunterWoW_QuestEN[94221] = { title = "Craftsman's Writ: Golden Rod", description = "<Penned in faded ink, the note is requesting X Golden Rod, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "<The dwarf seems to be in a deep state of meditation, though your approach interrupted his focus. Fortunately, a smile greets you.>", completion = "Ah, the Golden Rod I requested. I never expected it to arrive. I was considering going back to Ironforge to purchase one off the auction house. You saved me a trip, something these old feet greatly thank you for.\n\nI do not yet know how I can use this to commune with the Binding Stones, let alone if I even can, but I suspect this brings me one step closer.\n\nIn the worst case, well, I am happy to have a new cane." }
WordHunterWoW_QuestEN[94222] = { title = "Craftsman's Writ: Iridescent Hammer", description = "<Penned in faded ink, the note is requesting X Iridescent Hammer, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94223] = { title = "Craftsman's Writ: Silver Skeleton Key", description = "<Penned in faded ink, the note is requesting X Silver Skeleton Key, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "<After following the instructions on the writ, you find yourself deep in a crypt surrounded by undead. There is a note on a nearby trunk.>\n\nWhomever first reads this will be the first to learn of my death. I am a mere caretaker of the Raven Hill Cemetery, whose presence is largely forgotten by even his employers at Darkshire. I have no heir with which to bestow my vast wealth unto. I have since stashed them away, in this box, for who or whatever manages to open it.", completion = "<With the undead hordes endlessly gathering nearby and no sign of others, you choose to make use of your Silver Skeleton Key to effortlessly open the chest.\n\nDespite the claims of impressive riches, the trunk is nearly empty. At the very least there is enough present to cover some of the cost of this ordeal.>" }
WordHunterWoW_QuestEN[94224] = { title = "Craftsman's Writ: Heavy Bronze Mace", description = "<Penned in faded ink, the note is requesting X Heavy Bronze Mace, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Shh. Keep your voice down. I'm not ready for a fight, yet.", completion = "Whoa. You came well prepared! Hope that mace is for me, unless you plan to do ALL of the fighting." }
WordHunterWoW_QuestEN[94225] = { title = "Craftsman's Writ: Rough Bronze Leggings", description = "<Penned in faded ink, the note is requesting X Rough Bronze Leggings, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "What's up?", completion = "These are the leggings I ordered, huh? \"Three to five business days,\" they said. More like three to five business MONTHS!\n\nI submitted this when I was working for the Venture Co out there, and let me just say, that partnership is well over with, so we can consider this order expired.\n\nWhy aren't you leaving yet? Ugh, fine! Here's your payment." }
WordHunterWoW_QuestEN[94226] = { title = "Craftsman's Writ: Green Iron Gauntlets", description = "<Penned in faded ink, the note is requesting X Green Iron Gauntlets, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94227] = { title = "Craftsman's Writ: Big Bronze Knife", description = "<Penned in faded ink, the note is requesting X Big Bronze Knife, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "<The chicken... clears its throat?>\n\nCluck, cluck.", completion = "Cluck? CLUCK CLUCK! BWOK!\n\n<The chicken glares menacingly toward Magus Tirth from afar, newly acquired blade in beak.>" }
WordHunterWoW_QuestEN[94228] = { title = "Craftsman's Writ: Green Iron Boots", description = "<Penned in faded ink, the note is requesting X Green Iron Boots, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Please tell me you're the one with the boots...", completion = "At last! I've been stomping around the wetlands with soggy feet for days!\n\nHopefully these aren't prone to rusting either. I trust you know what you're doing." }
WordHunterWoW_QuestEN[94229] = { title = "Craftsman's Writ: Ornate Spyglass", description = "<Penned in faded ink, the note is requesting X Ornate Spyglass, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Whoa! I almost didn't see you there. I might have seen you coming sooner if a damned engineer would at last deliver my order.", completion = "Oh. Oh! You're the engineer? I suppose at the very least you are the delivery boy in any case.\n\nPlease hand over the spyglass. I have little time and many things to inspect." }
WordHunterWoW_QuestEN[94230] = { title = "Craftsman's Writ: Explosive Sheep", description = "<Penned in faded ink, the note is requesting X Explosive Sheep, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94231] = { title = "Craftsman's Writ: Moonsight Rifle", description = "<Penned in faded ink, the note is requesting X Moonsight Rifle, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Hey, HEY, man, haven't you heard of a little thing called \"subtlety\"? Spell it out with me, S-U-B...LETY. You're going to blow my cover!", completion = "Ohoho, I take it back. Look at this beautiful boomstick. I bet it'll knock a satyr's head clean off.\n\nThanks pal, now step aside or you're going to get caught in the crossfire." }
WordHunterWoW_QuestEN[94232] = { title = "Craftsman's Writ: Minor Recombobulator", description = "<Penned in faded ink, the note is requesting X Minor Recombobulator, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", completion = "I don't know what I expected when I sent out an order for a curse dispelling device, but this Minor Recon--Racom--ugh, Minor Whatchamacallit sure ain't it!\n\nLook, I know how complicated the refund process is and I do NOT have time for that. It's way easier for us both if I just take this off your hands, and I'll be more specific with my next order.\n\nFor both of our sakes, let's hope you don't screw that one up too!" }
WordHunterWoW_QuestEN[94233] = { title = "Craftsman's Writ: Practice Lock", description = "<Penned in faded ink, the note is requesting X Practice Lock, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "I watched this whole place get burned to the ground and that keep toppled over. It was glorious.\n\nNever expected a group of bandits try to use this place as a base of operations.", completion = "Ahh, my practice lock has arrived.\n\nThe Syndicate here have been plotting to turn this place into a prison like it once was. I already know that at least one orc is currently being held here. Maybe more. I don't intend to be another, but I intend to be more prepared than the last time if they catch me off guard." }
WordHunterWoW_QuestEN[94234] = { title = "Craftsman's Writ: Shadow Goggles", description = "<Penned in faded ink, the note is requesting X Shadow Goggles, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Hey! Watch where you're walking!", completion = "My new shadow goggles!\n\n<Without another word, the goblin tossed a handful of coins your way with one hand while the other swiped the item out of your grasp. The transaction was completed and his attention lost before you had a moment to process what happened.>" }
WordHunterWoW_QuestEN[94235] = { title = "Craftsman's Writ: Gnomish Universal Remote", description = "<Penned in faded ink, the note is requesting X Gnomish Universal Remote, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Careful where you walk, Gizmo! This thing likes to activate when you least expect it, and we don't quite have a handle on where it can take you when we aren't actively manning the controls.", completion = "Seems we are in luck, the remote has arrived! Looks like you precalibrated it for us which, I'll admit, isn't ideal for this scenario.\n\nI should be able to reverse engineer it in no time. Then maybe, hopefully, I'll be able to take a much needed break. Feels like I've been stuck fumbling with this teleporter's controls for months on end!" }
WordHunterWoW_QuestEN[94236] = { title = "Craftsman's Writ: Big Bronze Bomb", description = "<Penned in faded ink, the note is requesting X Big Bronze Bomb, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "You got the stuff?", completion = "Hey, there's the bomb I ordered!\n\nWell, one of them anyway. I needed a variety pack! You know, enough so I can test each one for effectiveness AND have a few leftover for my own needs!\n\nWell, whatever. Here's a cut of your cut, I'll give you the rest when you bring ME my full order!" }
WordHunterWoW_QuestEN[94237] = { title = "Craftsman's Writ: Crafted Solid Shot", description = "<Penned in faded ink, the note is requesting X Crafted Solid Shot, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94238] = { title = "Craftsman's Writ: Heavy Leather Ball", description = "<Penned in faded ink, the note is requesting X Heavy Leather Ball, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94239] = { title = "Craftsman's Writ: Fine Leather Pants", description = "<Penned in faded ink, the note is requesting X Fine Leather Pants, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Move along, please, and try not to draw attention to us.", completion = "Oh! The pants? Ah, I realized shortly after writing this that I needed a full set of clothes - new overalls included.\n\nIf it will get you out of my hair, I suppose I should honor the request. After all, you did make an arduous journey to find me.\n\nTake this, now please...\n\n<She gestured in a polite but firm shooing motion.>" }
WordHunterWoW_QuestEN[94240] = { title = "Craftsman's Writ: Herbalist's Gloves", description = "<Penned in faded ink, the note is requesting X Herbalist's Gloves, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94241] = { title = "Craftsman's Writ: Dark Leather Tunic", description = "<Penned in faded ink, the note is requesting X Dark Leather Tunic, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "WHAT???", completion = "Oh your timing is impeccable!\n\nCallahan! Your new shirt arrived. Hurry up and change so I can stop hearing about how itchy you are all the time.\n\nAnd for you, {race}. Here is your payment. Before you wander off, you should take a look at my wares now that you can afford 'em!" }
WordHunterWoW_QuestEN[94242] = { title = "Craftsman's Writ: Pilferer's Gloves", description = "<Penned in faded ink, the note is requesting X Pilferer's Gloves, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94243] = { title = "Craftsman's Writ: Heavy Quiver", description = "<Penned in faded ink, the note is requesting X Heavy Quiver, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Need some work?", completion = "I--Hmm.\n\nI don't remember why I ordered this.\n\n<Ziz shrugs and tosses the quiver into a nearby pile of junk.>" }
WordHunterWoW_QuestEN[94244] = { title = "Craftsman's Writ: Dark Leather Shoulders", description = "<Penned in faded ink, the note is requesting X Dark Leather Shoulders, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Yarr, what business do ye' have with ol' Narkk?", completion = "Thar be me shoulderpads, at last!\n\nEver had one of these squakers perch on your shoulder? Bet ye' haven't! Their claws, they hurt!\n\nNow they got a place to rest all day, and you have a heavier coinpurse!\n\n<Narkk eyes said coinpurse.>\n\nFor now!" }
WordHunterWoW_QuestEN[94245] = { title = "Craftsman's Writ: Barbaric Gloves", description = "<Penned in faded ink, the note is requesting X Barbaric Gloves, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94246] = { title = "Craftsman's Writ: Red Whelp Gloves", description = "<Penned in faded ink, the note is requesting X Red Whelp Gloves, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94247] = { title = "Craftsman's Writ: Lesser Wizard's Robe", description = "<Penned in faded ink, the note is requesting X Lesser Wizard's Robe, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "<The man stands at attention, peering over the mountainside toward Dalaran. He regards your presence with a subtle wave of a hand, beckoning you closer.>", completion = "<Alan speaks in a whisper.>\n\nDon't you think it is a little suspicious to be carrying elegant robes in broad daylight to a man garbed in dark leathers?\n\nWell, ahem, fortunately I am out here on behalf of the Kirin Tor, so there is no shady transaction about to take place. None at all.\n\nThe robe, please." }
WordHunterWoW_QuestEN[94248] = { title = "Craftsman's Writ: Blue Overalls", description = "<Penned in faded ink, the note is requesting X Blue Overalls, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Oh! Please keep your voice down, we don't need to draw any further attention to ourselves.\n\nDo you have something for me?", completion = "The Blue Overalls! Thank goodness, I have a proper change of clothes.\n\nTake this, and please be on your way. I do not have time to chat, I must keep an eye on the farm and can't risk more distractions." }
WordHunterWoW_QuestEN[94249] = { title = "Craftsman's Writ: Azure Silk Hood", description = "<Penned in faded ink, the note is requesting X Azure Silk Hood, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "AHHHH! Oh, it just a {race}.\n\nHi {race}!", completion = "It da hood me order-er-ed!\n\nMe forgot why wanted in first place, but me take anyway.\n\nHere, take shiny coin. It fell out of slime monster. Lots and lots of them!" }
WordHunterWoW_QuestEN[94250] = { title = "Craftsman's Writ: Small Silk Pack", description = "<Penned in faded ink, the note is requesting X Small Silk Pack, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Yo! Is that pack for me?", completion = "Ha ha! Thanks, pal. I owe you.\n\n<Kzixx reaches into a Small Silk Pack already in his possession, filled to the brim with coin, and pulls out a fist full. He counts out a tiny fraction of his total wealth, and hands it to you.>\n\nThis should cover it. No take-backs!" }
WordHunterWoW_QuestEN[94251] = { title = "Craftsman's Writ: Phoenix Pants", description = "<Penned in faded ink, the note is requesting X Phoenix Pants, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94252] = { title = "Craftsman's Writ: Red Woolen Boots", description = "<Penned in faded ink, the note is requesting X Red Woolen Boots, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94253] = { title = "Craftsman's Writ: Colorful Kilt", description = "<Penned in faded ink, the note is requesting X Colorful Kilt, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
WordHunterWoW_QuestEN[94254] = { title = "Craftsman's Writ: Greater Adept's Robe", description = "<Penned in faded ink, the note is requesting X Greater Adept's Robe, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "<Magus Tirth begins to cast Polymorph: Chicken on you.>", completion = "My new robe! Delightful!\n\nAt long last, I can don my robe AND my wizard hat." }
WordHunterWoW_QuestEN[94255] = { title = "Craftsman's Writ: Spider Silk Slippers", description = "<Penned in faded ink, the note is requesting X Spider Silk Slippers, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction.", progress = "Yo!", completion = "Are these my new boots?\n\n<Kixxle looks very excited, but it fades immediately upon setting his eyes upon them.>\n\nAh. I thought I had cancelled the order for slippers once I realized how foolish it would be to trudge around a swamp with my toes hanging out. I ordered a new pair of proper boots too, but they still haven't arrived yet.\n\nOh well, pleasure doing business with you. I'll keep these for later!" }
WordHunterWoW_QuestEN[94256] = { title = "Craftsman's Writ: Frost Protection Potion", description = "<Penned in faded ink, the note is requesting X Frost Protection Potion, along with information about delivery location and payment.  At the bottom appears text denoting this writ is transferable.>", objectives = "Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction." }
